inline bool ieq(std::string_view a, std::string_view b) {
    if(a.size() != b.size()) return false;

    for(size_t i = 0; i < a.size(); ++i) {
        unsigned char ca = static_cast<unsigned char>(a[i]);
        unsigned char cb = static_cast<unsigned char>(b[i]);
        if('A' <= ca && ca <= 'Z') ca = static_cast<unsigned char>(ca - 'A' + 'a');
        if('A' <= cb && cb <= 'Z') cb = static_cast<unsigned char>(cb - 'A' + 'a');
        if(ca != cb) return false;
    }
    return true;
}

template <class T>
inline bool to_number(std::string_view sv, T& out) {
    static_assert(
        ((std::is_integral_v<T> && !std::is_same_v<T, bool>) ||
         std::is_floating_point_v<T>),
        "T must be non-bool integral or floating point");

    if(sv.empty()) return false;

    // True/False -> 1/0
    if(ieq(sv, "True")) {
        out = static_cast<T>(1);
        return true;
    }
    if(ieq(sv, "False")) {
        out = static_cast<T>(0);
        return true;
    }

    if constexpr (std::is_integral_v<T>) {
        // 16進: 0x12ab / 0X12AB
        if (sv.size() > 2 && sv[0] == '0' && (sv[1] == 'x' || sv[1] == 'X')) {
            auto r = std::from_chars(sv.data() + 2, sv.data() + sv.size(), out, 16);
            return r.ec == std::errc{} && r.ptr == sv.data() + sv.size();
        }

