#include "trace.h"

#include <sys/time.h>
#include <cstdio>
#include <cstdarg>
#include <cstring>
#include <ctime>
#include <mutex>
#include <string>

static int g_trace_level = 0;
static std::string g_trace_id;
static std::mutex g_trace_mutex;

void set_trace_id(const char *id) {
	g_trace_id = id;
}

void set_trace_level(int level) {
	g_trace_level = level;
}

int trace(int level, const char *fmt, ...) {
	if(level > g_trace_level) {
		return -1;
	}

	g_trace_mutex.lock();

	timespec ts;
	clock_gettime(CLOCK_REALTIME, &ts);

	std::tm *ptm = std::localtime(&ts.tv_sec);

	char work[2048];
	int header_length = std::snprintf(work, sizeof(work), "%04d-%02d-%02dT%02d:%02d:%02d.%03d%+03d:%02d,%s,%d,",
	                                  ptm->tm_year + 1900, ptm->tm_mon + 1, ptm->tm_mday,
	                                  ptm->tm_hour, ptm->tm_min, ptm->tm_sec, (int)(ts.tv_nsec / 1000000),
	                                  (int)(ptm->tm_gmtoff / 3600), (int)(ptm->tm_gmtoff % 3600) / 60,
	                                  g_trace_id.c_str(),
	                                  level);

	std::va_list ap;
	va_start(ap, fmt);
	std::vsnprintf(work + header_length, sizeof(work) - header_length, fmt, ap);
	va_end(ap);

	std::fprintf(stderr, "%s\n", work);
	std::fflush(stderr);

	g_trace_mutex.unlock();

	return 0;
}

