		auto sr = m_seq_stats.update(ex.ext_seq);

		if(sr.duplicate) {
			trace(1, "%s duplicate seq=%u",
			      to_string(i.dst).c_str(),
			      static_cast<unsigned>(i.seq));
		}

		if(sr.reordered) {
			trace(1, "%s reordered seq=%u",
			      to_string(i.dst).c_str(),
			      static_cast<unsigned>(i.seq));
		}

		if(sr.gap_added > 0) {
			trace(1, "%s gap +%llu seq=%u",
			      to_string(i.dst).c_str(),
			      static_cast<unsigned long long>(sr.gap_added),
			      static_cast<unsigned>(i.seq));
		}
	}

	auto tx = m_ts_ext.update(i.timestamp);
	auto sr = m_skew.update(i.time_epoch, tx.ext_ts);
	if(sr.updated) {
		trace(1, "%s elapsed=%f observed_rate=%f skew=%f ppm",
		      to_string(i.dst).c_str(),
		      sr.elapsed_sec,
		      sr.observed_rate,
		      sr.skew_ppm);
	}

	return 0;
}

