例えばこうです。

```cpp
struct dispatch_rule {
    std::string_view proto;
    streams* target;
};

std::array<dispatch_rule, 4> rules = {{
    {"SRT",     m_srt.get()},
    {"MPEG TS", m_rtp.get()},
    {"RTP",     m_rtp.get()},
    {"HTTP",    m_hls.get()},
}};
