class counter {
public:
    struct result {
        std::uint64_t count{0};
    };

public:
    void reset() {
        count_ = 0;
    }

    void inc() {
        ++count_;
    }

    void add(std::uint64_t n) {
        count_ += n;
    }

    void add(bool cond) {
        if (cond) {
            ++count_;
        }
    }

    bool empty() const {
        return count_ == 0;
    }

    std::uint64_t count() const {
        return count_;
    }

    result value() const {
        return result{ .count = count_ };
    }

private:
    std::uint64_t count_{0};
