    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    result update(double time_epoch) {
        result r{};

        if (prev_time_ >= 0.0) {
            const double d = time_epoch - prev_time_;
            if (d >= 0.0) {
                interval_sec_ = d;
                stats_.add(interval_sec_);

                r.updated = true;
                r.seconds = interval_sec_;
            }
        }

        prev_time_ = time_epoch;
        return r;
    }

    double value() const { return interval_sec_; }
    const value_stats& stats() const { return stats_; }

private:
    double prev_time_{-1.0};
    double interval_sec_{0.0};
    value_stats stats_{};
};

class sequence_stats {
public:
    struct update_result {
        bool updated{false};
        std::uint64_t seq{0};

        bool duplicate{false};
        bool reordered{false};
        std::uint64_t gap_added{0};
    };

public:
    void reset() {
        initialized_ = false;
        last_seq_ = 0;
        gap_count_.reset();
        reorder_count_.reset();
        dup_count_.reset();
    }

    void reset_stats() {
        gap_count_.reset();
        reorder_count_.reset();
        dup_count_.reset();
    }

    update_result update(std::uint64_t seq) {
        update_result r{};
        r.updated = true;
        r.seq = seq;

        if (!initialized_) {
            initialized_ = true;
            last_seq_ = seq;
            return r;
        }

        if (seq == last_seq_) {
            dup_count_.inc();
            r.duplicate = true;
            return r;
        }

        if (seq == last_seq_ + 1) {
            last_seq_ = seq;
            return r;
        }

        if (seq > last_seq_ + 1) {
            const std::uint64_t gap = seq - last_seq_ - 1;
            gap_count_.add(gap);
            r.gap_added = gap;
            last_seq_ = seq;
            return r;
        }

        reorder_count_.inc();
        r.reordered = true;
        return r;
    }

    const counter& gap_count() const {
        return gap_count_;
    }

    const counter& reorder_count() const {
        return reorder_count_;
    }

    const counter& dup_count() const {
        return dup_count_;
    }

    std::uint64_t last_seq() const {
        return last_seq_;
    }

    bool initialized() const {
        return initialized_;
    }

private:
    bool initialized_{false};
    std::uint64_t last_seq_{0};

    counter gap_count_;
    counter reorder_count_;
    counter dup_count_;
};

class bitrate {
public:
    struct result {
        bool updated{false};
        double bps{0.0};
        double elapsed{0.0};
    };

public:
    void reset_window() {
        current_time_ = -1.0;
        rec_bytes_ = 0;
        bitrate_bps_ = 0.0;
    }

    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    result update(double time_epoch, std::uint64_t frame_len) {
        result r{};

        if (current_time_ < 0.0) {
            current_time_ = time_epoch;
        }

        const std::int64_t now_sec = static_cast<std::int64_t>(time_epoch);
        const std::int64_t cur_sec = static_cast<std::int64_t>(current_time_);

        if (now_sec > cur_sec) {
            const double elapsed = time_epoch - current_time_;

            if (elapsed > 0.0) {
                bitrate_bps_ = static_cast<double>(rec_bytes_) * 8.0 / elapsed;
                stats_.add(bitrate_bps_);

                r.updated = true;
                r.bps = bitrate_bps_;
                r.elapsed = elapsed;
            }

            current_time_ = time_epoch;
            rec_bytes_ = 0;
        }

        rec_bytes_ += frame_len;
        return r;
    }

    double value() const { return bitrate_bps_; }
    const value_stats& stats() const { return stats_; }

private:
    double current_time_{-1.0};
    std::uint64_t rec_bytes_{0};
    double bitrate_bps_{0.0};
    value_stats stats_{};
};

