namespace srt {

flow::flow(const flow_id fid)
	: m_fid(std::move(fid)) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_counts.update(i.iscontrol != 0, i.msg_rexmit != 0);

	if(i.iscontrol != 0) {
		m_metrics.control_types.update(i.type);
		if(i.type == 0x0003) {
			m_metrics.nak_seq_stats.add(static_cast<double>(i.nak_seqno));
		}
	}
	else {
		m_metrics.seq_stats.update(i.seqno);
	}

	if(i.rtt > 0) {
		m_metrics.rtt.update(static_cast<double>(i.rtt));
	}
	if(i.rttvar > 0) {
		m_metrics.rttvar.update(static_cast<double>(i.rttvar));
	}
	if(i.rate > 0) {
		m_metrics.rate.update(static_cast<double>(i.rate));
	}
	if(i.rcvrate > 0) {
		m_metrics.rcvrate.update(static_cast<double>(i.rcvrate));
	}
	if(i.bw > 0) {
		m_metrics.bw.update(static_cast<double>(i.bw));
	}

	return 0;
}

int flow::flush_metrics(double now, writer &w) {
	(void)now;
	(void)w;

	flow_metrics &m = m_metrics;

	json j{
		{"endpoint", {
			{"src", to_string(m_fid.src)},
			{"dst", to_string(m_fid.dst)},
		}},
		{"bitrate", {
			{"bps", m.bitrate.value()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
		}},
		{"packet_count", {
			{"total", m.packet_counts.total().count()},
			{"data", m.packet_counts.data().count()},
			{"control", m.packet_counts.control().count()},
			{"retransmit", m.packet_counts.retransmit().count()},
		}},
		{"control_type_count", {
			{"total", m.control_types.total().count()},
			{"handshake", m.control_types.handshake().count()},
			{"keepalive", m.control_types.keepalive().count()},
			{"ack", m.control_types.ack().count()},
			{"nak", m.control_types.nak().count()},
			{"shutdown", m.control_types.shutdown().count()},
			{"ackack", m.control_types.ackack().count()},
			{"dropreq", m.control_types.dropreq().count()},
			{"peer_error", m.control_types.peer_error().count()},
			{"user_defined", m.control_types.user_defined().count()},
			{"other", m.control_types.other().count()},
		}},
		{"count", {
			{"gap", m.seq_stats.gap_count().count()},
			{"dup", m.seq_stats.dup_count().count()},
			{"reorder", m.seq_stats.reorder_count().count()},
		}},
		{"rtt", {
			{"value", m.rtt.value()},
			{"count", m.rtt.stats().count},
			{"min", m.rtt.stats().min},
			{"max", m.rtt.stats().max},
			{"avg", m.rtt.stats().avg()},
		}},
		{"rttvar", {
			{"value", m.rttvar.value()},
			{"count", m.rttvar.stats().count},
			{"min", m.rttvar.stats().min},
			{"max", m.rttvar.stats().max},
			{"avg", m.rttvar.stats().avg()},
		}},
		{"rate", {
			{"value", m.rate.value()},
			{"count", m.rate.stats().count},
			{"min", m.rate.stats().min},
			{"max", m.rate.stats().max},
			{"avg", m.rate.stats().avg()},
		}},
		{"rcvrate", {
			{"value", m.rcvrate.value()},
			{"count", m.rcvrate.stats().count},
			{"min", m.rcvrate.stats().min},
			{"max", m.rcvrate.stats().max},
			{"avg", m.rcvrate.stats().avg()},
		}},
		{"bandwidth", {
			{"value", m.bw.value()},
			{"count", m.bw.stats().count},
			{"min", m.bw.stats().min},
			{"max", m.bw.stats().max},
			{"avg", m.bw.stats().avg()},
		}},
		{"nak_seqno", {
			{"count", m.nak_seq_stats.count},
			{"min", m.nak_seq_stats.min},
			{"max", m.nak_seq_stats.max},
			{"avg", m.nak_seq_stats.avg()},
		}},
	};

	m.bitrate.clear_stats();
	m.interval.clear_stats();
	m.seq_stats.reset_stats();
	m.nak_seq_stats.clear();
	m.packet_counts.reset();
	m.control_types.reset();
	m.rtt.clear_stats();
	m.rttvar.clear_stats();
	m.rate.clear_stats();
	m.rcvrate.clear_stats();
	m.bw.clear_stats();

	std::fprintf(stderr, "%s\n", j.dump(2).c_str());

	return 0;
}

stream::stream(const stream_id sid)
	: m_sid(std::move(sid)) {
}

int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid{
		.src = {i.src.addr, i.src.port},
		.dst = {i.dst.addr, i.dst.port}
	};

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(fid)).first;
	}

	return it->second->process(i);
}

int stream::flush_metrics(double now, writer &w) {
	for(auto& [fid, flow] : m_flows) {
		flow->flush_metrics(now, w);
	}

	return 0;
}

void stream::expire_flows(double now) {
    for(auto it = m_flows.begin(); it != m_flows.end(); ) {
        if (it->second->expired(now, k_flow_idle_timeout_sec)) {
            it = m_flows.erase(it);
        }
        else {
            ++it;
        }
    }
}

streams::streams() {
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}

	expire_streams(i.time_epoch);

	stream_id sid = make_stream_id(i.src.addr, i.src.port,
	                               i.dst.addr, i.dst.port,
	                               i.hs_sid);
	auto it = m_streams.find(sid);
	if (it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid)).first;
	}

	return it->second->process(i);
}

int streams::flush_metrics(double now, writer &w) {
	for(auto& [sid, stream] : m_streams) {
		stream->flush_metrics(now, w);
	}

	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	parse_ip(row[c.i.com.ip_src], i.src.addr);
	parse_ip(row[c.i.com.ip_dst], i.dst.addr);
	tsv::to_number(row[c.i.com.udp_srcport], i.src.port);
	tsv::to_number(row[c.i.com.udp_dstport], i.dst.port);

	tsv::to_number(row[c.i.com.time_epoch],  i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],   i.frame_len);
	tsv::to_number(row[c.i.srt.iscontrol],   i.iscontrol);
	tsv::to_number(row[c.i.srt.type],        i.type);
	tsv::to_number(row[c.i.srt.seqno],       i.seqno);
	tsv::to_number(row[c.i.srt.msg_rexmit],  i.msg_rexmit);
	tsv::to_number(row[c.i.srt.msg_order],   i.msg_order);
	tsv::to_number(row[c.i.srt.nak_seqno],   i.nak_seqno);
	tsv::to_number(row[c.i.srt.rtt],         i.rtt);
	tsv::to_number(row[c.i.srt.rttvar],      i.rttvar);
	tsv::to_number(row[c.i.srt.rate],        i.rate);
	tsv::to_number(row[c.i.srt.rcvrate],     i.rcvrate);
	tsv::to_number(row[c.i.srt.bw],          i.bw);
	tsv::to_number(row[c.i.srt.timestamp],   i.timestamp);
	tsv::to_string(row[c.i.srt.hs_sid],      i.hs_sid);

	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now);

		if(it->second->empty() &&
		    it->second->expired(now, k_stream_idle_timeout_sec)) {
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

