int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}

    expire_pending(i.time_epoch);
    expire_streams(i.time_epoch);

    stream_id sid = make_stream_id(i.ip_proto,
                                   i.src.addr, i.src.port,
                                   i.dst.addr, i.dst.port);

// std::cerr << m_streams.size() << std::endl;

    // すでに本streamならそのまま処理
    auto it = m_streams.find(sid);
    if (it != m_streams.end()) {
        return it->second->process(i);
    }

    // pending にあれば 2回目なので stream に昇格
    auto pit = m_pending.find(sid);
    if (pit != m_pending.end()) {
        auto s = std::make_unique<stream>(sid);

        // 初回パケットぶんは stream 側に入っていないので、
        // 必要なら pending の packets/bytes を stream に引き継ぐ仕組みを後で足す
        // まずは「2回目以降だ stream 化」で最小にする
        int rc = s->process(i);

        m_streams.emplace(sid, std::move(s));
        m_pending.erase(pit);
        return rc;
    }

    // 初回観測なので pending に置くだけ
    pending_stream ps;
    ps.add(i);
    m_pending.emplace(sid, std::move(ps));

    return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	parse_ip(row[c.i.com.ip_src], i.src.addr);
	parse_ip(row[c.i.com.ip_dst], i.dst.addr);
	tsv::to_number(row[c.i.com.udp_srcport], i.src.port);
	tsv::to_number(row[c.i.com.udp_dstport], i.dst.port);
	tsv::to_number(i.src.addr.is_v6 ?
	               row[c.i.com.ipv6_nxt] : row[c.i.com.ip_proto], i.ip_proto);
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);

	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now);

		if(it->second->empty() &&
		    it->second->expired(now, k_stream_idle_timeout_sec)) {
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

void streams::expire_pending(double now) {
    for(auto it = m_pending.begin(); it != m_pending.end(); ) {
        if((now - it->second.last_seen) >= k_pending_timeout_sec) {
            ++m_other_oneshot_flows;
            m_other_oneshot_packets += it->second.packets;
            m_other_oneshot_bytes   += it->second.bytes;
            it = m_pending.erase(it);
        }
        else {
            ++it;
        }
    }
}

}

