  "proto": "RTP",
  "stream": {
    "session_dst": "239.1.1.1:5004",
    "flows": [
      {
        "role": "main",
        "ssrc": 1001,
        "payload_type": 33,
        "endpoint": { "src": "...", "dst": "..." }
      },
