flow_id stream::resolve_flow_id(const info &i) const {
	const std::uint16_t offset = static_cast<std::uint16_t>(i.dst.port - m_sid.session_dst.port);
	flow_role role = flow_role::unknown;

	switch(offset) {
	case 0: role = flow_role::main; break;
	case 2: role = flow_role::fec_row; break;
	case 4: role = flow_role::fec_col; break;
	default: role = flow_role::unknown; break;
	}

	return make_flow_id(role,
	                   i.src.addr, i.src.port,
	                   i.dst.addr, i.dst.port,
	                   i.ssrc,
	                   i.p_type);
}

