    for(auto it = m_pending.begin(); it != m_pending.end(); ) {
        if((now - it->second.last_seen) >= k_pending_timeout_sec) {
            ++m_other_oneshot_flows;
            m_other_oneshot_packets += it->second.packets;
            m_other_oneshot_bytes   += it->second.bytes;
            it = m_pending.erase(it);
