+        }
+
+        if (seq == last_seq_ + 1) {
+            last_seq_ = seq;
+            return r;
+        }
+
+        if (seq > last_seq_ + 1) {
+            const std::uint64_t gap = seq - last_seq_ - 1;
+            gap_count_.add(gap);
