struct stream_id {
    ip_endpoint endpoint_a;
    ip_endpoint endpoint_b;
    std::string streamid;

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id &v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_a));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint_b));
        hash_combine(h, std::hash<std::string>{}(v.streamid));
        return h;
    }
};

enum class flow_role : std::uint8_t {
    data,
    control,
    mixed,
    unknown,
};

inline const char* to_string(flow_role role) noexcept {
    switch(role) {
    case flow_role::data: return "data";
    case flow_role::control: return "control";
    case flow_role::mixed: return "mixed";
    default: return "unknown";
    }
}

struct flow_id {
    ip_endpoint src;
    ip_endpoint dst;

    bool operator==(const flow_id&) const = default;
};

struct flow_id_hash {
    std::size_t operator()(const flow_id &v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, ip_endpoint_hash{}(v.src));
        hash_combine(h, ip_endpoint_hash{}(v.dst));
        return h;
    }
};

inline stream_id make_stream_id(
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port,
    std::string_view streamid_sv
) {
    auto ep = normalize_endpoints(src_ip, src_port, dst_ip, dst_port);
    return stream_id{
        .endpoint_a = std::move(ep.a),
        .endpoint_b = std::move(ep.b),
        .streamid = std::string(streamid_sv)
    };
}

inline flow_id make_flow_id(
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) {
    return flow_id{
        .src = {src_ip, src_port},
        .dst = {dst_ip, dst_port}
    };
}

inline std::string make_stream_key(const stream_id& sid) {
    return "SRT|a=" + to_string(sid.endpoint_a) +
        "|b=" + to_string(sid.endpoint_b) +
        "|streamid=" + sid.streamid;
}

inline std::string make_flow_key(const stream_id& sid, const flow_id& fid) {
    return make_stream_key(sid) +
        "|src=" + to_string(fid.src) +
        "|dst=" + to_string(fid.dst);
}

