	flow_metrics &m = m_metrics;

    json j{
	    {"proto", "RTP"},
	    {"interface_id", m_fid.interface_id},
	    {"stream_key", m_stream_key},
	    {"flow_key", m_flow_key},
	    {"role", m_role_text},
	    {"ssrc", m_fid.ssrc},
	    {"payload_type", m_fid.payload_type},
	    {"endpoint",{
		    {"src",  m_src_text },
		    {"dst",  m_dst_text },
	    }},
		{"bitrate", {
			{"bps", m.bitrate.value()},
			{"count", m.bitrate.stats().count},
			{"min", m.bitrate.stats().min},
			{"max", m.bitrate.stats().max},
			{"avg", m.bitrate.stats().avg()},
		}},
		{"packet_rate", {
			{"pps", m.packet_rate.value()},
			{"count", m.packet_rate.stats().count},
			{"min", m.packet_rate.stats().min},
			{"max", m.packet_rate.stats().max},
			{"avg", m.packet_rate.stats().avg()},
		}},
		{"packet_count", {
			{"total", m.packet_count.count()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
        {"jitter", {
	        {"seconds", m.jitter.value_sec()},
			{"count", m.jitter.stats_sec().count},
			{"min", m.jitter.stats_sec().min},
			{"max", m.jitter.stats_sec().max},
			{"avg", m.jitter.stats_sec().avg()},
        }},
        {"clock_skew", {
	        {"skew_ppm", m.skew.skew_ppm()},
	        {"skew_ratio", m.skew.skew_ratio()},
	        {"observed_rate", m.skew.observed_rate()},
        }},
        {"seq_stats", {
	        {"gap", m.seq_stats.gap_count().count()},
	        {"dup", m.seq_stats.dup_count().count()},
	        {"reorder", m.seq_stats.reorder_count().count()},
        }}
    };

	m.bitrate.clear_stats();
	m.packet_rate.clear_stats();
	m.packet_count.reset();
	m.interval.clear_stats();
	m.seq_stats.reset_stats();

	out.push_back(std::move(j));

	return 0;
}

