#include <memory>
#include <string>
#include <unordered_map>

#include "event.h"
#include "json.h"
#include "metrics_common.h"

namespace netif {

struct config {
};

struct interface_id {
	std::string name;

	bool operator==(const interface_id &o) const noexcept {
		return name == o.name;
	}
};

struct interface_id_hash {
	std::size_t operator()(const interface_id &v) const noexcept {
		return std::hash<std::string>{}(v.name);
	}
};

struct interface_stats {
	metrics::counter rx_packets;
	metrics::counter tx_packets;
	metrics::counter rx_errors;
	metrics::counter tx_errors;
	metrics::counter rx_dropped;
	metrics::counter tx_dropped;
};

class interface {
public:
	explicit interface(interface_id id, event_sink &events);
