  mixed: "#8bb8de",
  default: "#97acc3"
};
const DONUT_COLORS = ["#66d9ef", "#7fd4c7", "#6e97c7", "#62b7c3", "#8bb8de", "#7f98b5"];

export function StreamTable({ streams, interfaces, selectedStreamKey, selectedFlowKey, selectedInterfaceKey, overviewMode = false, onSelectInterface, onSelectStream, onSelectFlow }: StreamTableProps) {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [expandedInterfaces, setExpandedInterfaces] = useState<Set<string>>(() => new Set());
  const initializedExpansion = useRef(false);
  const initializedInterfaceExpansion = useRef(false);
  const maxStreamBitrate = Math.max(...streams.map(streamBitrateOf), 1);
  const interfaceGroups = buildInterfaceGroups(interfaces, streams);
  const groupedByInterface = interfaceGroups.length > 0;

  useEffect(() => {
    if (initializedExpansion.current || streams.length === 0) return;
    initializedExpansion.current = true;
    setExpanded(new Set(streams.filter(isExpandable).map((stream) => stream.streamKey)));
  }, [streams]);

  useEffect(() => {
    if (initializedInterfaceExpansion.current || interfaceGroups.length === 0) return;
    initializedInterfaceExpansion.current = true;
    setExpandedInterfaces(new Set(interfaceGroups.map((group) => group.key)));
  }, [interfaceGroups]);

  const selectStream = (stream: StreamListItem) => {
    onSelectStream(stream.streamKey);
    if (isExpandable(stream)) {
      setExpanded((current) => new Set(current).add(stream.streamKey));
    }
  };

  const toggleStream = (streamKey: string) => {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(streamKey)) next.delete(streamKey);
      else next.add(streamKey);
      return next;
    });
  };

  const toggleInterface = (key: string) => {
    setExpandedInterfaces((current) => {
