              <p>{filteredStreams.length} visible / {streams.length} total</p>
              </div>
              <div className="list-toolbar-actions">
                <div className="expand-level-controls" role="tablist" aria-label="Tree expand level">
                  <button type="button" className={expandLevel === "interface" ? "active" : ""} onClick={() => setExpandLevel("interface")} aria-pressed={expandLevel === "interface"} title="Show NIC rows only">NIC</button>
                  <button type="button" className={expandLevel === "stream" ? "active" : ""} onClick={() => setExpandLevel("stream")} aria-pressed={expandLevel === "stream"} title="Open NIC rows and show streams">Stream</button>
                  <button type="button" className={expandLevel === "flow" ? "active" : ""} onClick={() => setExpandLevel("flow")} aria-pressed={expandLevel === "flow"} title="Open all NIC, stream, and flow rows">Flow</button>
                </div>
                {wideLayout && (
                  <div className="list-width-controls" aria-label="Stream list width controls">
                    <button type="button" className={`size-button size-button-v size-button-left ${rightPaneMaximized ? "active" : ""}`} onClick={() => {
                      const liveWidth = workspaceRef.current?.clientWidth ?? workspaceWidth;
                      setRightPaneWidth(Math.max(MIN_RIGHT_WIDTH, liveWidth - 8));
                    }} aria-pressed={rightPaneMaximized} title="Shrink stream list"><span className="width-icon" aria-hidden="true" /></button>
                    <button type="button" className={`size-button size-button-v size-button-center ${rightPaneRestored ? "active" : ""}`} onClick={() => setRightPaneWidth(Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneRestoreWidth || DEFAULT_RIGHT_WIDTH)))} aria-pressed={rightPaneRestored} title="Restore stream list width"><span className="width-icon" aria-hidden="true" /></button>
                    <button type="button" className={`size-button size-button-v size-button-right ${listOverviewMode ? "active" : ""}`} onClick={() => setRightPaneWidth(COLLAPSED_RIGHT_WIDTH)} aria-pressed={listOverviewMode} title="Maximize stream list"><span className="width-icon" aria-hidden="true" /></button>
                  </div>
                )}
              </div>
            </div>
            <label className="search-box">
              <span aria-hidden="true">⌕</span>
              <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter by kind, endpoint, role" />
            </label>
          </div>
          <StreamTable
            streams={filteredStreams}
            interfaces={interfaces}
            selectedStreamKey={selectedStreamKey}
            selectedFlowKey={selectedFlowKey}
            selectedInterfaceKey={selectedInterfaceKey}
            overviewMode={listOverviewMode}
            expandLevel={expandLevel}
            onSelectInterface={(interfaceKey) => {
              setSelectedInterfaceKey(interfaceKey);
              setSelectedStreamKey(null);
              setSelectedFlowKey(null);
            }}
            onSelectStream={(streamKey) => {
              setSelectedInterfaceKey(null);
              setSelectedStreamKey(streamKey);
              setSelectedFlowKey(null);
            }}
            onSelectFlow={(streamKey, flowKey) => {
              setSelectedInterfaceKey(null);
              setSelectedStreamKey(streamKey);
              setSelectedFlowKey(flowKey);
            }}
          />
        </aside>
        <div className="workspace-splitter" role="separator" aria-orientation="vertical" onPointerDown={startResizeWidth} />
        <section ref={rightColumnRef} className={`right-column${eventsMaximized ? " events-maximized" : ""}${eventsMinimized ? " events-minimized" : ""}${listOverviewMode ? " width-collapsed" : ""}`} style={{ gridTemplateRows: rightColumnRows }}>
          {selectedInterface && !selectedStreamKey ? (
            <InterfaceDetailPane
              item={selectedInterface}
              metrics={selectedInterfaceMetrics}
              onMinimizeWidth={() => setRightPaneWidth(MIN_RIGHT_WIDTH)}
              onRestoreWidth={() => setRightPaneWidth(Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneRestoreWidth || DEFAULT_RIGHT_WIDTH)))}
              onMaximizeWidth={() => {
                const liveWidth = workspaceRef.current?.clientWidth ?? workspaceWidth;
                setRightPaneWidth(Math.max(MIN_RIGHT_WIDTH, liveWidth - 8));
              }}
              isWidthMinimized={rightPaneMinimized}
              isWidthRestored={rightPaneRestored}
              isWidthMaximized={rightPaneMaximized}
              showWidthControls={wideLayout}
            />
          ) : (
            <DetailPane
              stream={detailStream}
              metrics={selectedMetrics}
              selectedFlowKey={selectedFlowKey}
              onMinimizeWidth={() => setRightPaneWidth(MIN_RIGHT_WIDTH)}
              onRestoreWidth={() => setRightPaneWidth(Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneRestoreWidth || DEFAULT_RIGHT_WIDTH)))}
              onMaximizeWidth={() => {
                const liveWidth = workspaceRef.current?.clientWidth ?? workspaceWidth;
                setRightPaneWidth(Math.max(MIN_RIGHT_WIDTH, liveWidth - 8));
              }}
              isWidthMinimized={rightPaneMinimized}
              isWidthRestored={rightPaneRestored}
              isWidthMaximized={rightPaneMaximized}
              showWidthControls={wideLayout}
            />
          )}
          <div className="pane-splitter" role="separator" aria-orientation="horizontal" onPointerDown={startResizeEvents} />
          <EventLog
            events={events}
            selectedStreamKey={selectedStreamKey}
            selectedFlowKey={selectedFlowKey}
            selectedInterfaceId={selectedInterface?.interfaceId ?? null}
            onMinimize={() => setEventsHeight(MINIMIZED_EVENTS_HEIGHT)}
            onRestore={() => setEventsHeight(Math.min(eventsMaxHeight, Math.max(MINIMIZED_EVENTS_HEIGHT, eventsRestoreHeight || DEFAULT_EVENTS_HEIGHT)))}
            onMaximize={() => setEventsHeight(eventsMaxHeight)}
            isMinimized={eventsMinimized}
            isRestored={eventsRestored}
            isMaximized={eventsMaximized}
          />
        </section>
      </section>
      {/* Strong guard against browser history swipe gestures during splitter drags; remove if it interferes with normal dragging. */}
      {resizingPane && <div className={`resize-capture resize-capture-${resizingPane}`} aria-hidden="true" />}
    </main>
  );
}

function SummaryCard({ label, value }: { label: string; value: string }) {
  return <div className="summary-card"><span>{label}</span><strong>{value}</strong></div>;
}

