+  width: 20px;
+  color: var(--accent);
+  font-size: 16px;
+  line-height: 1;
+}
+.menu-rail-brand {
+  font-size: 13px;
+  font-weight: 800;
+  letter-spacing: .14em;
+  text-transform: uppercase;
+}
+.menu-rail-nav {
+  display: grid;
+  gap: 8px;
+  align-content: start;
+}
+.menu-item {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  width: 100%;
+  min-height: 48px;
+  padding: 0 10px;
+  border: 1px solid transparent;
+  border-radius: 12px;
+  background: transparent;
+  color: var(--muted);
+  text-align: left;
+  cursor: pointer;
+}
+.menu-item:hover,
+.menu-item.active {
+  background: rgba(102,217,239,.08);
+  border-color: rgba(102,217,239,.16);
+  color: #eef4fb;
+}
+.menu-item-icon {
+  display: grid;
+  place-items: center;
+  width: 20px;
+  flex: 0 0 20px;
+  color: var(--accent);
+  font-size: 17px;
+  line-height: 1;
+}
+.menu-item-copy strong {
+  display: block;
+  font-size: 13px;
+  font-weight: 700;
+  color: inherit;
+}
+.menu-item-copy small {
+  display: block;
+  margin-top: 2px;
+  color: var(--muted);
+  font-size: 10px;
+}
 .hero-panel { display: flex; align-items: end; justify-content: space-between; gap: 18px; padding: 22px; border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(14,29,43,.9), rgba(37,28,18,.72)); box-shadow: 0 20px 64px rgba(0,0,0,.28); }
