    const bandFill = toRgba(color, compact ? 0.12 : 0.16);
    const options: uPlot.Options = {
      width: hostRef.current.clientWidth || 640,
      height,
      cursor: { sync: { key: syncKey } },
      scales: { x: { time: true } },
      legend: { show: !compact },
      axes: compact
        ? [
            { show: false },
            { show: false }
          ]
        : [
