bool isTargetPcap(const std::string& filename) {
	return filename.find(PCAP_PREFIX) != std::string::npos &&
	       filename.find(".pcap") != std::string::npos;
}

void rememberProcessed(const std::string& filename) {
	if(!g_processed_files.insert(filename).second) {
		return;
	}

	g_processed_order.push_back(filename);
	while(g_processed_order.size() > kRingFileCount) {
		g_processed_files.erase(g_processed_order.front());
		g_processed_order.pop_front();
	}
}

std::vector<std::string> collectPendingPcaps() {
	std::vector<std::string> filenames;

	for(const auto& entry : std::filesystem::directory_iterator(WATCH_DIR)) {
		if(!entry.is_regular_file()) {
			continue;
		}

		std::string filename = entry.path().filename().string();
		if(isTargetPcap(filename) && !g_processed_files.contains(filename)) {
			filenames.push_back(std::move(filename));
		}
	}

