function mergeFlows(existing: FlowState[], incoming: FlowState[]) {
  const byKey = new Map(existing.map((flow) => [flow.flowKey, flow]));
  for (const flow of incoming) {
    byKey.set(flow.flowKey, { ...byKey.get(flow.flowKey), ...flow, metrics: byKey.get(flow.flowKey)?.metrics ?? flow.metrics });
  }
  return [...byKey.values()];
}

function buildMetrics(history: FlowMetricPoint[], keys: Set<string>): Record<string, TimeSeriesMetric> {
  const byMetric: Record<string, TimeSeriesMetric> = {};
  for (const point of history) {
    for (const [key, stat] of Object.entries(point.metrics)) {
      keys.add(key);
      const descriptor = descriptorForMetric(key);
      byMetric[key] ??= { key, label: descriptor.label, unit: descriptor.unit, points: [] };
      byMetric[key].points.push({ time: point.time, ...stat });
    }
  }
  return byMetric;
}

function nearestMetric(history: FlowMetricPoint[], time: number, key: string) {
  return history.find((point) => point.time === time)?.metrics[key];
}

function sumStat(stats: NumericStat[], field: keyof NumericStat) {
  const values = stats.map((stat) => stat[field]).filter((value): value is number => typeof value === "number");
  return values.length > 0 ? values.reduce((sum, value) => sum + value, 0) : undefined;
}

function statValue(stat: NumericStat | undefined) {
  return Math.max(0, Math.round(stat?.value ?? stat?.avg ?? stat?.count ?? 0));
}

function sumOverview(stats: OverviewStats[], field: keyof OverviewStats) {
  return stats.reduce((sum, item) => sum + item[field], 0);
}

function updateCount(counts: Map<string, number>, key: string, delta: 1 | -1) {
  const next = (counts.get(key) ?? 0) + delta;
  if (next <= 0) counts.delete(key);
  else counts.set(key, next);
}

function withoutInterfaceMarker(item: NormalizedInterfaceInput): InterfaceListItem {
  const { hasMetrics: _hasMetrics, ...rest } = item;
  return { ...rest, streamCount: 0 };
}

function interfaceMetricsForHistory(item: NormalizedInterfaceInput): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {
    "rx.bitrate": item.rxBitrate,
    "tx.bitrate": item.txBitrate,
    "rx.packets": item.rx.packets,
    "tx.packets": item.tx.packets,
    "rx.errors": item.rx.errors,
    "tx.errors": item.tx.errors,
    "rx.dropped": item.rx.dropped,
    "tx.dropped": item.tx.dropped
  };
  if (item.rxRate?.utilization !== undefined) metrics["rx.utilization"] = valueStat(item.rxRate.utilization);
  if (item.txRate?.utilization !== undefined) metrics["tx.utilization"] = valueStat(item.txRate.utilization);
  if (item.rxRate?.headroomBps !== undefined) metrics["rx.headroom"] = valueStat(item.rxRate.headroomBps);
  if (item.txRate?.headroomBps !== undefined) metrics["tx.headroom"] = valueStat(item.txRate.headroomBps);
  return metrics;
}

function valueStat(value: number): NumericStat {
  return { value, avg: value, min: value, max: value };
}

