int stream::process(const info &i) {
	touch(i.time_epoch);

	flow_id fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, m_events)).first;
	}

	return it->second->process(i);
}

flow_id stream::resolve_flow_id(const info &i) const {
	const std::uint16_t offset = static_cast<std::uint16_t>(i.dst.port - m_sid.session_dst.port);
	flow_role role = flow_role::unknown;

	switch(offset) {
	case 0: role = flow_role::media; break;
	case 2: role = flow_role::fec_row; break;
	case 4: role = flow_role::fec_col; break;
	default: role = flow_role::unknown; break;
	}

	return make_flow_id(i.interface_id,
	                    role,
	                    i.src.addr, i.src.port,
	                    i.dst.addr, i.dst.port,
	                    i.ssrc,
	                    i.p_type);
}

event_record flow::make_event(double now, std::string type, json detail) const {
	return event_record{
		.time_epoch = now,
		.type = std::move(type),
		.source = m_event.source,
		.detail = std::move(detail),
	};
}

void flow::update_packet_event(double now,
                               counted_event_state &state,
                               std::uint64_t &count,
                               const char *occurred_type,
                               const char *recovered_type,
                               json detail) {
	const auto event_update = state.update(now, count);

	if(event_update.occurred) {
		detail["window_count"] = event_update.window_count;
		m_events.emit(make_event(now, occurred_type, std::move(detail)));
	}
	if(event_update.recovered) {
		m_events.emit(make_event(now, recovered_type, json{
			{"active_total", event_update.active_total},
		}));
	}

	count = 0;
}

