import { useMemo } from "react";
import type { TimelineRow } from "../types/api";

type TimelinePaneProps = {
  rows: TimelineRow[];
  nowSec: number;
};

export function TimelinePane({ rows, nowSec }: TimelinePaneProps) {
  const range = useMemo(() => {
    if (rows.length === 0) {
      return { start: nowSec - 60, end: nowSec, ticks: [nowSec - 60, nowSec - 45, nowSec - 30, nowSec - 15, nowSec] };
    }

    const start = rows.reduce(
      (min, row) => Math.min(min, ...row.segments.map((segment) => segment.start)),
      Number.POSITIVE_INFINITY
    );
    const end = rows.reduce(
      (max, row) => Math.max(max, row.lastSeen, ...row.segments.map((segment) => segment.end ?? nowSec)),
      nowSec
    );
    const safeEnd = end > start ? end : start + 1;
    const step = (safeEnd - start) / 4;
    return {
      start,
      end: safeEnd,
      ticks: Array.from({ length: 5 }, (_, index) => start + step * index)
    };
  }, [nowSec, rows]);

  if (rows.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
    <div className="timeline-chart">
      <div className="timeline-axis">
        <div className="timeline-axis-label" />
        <div className="timeline-axis-scale">
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="timeline-rows">
        {rows.map((row) => (
          <div key={row.flowKey ?? row.streamKey} className={`timeline-row ${row.rowType === "flow" ? "timeline-row-flow" : "timeline-row-stream"}`}>
            <div className="timeline-row-label" title={row.flowKey ?? row.streamKey}>
              <strong>{row.label}</strong>
              <span>{row.rowType === "flow" ? `${row.interfaceName ?? row.kind} / ${row.role ?? "flow"}` : row.interfaceName ?? row.kind}</span>
            </div>
            <div className="timeline-row-track">
              {row.segments.map((segment, index) => {
                const start = percent(segment.start, range.start, range.end);
                const end = percent(segment.end ?? range.end, range.start, range.end);
                return (
                  <div
                    key={`${row.flowKey ?? row.streamKey}:${index}:${segment.start}`}
                    className={`timeline-segment ${row.rowType === "flow" ? "timeline-segment-flow" : "timeline-segment-stream"}${segment.end === null ? " active" : ""}`}
                    style={{
                      left: `${start}%`,
                      width: `${Math.max(0.6, end - start)}%`
                    }}
                  />
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function percent(value: number, start: number, end: number) {
  return ((value - start) / Math.max(1e-6, end - start)) * 100;
}

function formatTick(value: number, spanSec: number) {
  return new Date(value * 1000).toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: spanSec <= 600 ? "2-digit" : undefined
  });
}

