                  <TimelineLane
                    row={stream}
                    range={range}
                    cursorPercent={clampPercent(cursorPercent)}
                    fadeSec={fadeSec}
                    childCount={flows.length}
                    expanded={isExpanded}
                    onToggle={flows.length > 0 ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded })) : undefined}
                  />
