  headroomBps?: number;
};

export type InterfaceListItem = {
  key: string;
  interfaceId?: number;
  name: string;
  observed: boolean;
  available: boolean;
  link?: InterfaceLinkInfo;
  lastSeen?: number;
  rx: InterfaceCounters;
  tx: InterfaceCounters;
