std::filesystem::path metrics_history_sink::build_path(const std::filesystem::path &root, const char *category, const hourly_slot &slot) {
	char day[16];
	char hour[16];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", slot.year, slot.month, slot.day);
	std::snprintf(hour, sizeof(hour), "%02d.jsonl", slot.hour);
	return root / category / day / hour;
}

std::string metrics_history_sink::subject_key(const json &entry, bool is_interface) {
	if(is_interface) {
		if(entry.contains("interface_id") && entry.at("interface_id").is_number_integer()) {
			return "if:" + std::to_string(entry.at("interface_id").get<int>());
		}
		if(entry.contains("name") && entry.at("name").is_string()) {
			return "name:" + entry.at("name").get<std::string>();
		}
		return "interface:unknown";
	}

	const auto stream_key = entry.value("stream_key", std::string{});
	const auto flow_key = entry.value("flow_key", std::string{});
	if(flow_key.empty()) {
		return stream_key;
	}
	return stream_key + "::" + flow_key;
}

bool metrics_history_sink::is_stat_object(const json &value) {
	if(!value.is_object()) {
		return false;
	}

	static const char *keys[] = { "value", "avg", "min", "max", "count", "bps", "pps", "seconds", "total", "window" };
	for(const char *key : keys) {
		if(value.contains(key) && value.at(key).is_number()) {
			return true;
		}
	}
	return false;
}

json metrics_history_sink::make_template(const json &value) {
	if(value.is_array()) {
		return json::array();
	}

	if(is_stat_object(value)) {
		return nullptr;
	}

	if(!value.is_object()) {
		return value;
	}

	json out = json::object();
	for(auto it = value.begin(); it != value.end(); ++it) {
		const json child = make_template(it.value());
		if(child.is_null()) {
			continue;
		}
		if(child.is_object() && child.empty()) {
			continue;
		}
		if(child.is_array() && child.empty()) {
			continue;
		}
		out[it.key()] = child;
	}
	return out;
}

double metrics_history_sink::first_stat_value(const json &record) {
	static const char *keys[] = { "value", "bps", "pps", "seconds", "total", "window", "avg", "min", "max" };
	for(const char *key : keys) {
		if(record.contains(key) && record.at(key).is_number()) {
			return record.at(key).get<double>();
		}
	}
	return 0.0;
}

void metrics_history_sink::collect_values(const std::string &prefix, const json &value, std::map<std::string, double> &out) {
	if(is_stat_object(value)) {
		out[prefix] = first_stat_value(value);
		return;
	}

	if(value.is_number()) {
		out[prefix] = value.get<double>();
		return;
	}

	if(!value.is_object() || value.is_array()) {
		return;
	}

	for(auto it = value.begin(); it != value.end(); ++it) {
		const auto child_prefix = prefix.empty() ? it.key() : prefix + "." + it.key();
		collect_values(child_prefix, it.value(), out);
	}
}

void metrics_history_sink::set_path(json &out, const std::string &path, json value) {
	json *cursor = &out;
	std::size_t start = 0;
	while(true) {
		const std::size_t dot = path.find('.', start);
		const auto part = path.substr(start, dot == std::string::npos ? std::string::npos : dot - start);
		if(dot == std::string::npos) {
			(*cursor)[part] = std::move(value);
			return;
		}
		if(!cursor->contains(part) || !(*cursor)[part].is_object()) {
			(*cursor)[part] = json::object();
		}
		cursor = &(*cursor)[part];
		start = dot + 1;
	}
}

void metrics_history_sink::append_raw(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	const auto slot = slot_for(now);
	ensure_open(m_raw_file, "raw", slot);
	json root = {
		{"time", now},
		{"metrics", metrics},
		{"interfaces", interfaces},
	};
	write_line(m_raw_file, root);
}

void metrics_history_sink::observe_entries(std::map<std::string, minute_bucket::subject_accumulator> &accumulators,
                                           const json::array_t &entries,
                                           bool is_interface) {
	for(const auto &entry : entries) {
		if(!entry.is_object()) {
			continue;
		}
		const auto key = subject_key(entry, is_interface);
		auto &acc = accumulators[key];
		if(acc.template_object.is_null()) {
			acc.template_object = make_template(entry);
		}

		std::map<std::string, double> values;
		collect_values("", entry, values);
		for(const auto &[path, sample] : values) {
			acc.stats_by_path[path].add(sample);
			acc.last_by_path[path] = sample;
		}
	}
}

void metrics_history_sink::update_rollup(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	const auto bucket_start = minute_floor(now);
	if(!m_bucket.has_value()) {
		m_bucket = minute_bucket{ .bucket_start = bucket_start, .bucket_end = bucket_start + 60.0 };
	}
	else if(bucket_start != m_bucket->bucket_start) {
		flush_bucket();
		m_bucket = minute_bucket{ .bucket_start = bucket_start, .bucket_end = bucket_start + 60.0 };
	}

	observe_entries(m_bucket->metrics_entries, metrics, false);
	observe_entries(m_bucket->interface_entries, interfaces, true);
}

void metrics_history_sink::flush_bucket() {
	if(!m_bucket.has_value()) {
		return;
	}

	const auto slot = slot_for(m_bucket->bucket_start);
	ensure_open(m_rollup_1m_file, "rollup_1m", slot);

	auto build_entries = [](const std::map<std::string, minute_bucket::subject_accumulator> &accumulators) {
		json::array_t out;
		for(const auto &[_, acc] : accumulators) {
			json entry = acc.template_object.is_null() ? json::object() : acc.template_object;
			for(const auto &[path, stats] : acc.stats_by_path) {
				const auto last_it = acc.last_by_path.find(path);
				json stat = {
					{"value", stats.avg()},
					{"avg", stats.avg()},
					{"min", stats.min},
					{"max", stats.max},
					{"count", stats.count},
				};
				if(last_it != acc.last_by_path.end()) {
					stat["last"] = last_it->second;
				}
				set_path(entry, path, std::move(stat));
			}
			out.push_back(std::move(entry));
		}
		return out;
	};

	json root = {
		{"time", m_bucket->bucket_end},
		{"bucket_start", m_bucket->bucket_start},
		{"bucket_end", m_bucket->bucket_end},
		{"resolution_sec", 60},
		{"metrics", build_entries(m_bucket->metrics_entries)},
		{"interfaces", build_entries(m_bucket->interface_entries)},
	};

	write_line(m_rollup_1m_file, root);
	m_bucket.reset();
}

void metrics_history_sink::ensure_open(hourly_file &file, const char *category, const hourly_slot &slot) {
	if(file.stream.is_open() && file.slot == slot) {
		return;
	}

	if(file.stream.is_open()) {
		file.stream.flush();
		file.stream.close();
	}

	file.slot = slot;
	file.path = build_path(m_cfg.root_dir, category, slot);
	std::filesystem::create_directories(file.path.parent_path());
	file.stream.open(file.path, std::ios::app);
}

void metrics_history_sink::write_line(hourly_file &file, const json &line) {
	if(!file.stream.is_open()) {
		return;
	}
	file.stream << line.dump() << '\n';
	file.stream.flush();
}

