timeline_sink::timeline_sink(writer &w, std::string capture_id)
	: m_writer(w)
	, m_capture_id(std::move(capture_id)) {
}

//--------------------------------------------------------------------------------
int timeline_sink::emit(const timeline_record &e) {
	json j{
		{"capture_id", m_capture_id},
		{"seq", m_seq++},
		{"time", e.time_epoch},
		{"kind", e.kind},
		{"source", "pcap"},
		{"subject", e.subject},
	};

	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	return m_writer.dump(j);
}

