function clampTimelineWindow({
  desiredTo,
  windowSec,
  available
}: {
  desiredTo: number;
  windowSec: number;
  available: TimelineWindow;
}) {
  const availableSpan = Math.max(0, available.to - available.from);
  if (availableSpan <= windowSec) {
    return {
      from: available.from,
      to: available.to
    };
  }

  const minTo = available.from + windowSec;
  const maxTo = available.to;
  const safeTo = Math.min(maxTo, Math.max(minTo, desiredTo));
  return {
    from: safeTo - windowSec,
    to: safeTo
