function VirtualRow({ children, estimatedHeight }: { children: React.ReactNode; estimatedHeight: number }) {
  const ref = useRef<HTMLDivElement | null>(null);
  const [visible, setVisible] = useState(true);

  useEffect(() => {
    const node = ref.current;
    if (!node || typeof IntersectionObserver === "undefined") return;
    const root = node.closest(".list-body") as Element | null;
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];
        if (!entry) return;
        setVisible(entry.isIntersecting);
      },
      {
        root,
        rootMargin: "420px 0px 420px 0px",
        threshold: 0
      }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={ref} style={visible ? undefined : { minHeight: `${Math.max(36, Math.round(estimatedHeight))}px` }}>
      {visible ? children : null}
    </div>
  );
}

function InterfaceHeadroomGauge({ item }: { item?: InterfaceListItem }) {
  const usage = interfaceCombinedUsage(item);
  const headroom = usage !== undefined ? 1 - usage : undefined;
  return (
    <span className="interface-headroom">
