            rowKey: stream.streamKey,
            childCount: flows.length,
            expanded: isExpanded,
            onToggle:
              flows.length > 0
                ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded }))
                : undefined
          });

          if (!isExpanded) continue;
          for (const flow of flows) {
            items.push({
              key: `flow:${flow.flowKey ?? flow.streamKey}`,
              type: "flow",
              height: 30,
              row: flow,
              rowKey: flow.flowKey ?? flow.streamKey
            });
          }
        }
      }
    }
    return items;
  }, [groupedByInterface, interfaceExpanded, expanded, protoExpanded, nowSec]);

  const virtualized = useMemo(() => {
    const offsets: number[] = new Array(flatRows.length);
    let total = 0;
    for (let index = 0; index < flatRows.length; index += 1) {
      offsets[index] = total;
      total += flatRows[index].height;
    }

    const overscan = Math.max(200, viewport.height);
    const startY = Math.max(0, viewport.top - overscan);
    const endY = viewport.top + viewport.height + overscan;

    let startIndex = 0;
    while (startIndex < flatRows.length && offsets[startIndex] + flatRows[startIndex].height < startY) {
      startIndex += 1;
    }

    let endIndex = startIndex;
    while (endIndex < flatRows.length && offsets[endIndex] < endY) {
      endIndex += 1;
    }

    const topPad = startIndex > 0 ? offsets[startIndex] : 0;
    const bottomPad = Math.max(0, total - (endIndex > 0 ? offsets[endIndex - 1] + flatRows[endIndex - 1].height : 0));

    return {
      startIndex,
      endIndex,
      topPad,
      bottomPad,
      visible: flatRows.slice(startIndex, endIndex)
    };
  }, [flatRows, viewport.height, viewport.top]);

  if (groupedByInterface.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
      <div
        ref={chartRef}
        className="timeline-chart"
        onPointerMove={(event) => {
          setIsHoveringCursor(true);
          updateCursor(event.clientX);
        }}
        onPointerLeave={() => {
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label" />
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <div className="timeline-cursor-label" style={{ left: `${clampPercent(cursorPercent)}%` }} title={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="timeline-rows">
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          if (item.type === "interface") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) }))}
                />
              </div>
            );
          }

          if (item.type === "proto") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineProtoLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                range={range}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? true}
                onToggle={item.onToggle}
              />
            </div>
          );
        })}
        {virtualized.bottomPad > 0 ? <div style={{ height: virtualized.bottomPad }} /> : null}
      </div>
    </div>
  );
}

function TimelineProtoLane({
  group,
  range,
  cursorPercent,
  expanded,
  isHovered,
  onHoverChange,
  onToggle
}: {
  group: {
    key: string;
    proto: string;
    rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
    segments: Array<{ start: number; end: number }>;
    active: boolean;
  };
  range: { start: number; end: number };
  cursorPercent: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
}) {
  const focusClass = isHovered ? " timeline-row-hovered" : "";
  return (
    <div
      className={`timeline-proto-row${focusClass}`}
      onPointerEnter={() => onHoverChange(group.key)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-proto-label" title={group.key}>
        <strong>
          <button type="button" className="timeline-toggle" onClick={onToggle} aria-label={expanded ? "Collapse protocol rows" : "Expand protocol rows"}>
            <span aria-hidden="true">{expanded ? "▾" : "▸"}</span>
          </button>
          {group.proto}
          <em>{group.rows.length}</em>
        </strong>
      </div>
      <div className="timeline-row-track timeline-proto-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {group.segments.map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end, range.start, range.end);
