import { existsSync } from "node:fs";
import fastify from "fastify";
import fastifyStatic from "@fastify/static";
import { config, ensureLogFilesExist } from "./config";
import { TailFile } from "./ingest/tailFile";
import { normalizeInterfacesLine, normalizeMetricsLine, normalizeStreamsLine, normalizeTimelineLine } from "./normalizer";
import { normalizeEventLine } from "./events";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";

async function main() {
  ensureLogFilesExist();

  const app = fastify({ logger: true });
  const store = new StreamStore(
    config.historyWindowSec,
    config.timelineWindowSec,
    config.staleAfterSec,
    config.lostRetentionSec,
    config.maxEvents,
    config.maxTimelineRows
  );

  await registerRoutes(app, store);

  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, {
      root: config.clientDist,
      prefix: "/"
    });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") {
        return reply.code(404).send({ error: "not found" });
      }
      return reply.sendFile("index.html");
    });
  }

  const sockets = new SocketServer(app.server, store, config.streamsPatchIntervalMs);
  sockets.start();

  const streamsTail = new TailFile({
    path: config.streamsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        store.upsertInterfaces(normalizeInterfacesLine(line));
        store.applyStreamSnapshot(normalizeStreamsLine(line).map((item) => item.stream), Date.now() / 1000);
      } catch (error) {
        app.log.warn({ error }, "failed to parse streams log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail streams log")
  });

  const metricsTail = new TailFile({
    path: config.metricsLog,
    pollMs: config.pollMs,
    onChunk: ({ start, end, bytes, lines, observedAt, processedAt, processingMs }) => {
      app.log.info({
        path: config.metricsLog,
        start,
        end,
        bytes,
        lines,
        observedAt,
        observedAtIso: new Date(observedAt).toISOString(),
        processedAt,
        processedAtIso: new Date(processedAt).toISOString(),
        processingMs
      }, "metrics log update detected");
    },
    onLine: (line) => {
      try {
        store.upsertInterfaces(normalizeInterfacesLine(line));
        for (const item of normalizeMetricsLine(line)) store.addMetric(item);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metrics log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail metrics log")
  });


  const eventsTail = new TailFile({
    path: config.eventsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        const event = normalizeEventLine(line);
        if (event) store.addEvent(event);
      } catch (error) {
        app.log.warn({ error }, "failed to parse events log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail events log")
  });

  const timelineTail = new TailFile({
    path: config.timelineLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        const item = normalizeTimelineLine(line);
        if (item) store.addTimelineEvent(item);
      } catch (error) {
        app.log.warn({ error }, "failed to parse timeline log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail timeline log")
  });

  streamsTail.start();
  metricsTail.start();
  eventsTail.start();
  timelineTail.start();

  const close = async () => {
    streamsTail.stop();
    metricsTail.stop();
    eventsTail.stop();
    timelineTail.stop();
    await app.close();
  };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());

  await app.listen({ host: config.host, port: config.port });
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

