import type { TimelineRow } from "../types/api";

type TimelinePaneProps = {
  rows: TimelineRow[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
};

export function TimelinePane({ rows, nowSec, fadeSec, rangeStartSec, rangeEndSec }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(Math.min(rangeEndSec, Math.max(rangeStartSec, nowSec)));
    }
  }, [isHoveringCursor, nowSec, rangeStartSec, rangeEndSec]);

  const updateCursor = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    setCursorSec(range.start + ratio * (range.end - range.start));
  };

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = false;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = row.interfaceName ?? (row.interfaceId !== undefined ? `if:${row.interfaceId}` : "unknown");
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = true;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  useEffect(() => {
    setProtoExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (!isOtherLike(row)) continue;
        const ifKey = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${row.interfaceName ?? "unknown"}`;
        const key = `${ifKey}::${row.proto}`;
        if (!(key in next)) {
          next[key] = true;
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows]);

  const range = useMemo(() => {
    const safeStart = Number.isFinite(rangeStartSec) ? rangeStartSec : nowSec - 60;
    const safeEnd = Number.isFinite(rangeEndSec) && rangeEndSec > safeStart ? rangeEndSec : safeStart + 1;
    const step = (safeEnd - safeStart) / 4;
    return {
      start: safeStart,
      end: safeEnd,
      ticks: Array.from({ length: 5 }, (_, index) => safeStart + step * index)
    };
  }, [nowSec, rangeStartSec, rangeEndSec]);
  const cursorPercent = percent(Math.min(range.end, Math.max(range.start, cursorSec)), range.start, range.end);
  const cursorLabel = formatCursor(cursorSec);

  const groupedRows = useMemo(() => {
    const streams = rows.filter((row) => row.rowType === "stream");
    const flowsByParent = new Map<string, TimelineRow[]>();
    for (const row of rows) {
      if (row.rowType !== "flow" || !row.parentStreamKey) continue;
      const group = flowsByParent.get(row.parentStreamKey) ?? [];
      group.push(row);
      flowsByParent.set(row.parentStreamKey, group);
    }
    return streams.map((stream) => {
      const flows = flowsByParent.get(stream.streamKey) ?? [];
      const streamSegments = stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? nowSec }));
      const flowSegments = flows.flatMap((flow) => flow.segments.map((segment) => ({ start: segment.start, end: segment.end ?? nowSec })));
      const merged = mergeSegments([...streamSegments, ...flowSegments]);
      const hasOpen =
        stream.segments.some((segment) => segment.end === null) ||
        flows.some((flow) => flow.segments.some((segment) => segment.end === null));
      const normalizedSegments = merged.map((segment, index) => {
        const isLast = index === merged.length - 1;
        if (hasOpen && isLast && segment.end >= nowSec) {
          return { start: segment.start, end: null as number | null };
        }
        return { start: segment.start, end: segment.end as number | null };
      });
      return {
        stream: {
          ...stream,
          active: stream.active || flows.some((flow) => flow.active),
          segments: normalizedSegments
        },
        flows
      };
    });
  }, [rows, nowSec]);

  const groupedByInterface = useMemo(() => {
    const groups = new Map<string, { key: string; label: string; rows: typeof groupedRows }>();
    for (const item of groupedRows) {
      const label = item.stream.interfaceName ?? (item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : "unknown");
      const key = item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : `name:${label}`;
      const group = groups.get(key) ?? { key, label, rows: [] };
      group.rows.push(item);
      groups.set(key, group);
    }
    return [...groups.values()]
      .map((group) => ({
        ...group,
        segments: mergeSegments(
          group.rows.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? nowSec })))
        ),
        firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
        lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
        active: group.rows.some(({ stream }) => stream.active)
      }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [groupedRows]);

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    const body = chart.closest(".timeline-body") as HTMLElement | null;
    if (!body) return;

    const update = () => {
      setViewport({
        top: body.scrollTop,
        height: body.clientHeight
      });
    };

    update();
    body.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(body);

    return () => {
      body.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [rows.length]);

  const flatRows = useMemo(() => {
    const items: Array<
      | { key: string; type: "interface"; height: number; group: (typeof groupedByInterface)[number] }
      | {
          key: string;
          type: "proto";
          height: number;
          group: {
            key: string;
            proto: string;
            rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
            segments: Array<{ start: number; end: number }>;
            active: boolean;
          };
          expanded: boolean;
          onToggle: () => void;
        }
      | {
          key: string;
          type: "stream" | "flow";
          height: number;
          row: TimelineRow;
          rowKey: string;
          childCount?: number;
          expanded?: boolean;
          onToggle?: () => void;
        }
    > = [];

    for (const group of groupedByInterface) {
      items.push({
        key: `if:${group.key}`,
        type: "interface",
        height: 30,
        group
      });

      if (!(interfaceExpanded[group.key] ?? true)) continue;
      const regularRows = group.rows.filter(({ stream }) => !isOtherLike(stream));
      const otherProtoGroups = buildOtherProtoGroups(group.rows, group.key, nowSec);

      for (const { stream, flows } of regularRows) {
        const isExpanded = expanded[stream.streamKey] ?? false;
        items.push({
          key: `stream:${stream.streamKey}`,
          type: "stream",
          height: 34,
          row: stream,
          rowKey: stream.streamKey,
          childCount: flows.length,
          expanded: isExpanded,
          onToggle:
            flows.length > 0
              ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded }))
              : undefined
        });

        if (!isExpanded) continue;
        for (const flow of flows) {
          const flowKey = `${stream.streamKey}::${flow.flowKey ?? flow.streamKey}`;
          items.push({
            key: `flow:${flowKey}`,
            type: "flow",
            height: 30,
            row: flow,
            rowKey: flowKey
          });
        }
      }

      for (const protoGroup of otherProtoGroups) {
        const groupExpanded = protoExpanded[protoGroup.key] ?? true;
        items.push({
          key: `proto:${protoGroup.key}`,
          type: "proto",
          height: 30,
          group: protoGroup,
          expanded: groupExpanded,
          onToggle: () => setProtoExpanded((current) => ({ ...current, [protoGroup.key]: !groupExpanded }))
        });

        if (!groupExpanded) continue;
        for (const { stream, flows } of protoGroup.rows) {
          const isExpanded = expanded[stream.streamKey] ?? false;
          items.push({
            key: `stream:${stream.streamKey}`,
            type: "stream",
            height: 34,
            row: stream,
            rowKey: stream.streamKey,
            childCount: flows.length,
            expanded: isExpanded,
            onToggle:
              flows.length > 0
                ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded }))
                : undefined
          });

          if (!isExpanded) continue;
          for (const flow of flows) {
            const flowKey = `${stream.streamKey}::${flow.flowKey ?? flow.streamKey}`;
            items.push({
              key: `flow:${flowKey}`,
              type: "flow",
              height: 30,
              row: flow,
              rowKey: flowKey
            });
          }
        }
      }
    }
    return items;
  }, [groupedByInterface, interfaceExpanded, expanded, protoExpanded, nowSec]);

  const virtualized = useMemo(() => {
    const offsets: number[] = new Array(flatRows.length);
    let total = 0;
    for (let index = 0; index < flatRows.length; index += 1) {
      offsets[index] = total;
      total += flatRows[index].height;
    }

    const overscan = Math.max(200, viewport.height);
    const startY = Math.max(0, viewport.top - overscan);
    const endY = viewport.top + viewport.height + overscan;

    let startIndex = 0;
    while (startIndex < flatRows.length && offsets[startIndex] + flatRows[startIndex].height < startY) {
      startIndex += 1;
    }

    let endIndex = startIndex;
    while (endIndex < flatRows.length && offsets[endIndex] < endY) {
      endIndex += 1;
    }

    const topPad = startIndex > 0 ? offsets[startIndex] : 0;
    const bottomPad = Math.max(0, total - (endIndex > 0 ? offsets[endIndex - 1] + flatRows[endIndex - 1].height : 0));

    return {
      startIndex,
      endIndex,
      topPad,
      bottomPad,
      visible: flatRows.slice(startIndex, endIndex)
    };
  }, [flatRows, viewport.height, viewport.top]);

  if (groupedByInterface.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
      <div
        ref={chartRef}
        className="timeline-chart"
        onPointerMove={(event) => {
          setIsHoveringCursor(true);
          updateCursor(event.clientX);
        }}
        onPointerLeave={() => {
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label" />
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <div className="timeline-cursor-label" style={{ left: `${clampPercent(cursorPercent)}%` }} title={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>

