              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="timeline-rows">
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          if (item.type === "interface") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) }))}
                />
              </div>
            );
          }

          if (item.type === "proto") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineProtoLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                range={range}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? false}
                onToggle={item.onToggle}
              />
            </div>
          );
        })}
        {virtualized.bottomPad > 0 ? <div style={{ height: virtualized.bottomPad }} /> : null}
      </div>
    </div>
  );
}

function TimelineProtoLane({
  group,
  range,
  cursorPercent,
  expanded,
  isHovered,
  onHoverChange,
  onToggle
}: {
  group: {
    key: string;
    proto: string;
    rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
    segments: Array<{ start: number; end: number }>;
    active: boolean;
  };
  range: { start: number; end: number };
  cursorPercent: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
}) {
  const focusClass = isHovered ? " timeline-row-hovered" : "";
  return (
    <div
      className={`timeline-proto-row${focusClass}`}
      onPointerEnter={() => onHoverChange(group.key)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-proto-label" title={group.key}>
        <strong>
          <button type="button" className="timeline-toggle" onClick={onToggle} aria-label={expanded ? "Collapse protocol rows" : "Expand protocol rows"}>
            <span aria-hidden="true">{expanded ? "▾" : "▸"}</span>
          </button>
          {group.proto}
          <em>{group.rows.length}</em>
        </strong>
      </div>
      <div className="timeline-row-track timeline-proto-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {group.segments.map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end, range.start, range.end);
          return (
            <div
              key={`${group.key}:${index}:${segment.start}`}
              className={`timeline-segment timeline-segment-proto${group.active && index === group.segments.length - 1 && segment.end >= range.end ? " active" : ""}`}
              style={{
                left: `${start}%`,
                width: `${Math.max(0.6, end - start)}%`
              }}
            />
          );
        })}
      </div>
    </div>
  );
}

function TimelineInterfaceLane({
  group,
  range,
  cursorPercent,
  expanded,
  isHovered,
  onHoverChange,
  onToggle
}: {
  group: {
    key: string;
    label: string;
    rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
    segments: Array<{ start: number; end: number }>;
    firstSeen: number;
    lastSeen: number;
    active: boolean;
  };
  range: { start: number; end: number };
  cursorPercent: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
}) {
  const focusClass = isHovered ? " timeline-row-hovered" : "";
  return (
    <div
      className={`timeline-interface-header${focusClass}`}
      onPointerEnter={() => onHoverChange(group.key)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-interface-label" title={group.key}>
        <strong>
          <button type="button" className="timeline-toggle" onClick={onToggle} aria-label={expanded ? "Collapse interface rows" : "Expand interface rows"}>
            <span aria-hidden="true">{expanded ? "▾" : "▸"}</span>
          </button>
          {group.label}
          <em>{group.rows.length}</em>
        </strong>
      </div>
      <div className="timeline-row-track timeline-interface-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {group.segments.map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end, range.start, range.end);
          return (
            <div
              key={`${group.key}:${index}:${segment.start}`}
              className={`timeline-segment timeline-segment-interface${group.active && index === group.segments.length - 1 && segment.end >= range.end ? " active" : ""}`}
              style={{
                left: `${start}%`,
                width: `${Math.max(0.6, end - start)}%`
              }}
            />
          );
        })}
      </div>
    </div>
  );
}

function TimelineLane({
  rowKey,
  row,
  range,
  cursorPercent,
  cursorSec,
  fadeSec,
  isHovered,
  onHoverChange,
  childCount = 0,
  expanded = true,
  onToggle
}: {
  rowKey: string;
  row: TimelineRow;
  range: { start: number; end: number };
  cursorPercent: number;
  cursorSec: number;
  fadeSec: number;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  childCount?: number;
  expanded?: boolean;
  onToggle?: () => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
    return cursorSec >= segment.start && cursorSec <= end;
  });
  const focusClass = focused
    ? " timeline-row-cursor-focused"
    : isHovered
      ? " timeline-row-hovered"
      : "";

  return (
    <div
      className={`timeline-row ${row.rowType === "flow" ? "timeline-row-flow" : "timeline-row-stream"}${focusClass}`}
      onPointerEnter={() => onHoverChange(rowKey)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-row-label" title={row.flowKey ?? row.streamKey}>
        <strong>
          {onToggle ? (
            <button type="button" className="timeline-toggle" onClick={onToggle} aria-label={expanded ? "Collapse flow rows" : "Expand flow rows"}>
              <span aria-hidden="true">{expanded ? "▾" : "▸"}</span>
            </button>
          ) : (
            <span className="timeline-toggle-spacer" aria-hidden="true" />
          )}
          {row.label}
          {childCount > 0 && row.rowType === "stream" ? <em>{childCount}</em> : null}
        </strong>
        {/* <span>{row.rowType === "flow" ? `${row.interfaceName ?? row.kind} / ${row.role ?? "flow"}` : row.interfaceName ?? row.kind}</span> */}
      </div>
      <div className="timeline-row-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {row.segments.map((segment, index) => renderSegment(row, segment, index, range, fadeSec))}
      </div>
    </div>
  );
}

function renderSegment(row: TimelineRow, segment: { start: number; end: number | null }, index: number, range: { start: number; end: number }, fadeSec: number) {
  const fullEnd = segment.end ?? range.end;
  const start = percent(segment.start, range.start, range.end);
  const end = percent(fullEnd, range.start, range.end);
  const width = Math.max(0.6, end - start);
  const baseClass = row.rowType === "flow" ? "timeline-segment-flow" : row.rowType === "stream" ? "timeline-segment-stream" : "timeline-segment-interface";
  const key = `${row.flowKey ?? row.streamKey}:${index}:${segment.start}`;

  if (segment.end === null) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const fadeStart = Math.max(segment.start, fullEnd - fadeSec);
  if (fadeStart <= segment.start + 1e-6) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} timeline-segment-fade active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const solidEnd = percent(fadeStart, range.start, range.end);
  const fadeBegin = percent(fadeStart, range.start, range.end);
  const fadeWidth = Math.max(0.6, end - fadeBegin);

  return (
    <Fragment key={key}>
      <div
        key={`${key}:solid`}
        className={`timeline-segment ${baseClass} timeline-segment-split-solid active`}
        style={{
          left: `${start}%`,
          width: `${Math.max(0.6, solidEnd - start)}%`
        }}
      />
      <div
        key={`${key}:fade`}
        className={`timeline-segment ${baseClass} timeline-segment-fade timeline-segment-split-fade active`}
        style={{
          left: `${fadeBegin}%`,
          width: `${fadeWidth}%`
        }}
      />
    </Fragment>
  );
}

function percent(value: number, start: number, end: number) {
  return ((value - start) / Math.max(1e-6, end - start)) * 100;
}

function clampPercent(value: number) {
  return Math.min(99.5, Math.max(0.5, value));
}

function formatTick(value: number, spanSec: number) {
  return new Date(value * 1000).toLocaleTimeString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: spanSec <= 600 ? "2-digit" : undefined
  });
}

function formatCursor(value: number) {
  return new Date(value * 1000).toLocaleString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
}

function mergeSegments(segments: Array<{ start: number; end: number }>) {
  if (segments.length === 0) return [];
  const sorted = [...segments].sort((a, b) => a.start - b.start || a.end - b.end);
  const merged = [{ ...sorted[0] }];
  for (let index = 1; index < sorted.length; index += 1) {
    const current = sorted[index];
    const last = merged[merged.length - 1];
    if (current.start <= last.end) {
      last.end = Math.max(last.end, current.end);
    } else {
      merged.push({ ...current });
    }
  }
  return merged;
}

function isOtherLike(row: TimelineRow) {
  const proto = row.proto.toUpperCase();
  return proto !== "RTP" && proto !== "SRT" && proto !== "HLS";
}

function buildOtherProtoGroups(
  rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>,
  scopeKey: string,
  nowSec: number
