}

function FlowRow({ flow, selected, overviewMode, enableCharts, onSelect }: { flow: FlowListItem; selected: boolean; overviewMode: boolean; enableCharts: boolean; onSelect: () => void }) {
  const flowBitrate = flow.bitrate.value ?? flow.bitrate.avg ?? 0;
  const color = flowLineColor(flow.role);

  return (
    <button className={`flow-list-row ${selected ? "selected" : ""}`} onClick={onSelect}>
      <span className={`status-dot ${flow.active ? "active" : "stale"}`} />
      <span className="flow-main">
        <span className="flow-title"><strong>{flow.role}</strong><span>{flow.label}</span></span>
        <span className="flow-subtitle">{flow.interfaceName ? `if: ${flow.interfaceName} / ` : ""}{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span>
      </span>
      <span className="row-right flow-row-right">
        <span className="stream-rate">{formatBitrate(flowBitrate)}</span>
        {enableCharts && <Sparkline values={flow.sparkline} width={150} height={24} color={color} strokeWidth={1.1} />}
        {overviewMode && enableCharts && <OverviewStats stats={flow.overview} />}
      </span>
    </button>
  );
}

function OverviewStats({ stats }: { stats: StreamListItem["overview"] }) {
  return (
    <span className="overview-stats" aria-label="Overview counters">
      <span><small>Gap</small><strong>{formatCount(stats.gap)}</strong></span>
      <span><small>Dup</small><strong>{formatCount(stats.dup)}</strong></span>
      <span><small>Re</small><strong>{formatCount(stats.reorder)}</strong></span>
      <span><small>Ev</small><strong>{formatCount(stats.events)}</strong></span>
    </span>
  );
}

function formatCount(value: number | undefined) {
  return value && value > 999 ? `${Math.round(value / 100) / 10}k` : String(value ?? 0);
}

function buildInterfaceGroups(interfaces: InterfaceListItem[], streams: StreamListItem[]) {
  const interfaceById = new Map(interfaces.filter((item) => item.interfaceId !== undefined).map((item) => [item.interfaceId!, item]));
  const groups = new Map<string, { key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>();

  for (const item of interfaces) {
    groups.set(item.key, {
      key: item.key,
      name: item.name,
      interfaceItem: item,
      streams: []
    });
  }

  for (const stream of streams) {
    const item = stream.interfaceId !== undefined ? interfaceById.get(stream.interfaceId) : undefined;
    const key = item ? item.key : stream.interfaceName ? `name:${stream.interfaceName}` : "unknown";
    const name = item?.name ?? stream.interfaceName ?? "Unknown interface";
    const group = groups.get(key) ?? { key, name, interfaceItem: item, streams: [] };
    group.streams.push(stream);
    groups.set(key, group);
  }

  return [...groups.values()]
    .filter((group) => group.streams.length > 0 || group.interfaceItem)
    .sort((a, b) => {
      if (a.key === "unknown") return 1;
      if (b.key === "unknown") return -1;
      return (a.interfaceItem?.interfaceId ?? Number.MAX_SAFE_INTEGER) - (b.interfaceItem?.interfaceId ?? Number.MAX_SAFE_INTEGER) || a.name.localeCompare(b.name);
    });
}

function expandedInterfaceKeys(
  interfaceGroups: Array<{ key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>,
  expandLevel: "interface" | "stream" | "flow"
) {
  if (expandLevel === "interface") return new Set<string>();
  return new Set(interfaceGroups.map((group) => group.key));
}

function expandedStreamKeys(streams: StreamListItem[], expandLevel: "interface" | "stream" | "flow") {
  if (expandLevel !== "flow") return new Set<string>();
  return new Set(streams.filter(isExpandable).map((stream) => stream.streamKey));
}

function expandedProtoKeys(
  interfaceGroups: Array<{ key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>,
  streams: StreamListItem[],
  expandLevel: "interface" | "stream" | "flow"
) {
  if (expandLevel === "interface") return new Set<string>();
  const keys = interfaceGroups.length > 0
    ? interfaceGroups.flatMap((group) => buildProtoGroups(group.streams, group.key).map((protoGroup) => protoGroup.key))
    : buildProtoGroups(streams, "root").map((protoGroup) => protoGroup.key);
  return new Set(keys);
}

function interfaceBitrateOf(item: InterfaceListItem | undefined, direction: "rx" | "tx") {
  const stat = direction === "rx" ? item?.rxBitrate : item?.txBitrate;
  return stat?.value ?? stat?.avg ?? 0;
}

function interfaceCombinedUsage(item: InterfaceListItem | undefined) {
  const rx = item?.rxRate?.utilization;
  const tx = item?.txRate?.utilization;
  const values = [rx, tx].filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  return values.length > 0 ? Math.max(...values) : undefined;
}

function formatPercent(value: number | undefined) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return `${Math.round(Math.max(0, Math.min(1, value)) * 100)}%`;
}

function formatLinkSummary(item: InterfaceListItem | undefined) {
  if (!item?.link) return "link unknown";
  const speed = item.link.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "speed unknown";
  const duplex = item.link.duplex ? ` ${item.link.duplex}` : "";
  const state = item.link.operstate ? ` ${item.link.operstate}` : "";
  return `${speed}${duplex}${state}`;
}

function formatLinkSpeed(speedMbps: number) {
  if (speedMbps < 1000) return `${speedMbps}M`;
  const gbps = speedMbps / 1000;
  return `${Number.isInteger(gbps) ? gbps.toFixed(0) : gbps.toFixed(1)}G`;
}

function streamBitrateOf(stream: StreamListItem) {
  return stream.bitrate.value ?? stream.bitrate.avg ?? 0;
}

function protoAccentColor(proto: string) {
  switch (proto.toUpperCase()) {
    case "RTP":
      return "#f7c873";
    case "SRT":
      return "#7fd4c7";
    case "HLS":
      return "#87abd5";
    default:
      return "#a8b0ba";
  }
}

function buildTopBitrateEntries(streams: StreamListItem[]) {
  const sorted = streams
    .map((stream) => ({
      key: stream.streamKey,
      label: compactStreamLabel(stream),
      value: streamBitrateOf(stream)
    }))
    .filter((entry) => entry.value > 0)
    .sort((a, b) => b.value - a.value);
  const total = sorted.reduce((sum, entry) => sum + entry.value, 0);
  const top = sorted.slice(0, 5);
  const others = sorted.slice(5).reduce((sum, entry) => sum + entry.value, 0);
  const entries = others > 0 ? [...top, { key: "others", label: "Others", value: others }] : top;

  if (total === 0) return [{ key: "none", label: "No bitrate", value: 0, percent: 0 }];
  return entries.map((entry) => ({
    ...entry,
    percent: Math.round((entry.value / total) * 100)
  }));
}

function compactStreamLabel(stream: StreamListItem) {
  const label = stream.label || stream.streamKey;
  return label.length > 22 ? `${label.slice(0, 19)}...` : label;
}

function StreamSummaryChart({ stream, scaleMax }: { stream: StreamListItem; scaleMax: number }) {
  const width = 150;
  const height = 24;
  const totalValues = normalizeSeries(stream.sparkline);
  const count = totalValues.length;
  const flowSeries = stream.flows.map((flow) => ({
    flowKey: flow.flowKey,
    role: flow.role,
    values: alignSeries(flow.sparkline, count)
  }));

  if (count === 0) return <div className="sparkline-empty" style={{ width, height }} />;

  const pointsFor = (values: Array<number | undefined>) => values.map((value, index) => {
    const clamped = Math.max(0, Math.min(scaleMax, value ?? 0));
    const x = count === 1 ? width : (index / (count - 1)) * width;
    const y = height - ((clamped / scaleMax) * (height - 4)) - 2;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");

  return (
    <svg className="stream-summary-chart" width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      {flowSeries.map((series) => (
        <polyline
          key={series.flowKey}
          points={pointsFor(series.values)}
          fill="none"
          stroke={flowBarColor(series.role)}
          strokeWidth="1.1"
          strokeLinejoin="round"
          strokeLinecap="round"
          opacity={0.95}
        />
      ))}
      <polyline points={pointsFor(totalValues)} fill="none" stroke={TOTAL_COLOR} strokeWidth="1.1" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

function normalizeSeries(values: number[]) {
  if (values.length >= 60) return values.slice(-60);
  return [...Array(Math.max(0, 60 - values.length)).fill(0), ...values];
}

function alignSeries(values: number[], count: number) {
  const tail = values.slice(-count);
  return [...Array(Math.max(0, count - tail.length)).fill(undefined), ...tail];
}

function sumSparklines(seriesList: number[][]) {
  const count = Math.max(0, ...seriesList.map((values) => values.length));
  if (count === 0) return [];
  const aligned = seriesList.map((values) => alignSeries(values, count));
  return Array.from({ length: count }, (_, index) =>
    aligned.reduce((sum, series) => sum + (series[index] ?? 0), 0)
  );
}

function flowBarColor(role: string) {
  return FLOW_ROLE_COLORS[role] ?? FLOW_ROLE_COLORS.default;
}

function flowLineColor(role: string) {
  return FLOW_ROLE_LINE_COLORS[role] ?? FLOW_ROLE_LINE_COLORS.default;
}

function isExpandable(stream: StreamListItem) {
  return stream.flows.length > 1 || stream.flows.some((flow) => flow.role !== "default");
}

function buildProtoGroups(streams: StreamListItem[], parentKey: string) {
  const groups = new Map<string, { key: string; proto: string; streams: StreamListItem[] }>();
  for (const stream of streams) {
    const key = `${parentKey}|proto:${stream.proto}`;
    const existing = groups.get(key) ?? { key, proto: stream.proto, streams: [] };
    existing.streams.push(stream);
    groups.set(key, existing);
  }
  return [...groups.values()].sort((a, b) => a.proto.localeCompare(b.proto));
}

