inline void hash_combine(std::size_t& seed, std::size_t v) {
    seed ^= v + 0x9e3779b97f4a7c15ULL + (seed << 6) + (seed >> 2);
}

struct ip_addr {
    bool is_v6{false};
    std::array<std::uint8_t, 16> bytes{};

    bool operator==(const ip_addr&) const = default;
};

inline bool operator<(const ip_addr& a, const ip_addr& b) noexcept {
    if (a.is_v6 != b.is_v6) return a.is_v6 < b.is_v6;
    const std::size_t n = a.is_v6 ? 16 : 4;
    return std::memcmp(a.bytes.data(), b.bytes.data(), n) < 0;
}

struct ip_addr_hash {
    std::size_t operator()(const ip_addr& ip) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<bool>{}(ip.is_v6));
        const std::size_t n = ip.is_v6 ? 16 : 4;
        for (std::size_t i = 0; i < n; ++i) {
            hash_combine(h, std::hash<std::uint8_t>{}(ip.bytes[i]));
        }
        return h;
    }
};

struct ip_endpoint {
    ip_addr addr;
    std::uint16_t port{0};

    bool operator==(const ip_endpoint&) const = default;
};

inline bool operator<(const ip_endpoint& a, const ip_endpoint& b) noexcept {
    if (a.addr == b.addr) return a.port < b.port;
    return a.addr < b.addr;
}

struct ip_endpoint_hash {
    std::size_t operator()(const ip_endpoint& ep) const noexcept {
        std::size_t h = 0;
        hash_combine(h, ip_addr_hash{}(ep.addr));
        hash_combine(h, std::hash<std::uint16_t>{}(ep.port));
        return h;
    }
};

struct endpoint_pair {
    ip_endpoint a;
    ip_endpoint b;
};

inline endpoint_pair normalize_endpoints(
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port
) noexcept {
    ip_endpoint src{src_ip, src_port};
    ip_endpoint dst{dst_ip, dst_port};

    if (src < dst) return {src, dst};
    if (dst < src) return {dst, src};
    return {src, dst};
}

static bool parse_ipv4(std::string_view sv, ip_addr &out) {
	char buf[16];
	if(sv.empty() || sv.size() >= sizeof(buf)) {
		return false;
	}

	std::memcpy(buf, sv.data(), sv.size());
	buf[sv.size()] = '\0';

	in_addr addr{};
	if(::inet_pton(AF_INET, buf, &addr) != 1) {
		return false;
	}

	out = {};
	out.is_v6 = false;
	std::memcpy(out.bytes.data(), &addr, 4);

	return true;
}

static bool parse_ipv6(std::string_view sv, ip_addr &out) {
	char buf[INET6_ADDRSTRLEN];
	if(sv.empty() || sv.size() >= sizeof(buf)) {
		return false;
	}

	std::memcpy(buf, sv.data(), sv.size());
	buf[sv.size()] = '\0';

	in6_addr addr6{};
	if(::inet_pton(AF_INET6, buf, &addr6) != 1) {
		return false;
	}

	out = {};
	out.is_v6 = true;
	std::memcpy(out.bytes.data(), &addr6, 16);

	return true;
}

static bool parse_ip(std::string_view sv, ip_addr &out) {
	if(parse_ipv4(sv, out)) {
		return true;
	}

	return parse_ipv6(sv, out);
}

static bool parse_ip(std::string_view ipv4, std::string_view ipv6, ip_addr &out) {
	if(!ipv4.empty()) {
		return parse_ipv4(ipv4, out);
	}

	return parse_ipv6(ipv6, out);
}

inline std::string to_string(const ip_addr& ip) {
    char buf[INET6_ADDRSTRLEN] = {};

    const int af = ip.is_v6 ? AF_INET6 : AF_INET;
    const void* src = ip.bytes.data();

    if (::inet_ntop(af, src, buf, sizeof(buf)) == nullptr) {
        return ip.is_v6 ? "<invalid-ipv6>" : "<invalid-ipv4>";
    }

    return std::string(buf);
}

inline std::string to_string(const ip_endpoint& ep) {
    if (ep.addr.is_v6) {
        return "[" + to_string(ep.addr) + "]:" + std::to_string(ep.port);
    }
    return to_string(ep.addr) + ":" + std::to_string(ep.port);
}

inline std::ostream& operator<<(std::ostream& os, const ip_addr& ip) {
    return os << to_string(ip);
}

inline std::ostream& operator<<(std::ostream& os, const ip_endpoint& ep) {
    return os << to_string(ep);
}

