int app::parse_options(int argc, char *argv[], app::param *p) {
	cmdline::parser cp;

	cp.add<int>("debug", 'd', "debug log level", false, 1);
	cp.add<std::string>("name", 'n', "identity name", false, "");
	cp.add<std::string>("log-dir", 0, "log output directory", false, "");
	cp.add<std::string>("log-metrics", 0, "metrics log file", false, "metrics.log");
	cp.add<std::string>("log-streams", 0, "streams log file", false, "streams.log");
	cp.add<std::string>("log-events", 0, "events log file", false, "events.log");
	cp.add<std::string>("log-events-dir", 0, "events hourly output directory", false, "events");
	cp.add<std::uint64_t>("log-events-part-size-bytes", 0, "events part max size bytes", false, 64ULL * 1024ULL * 1024ULL);
	cp.add<std::uint32_t>("log-events-retention-hours", 0, "events retention hours", false, 72U);
	cp.add<std::string>("log-timeline", 0, "timeline log file", false, "timeline.log");
	cp.add<std::string>("log-timeline-dir", 0, "timeline history output directory", false, "timeline");
	cp.add<std::string>("log-history-dir", 0, "history output directory", false, "history");
	cp.add("version", 'v', "show version");

	cp.parse_check(argc, argv);

	if(cp.exist("version")) {
		version(argv, VERSION_STR);
		return -1;
	}

	p->debug_level = cp.get<int>("debug");
	p->id_name     = cp.exist("name") ? cp.get<std::string>("name") : std::to_string(getpid());
	p->log_dir     = cp.get<std::string>("log-dir");
	p->metrics_log = cp.get<std::string>("log-metrics");
	p->streams_log = cp.get<std::string>("log-streams");
	p->events_log  = cp.get<std::string>("log-events");
	p->events_hourly_dir = cp.get<std::string>("log-events-dir");
	p->events_part_size_bytes = cp.get<std::uint64_t>("log-events-part-size-bytes");
	p->events_retention_hours = cp.get<std::uint32_t>("log-events-retention-hours");
	p->timeline_log = cp.get<std::string>("log-timeline");
	p->timeline_history_dir = cp.get<std::string>("log-timeline-dir");
	p->history_dir = cp.get<std::string>("log-history-dir");

	std::fprintf(stderr, "id_name: %s\n", p->id_name.c_str());
	std::fprintf(stderr, "debug_level: %d\n", p->debug_level);
	std::fprintf(stderr, "log_dir: %s\n", p->log_dir.c_str());
	std::fprintf(stderr, "metrics_log: %s\n", p->metrics_log.c_str());
	std::fprintf(stderr, "streams_log: %s\n", p->streams_log.c_str());
	std::fprintf(stderr, "events_log: %s\n", p->events_log.c_str());
	std::fprintf(stderr, "events_hourly_dir: %s\n", p->events_hourly_dir.c_str());
	std::fprintf(stderr, "events_part_size_bytes: %llu\n", static_cast<unsigned long long>(p->events_part_size_bytes));
	std::fprintf(stderr, "events_retention_hours: %u\n", static_cast<unsigned>(p->events_retention_hours));
	std::fprintf(stderr, "timeline_log: %s\n", p->timeline_log.c_str());
	std::fprintf(stderr, "timeline_history_dir: %s\n", p->timeline_history_dir.c_str());
	std::fprintf(stderr, "history_dir: %s\n", p->history_dir.c_str());

	set_trace_id(p->id_name.c_str());
	set_trace_level(p->debug_level);

	return 0;
}

