int optional_index(const field_map_t &fields, std::string_view name) {
	auto it = fields.find(std::string(name));
	if(it == fields.end()) {
		return -1;
	}
	return static_cast<int>(it->second);
}

bool require_index(const field_map_t &fields, std::string_view name, int &out) {
	out = optional_index(fields, name);
	if(out < 0) {
		std::cerr << "[ERROR] missing required tshark field: " << name << std::endl;
		return false;
	}
	return true;
}

bool check_duplicate_fields(const std::string &header) {
	std::unordered_map<std::string, int> seen;
	tsv::row_t fields;
	tsv::split(header, fields);
	bool ok = true;
	for(const auto &field : fields) {
		std::string name(field);
		if(name.empty()) {
			continue;
		}
		int &count = seen[name];
		++count;
		if(count == 2) {
			std::cerr << "[ERROR] duplicate tshark field: " << name << std::endl;
			ok = false;
		}
	}
	return ok;
}

} // namespace

