#include <stdexcept>
#include <utility>

namespace {

std::vector<std::string> split_path(const std::string &path) {
	std::vector<std::string> out;
	std::size_t start = 0;
	while(start <= path.size()) {
		const auto pos = path.find('.', start);
		const auto end = (pos == std::string::npos) ? path.size() : pos;
		if(end > start) {
			out.emplace_back(path.substr(start, end - start));
		}
		if(pos == std::string::npos) {
			break;
		}
		start = pos + 1;
	}
	return out;
}

std::string json_string_or_empty(const json &j, const char *key) {
	if(!j.is_object() || !j.contains(key) || j[key].is_null()) {
		return {};
	}
	if(j[key].is_string()) {
		return j[key].get<std::string>();
	}
	if(j[key].is_number_integer()) {
		return std::to_string(j[key].get<long long>());
	}
	if(j[key].is_number_unsigned()) {
		return std::to_string(j[key].get<unsigned long long>());
	}
	if(j[key].is_number_float()) {
		return std::to_string(j[key].get<double>());
	}
	return {};
}

bool read_bool(const json &j, const char *key, bool fallback) {
	if(!j.contains(key) || !j[key].is_boolean()) {
		return fallback;
	}
	return j[key].get<bool>();
}

} // namespace

alert_evaluator::alert_evaluator(event_sink &events)
	: m_events(events) {
}

int alert_evaluator::load(const std::filesystem::path &path) {
	m_rules.clear();
	m_states.clear();

	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "alert_evaluator: failed to open " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "alert_evaluator: failed to parse " << path << ": " << e.what() << std::endl;
		return -1;
	}

	const json *rules_json = nullptr;
	if(root.is_object() && root.contains("alerts") && root["alerts"].is_array()) {
		rules_json = &root["alerts"];
	}
	else if(root.is_array()) {
		rules_json = &root;
	}
	else {
		std::cerr << "alert_evaluator: root.alerts must be an array" << std::endl;
		return -1;
	}

	for(const auto &entry : *rules_json) {
		if(!entry.is_object()) {
			std::cerr << "alert_evaluator: alert entry must be an object" << std::endl;
			return -1;
		}
		if(!entry.contains("id") || !entry["id"].is_string()) {
			std::cerr << "alert_evaluator: alert entry requires string id" << std::endl;
			return -1;
		}
		if(!entry.contains("metric") || !entry["metric"].is_string()) {
			std::cerr << "alert_evaluator: alert " << entry["id"] << " requires string metric" << std::endl;
			return -1;
		}

		rule r;
		r.id = entry["id"].get<std::string>();
		r.metric = entry["metric"].get<std::string>();
		if(entry.contains("target") && entry["target"].is_string()) r.target = entry["target"].get<std::string>();
		if(entry.contains("proto") && entry["proto"].is_string()) r.proto = entry["proto"].get<std::string>();
		if(entry.contains("type") && entry["type"].is_string()) r.type = parse_rule_type(entry["type"].get<std::string>());
		if(entry.contains("operator") && entry["operator"].is_string()) r.op = parse_compare_op(entry["operator"].get<std::string>());
		if(entry.contains("error_threshold")) r.error_threshold = entry["error_threshold"].get<double>();
		if(entry.contains("recover_threshold")) r.recover_threshold = entry["recover_threshold"].get<double>();
		else r.recover_threshold = r.error_threshold;
		if(entry.contains("delta_threshold")) r.delta_threshold = entry["delta_threshold"].get<double>();
		if(entry.contains("recover_after_sec")) r.recover_after_sec = entry["recover_after_sec"].get<double>();
		if(entry.contains("severity") && entry["severity"].is_string()) r.severity = entry["severity"].get<std::string>();

		m_rules.push_back(std::move(r));
	}

	return 0;
}

void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	for(const auto &entry : metrics) {
		if(!entry.is_object()) {
			continue;
		}
		for(const auto &r : m_rules) {
			evaluate_entry(now, r, entry, false);
		}
	}
	for(const auto &entry : interfaces) {
		if(!entry.is_object()) {
			continue;
		}
		for(const auto &r : m_rules) {
			evaluate_entry(now, r, entry, true);
		}
	}
}

void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
	if(!matches_target(r, entry, is_interface)) {
		return;
	}
	auto value = metric_value(entry, r.metric);
	if(!value.has_value() || !std::isfinite(*value)) {
		return;
	}

	const auto state_key = make_state_key(r, entry, is_interface);
	auto &s = m_states[state_key];	s.last_seen_time = now;

	switch(r.type) {
	case rule_type::threshold:
		evaluate_threshold(now, r, entry, state_key, s, *value);
		break;
	case rule_type::counter_delta:
		evaluate_counter_delta(now, r, entry, state_key, s, *value);
		break;
	}
}

void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, const std::string &, state &s, double value) {
	if(!s.active) {
		if(compare(value, r.op, r.error_threshold)) {
			s.active = true;
			s.last_error_time = now;
			emit_alert(now, r, entry, "detected", value, json{
				{"metric", r.metric},
				{"value", value},
				{"threshold", r.error_threshold},
				{"operator", "error"},
			});
		}
		return;
	}

	if(!compare(value, r.op, r.recover_threshold)) {
		s.active = false;
		emit_alert(now, r, entry, "recovered", value, json{
			{"metric", r.metric},
			{"value", value},
			{"threshold", r.recover_threshold},
			{"operator", "recover"},
		});
	}
}

void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, const std::string &, state &s, double value) {
	if(!s.has_last_value) {
		s.has_last_value = true;
		s.last_value = value;
		return;
	}

	const double delta = value - s.last_value;
	s.last_value = value;
	if(compare(delta, r.op, r.delta_threshold)) {
		if(!s.active) {
			s.active = true;
			emit_alert(now, r, entry, "detected", value, json{
				{"metric", r.metric},
				{"value", value},
				{"delta", delta},
				{"threshold", r.delta_threshold},
			});
		}
		s.last_error_time = now;
		return;
	}

	if(s.active && (now - s.last_error_time) >= r.recover_after_sec) {
		s.active = false;
		emit_alert(now, r, entry, "recovered", value, json{
			{"metric", r.metric},
			{"value", value},
