timeline_sink::hourly_slot timeline_sink::slot_for(double now) {
	auto tm = utc_tm(now);
	return hourly_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
		.hour = tm.tm_hour,
	};
}

timeline_sink::minute_slot timeline_sink::minute_slot_for(double now) {
	auto tm = utc_tm(now);
	return minute_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
		.hour = tm.tm_hour,
		.minute = tm.tm_min,
	};
