json topology_projector::build(double time,
                               const json::array_t &streams_list,
                               const json::array_t &interface_list,
                               const json::array_t &metrics_list) const {
	const auto interface_names = build_interface_names(interface_list);
	const auto metric_index = build_metric_index(metrics_list);
	std::unordered_map<std::string, json> node_map;
	json::array_t edges;

	for(const auto &entry : streams_list) {
		if(!entry.is_object() || !entry.contains("stream") || !entry["stream"].is_object()) {
			continue;
		}
		const std::string proto = entry.value("proto", std::string{});
		const auto &stream = entry["stream"];
		const std::string stream_key = stream.value("stream_key", std::string{});
		if(stream_key.empty() || !stream.contains("flows") || !stream["flows"].is_array()) {
			continue;
		}

		for(const auto &flow : stream["flows"]) {
			if(!flow.is_object() || !flow.contains("endpoint") || !flow["endpoint"].is_object()) {
				continue;
			}
			const std::string flow_key = flow.value("flow_key", std::string{});
			if(flow_key.empty()) {
				continue;
			}
			const auto metrics_it = metric_index.find(metric_key(stream_key, flow_key));
			const json *metric_entry = (metrics_it == metric_index.end()) ? nullptr : &metrics_it->second.metrics;
			const auto &endpoint = flow["endpoint"];
			const auto src = parse_endpoint(endpoint.value("src", std::string{}));
			const auto dst = parse_endpoint(endpoint.value("dst", std::string{}));
			if(src.host.empty() || dst.host.empty()) {
				continue;
			}

			const std::string transport = transport_from_entry(entry, flow, metric_entry);
			json src_node = make_node_for_endpoint(src, transport);
			json dst_node = make_node_for_endpoint(dst, transport);
			const std::string src_id = src_node.value("id", std::string{});
			const std::string dst_id = dst_node.value("id", std::string{});
			if(src_id.empty() || dst_id.empty()) {
				continue;
			}
			upsert_node(node_map, std::move(src_node));
			upsert_node(node_map, std::move(dst_node));

			json edge{
				{"id", "flow:" + flow_key},
				{"type", "flow"},
				{"src", src_id},
				{"dst", dst_id},
				{"proto", proto},
				{"transport", transport},
				{"state", "active"},
				{"scope", make_scope(stream, flow, interface_names)},
				{"identity", {
					{"stream_key", stream_key},
					{"flow_key", flow_key},
				}},
				{"endpoint", {
					{"src", endpoint.value("src", std::string{})},
					{"dst", endpoint.value("dst", std::string{})},
				}},
			};
			if(flow.contains("role")) {
				edge["role"] = flow["role"];
			}
			if(metric_entry != nullptr) {
				edge["metrics"] = summarize_metrics(*metric_entry);
			}
			edges.push_back(std::move(edge));
		}
	}

	json::array_t nodes;
	std::vector<std::string> keys;
	keys.reserve(node_map.size());
	for(const auto &[key, _] : node_map) {
		keys.push_back(key);
	}
	std::sort(keys.begin(), keys.end());
	for(const auto &key : keys) {
		nodes.push_back(std::move(node_map[key]));
	}
	std::sort(edges.begin(), edges.end(), [](const json &a, const json &b) {
		return a.value("id", std::string{}) < b.value("id", std::string{});
	});

	return json{
		{"time", time},
		{"nodes", std::move(nodes)},
		{"edges", std::move(edges)},
	};
}

std::unordered_map<std::string, std::string> topology_projector::build_interface_names(const json::array_t &interface_list) {
	std::unordered_map<std::string, std::string> out;
	for(const auto &entry : interface_list) {
		if(!entry.is_object()) {
			continue;
		}
		const auto id = json_string_or_empty(entry, "interface_id");
		const auto name = json_string_or_empty(entry, "name");
		if(!id.empty() && !name.empty()) {
			out[id] = name;
		}
	}
	return out;
}

std::unordered_map<std::string, topology_projector::metric_summary> topology_projector::build_metric_index(const json::array_t &metrics_list) {
	std::unordered_map<std::string, metric_summary> out;
	for(const auto &entry : metrics_list) {
		if(!entry.is_object() || !entry.contains("flow_key")) {
			continue;
		}
		const auto stream_key = entry.value("stream_key", std::string{});
		const auto flow_key = entry.value("flow_key", std::string{});
		if(stream_key.empty() || flow_key.empty()) {
			continue;
		}
		out[metric_key(stream_key, flow_key)] = metric_summary{.metrics = entry};
	}
	return out;
}

std::string topology_projector::metric_key(const std::string &stream_key, const std::string &flow_key) {
	return stream_key + "\n" + flow_key;
}

topology_projector::endpoint_parts topology_projector::parse_endpoint(const std::string &value) {
	endpoint_parts out;
	if(value.empty()) {
		return out;
	}
	if(value.front() == '[') {
		const auto close = value.find(']');
		if(close == std::string::npos) {
			out.host = value;
			return out;
		}
		out.host = value.substr(1, close - 1);
		if(close + 1 < value.size() && value[close + 1] == ':') {
			out.port = std::atoi(value.c_str() + close + 2);
			out.has_port = true;
		}
		return out;
	}

	const auto colon = value.rfind(':');
	if(colon == std::string::npos || value.find(':') != colon) {
		out.host = value;
		return out;
	}
	out.host = value.substr(0, colon);
	out.port = std::atoi(value.c_str() + colon + 1);
	out.has_port = true;
	return out;
}

std::string topology_projector::transport_from_entry(const json &stream_entry, const json &flow_entry, const json *metric_entry) {
	for(const json *candidate : {&flow_entry, metric_entry}) {
		if(candidate != nullptr && candidate->is_object() && candidate->contains("ip_proto") && (*candidate)["ip_proto"].is_number_integer()) {
			const auto transport = transport_from_ip_proto((*candidate)["ip_proto"].get<int>());
			if(transport != "unknown") {
				return transport;
			}
		}
	}
	return transport_from_proto(stream_entry.value("proto", std::string{}));
}

std::string topology_projector::transport_from_ip_proto(int ip_proto) {
	switch(ip_proto) {
	case 6: return "tcp";
	case 17: return "udp";
	case 1: return "icmp";
	case 58: return "icmpv6";
	case 2: return "igmp";
	default: return "unknown";
	}
}

std::string topology_projector::transport_from_proto(const std::string &proto) {
	const auto p = upper(proto);
	if(p == "ARP") return "arp";
	if(p == "ICMP") return "icmp";
	if(p == "ICMPV6") return "icmpv6";
	if(p == "IGMP") return "igmp";
	if(p == "TCP" || p == "HTTP" || p == "HTTPS" || p == "SSH" || p == "RTMP") return "tcp";
	if(p == "UDP" || p == "RTP" || p == "SRT" || p == "NTP" || p == "DHCP" || p == "DNS" || p == "MDNS" || p == "SSDP") return "udp";
	return "unknown";
}

bool topology_projector::is_group_host(const std::string &host) {
	return is_ipv4_broadcast(host) || is_ipv4_multicast(host) || is_ipv6_multicast(host);
}

bool topology_projector::is_ipv4_broadcast(const std::string &host) {
	return host == "255.255.255.255";
}

bool topology_projector::is_ipv4_multicast(const std::string &host) {
	int a = -1, b = -1, c = -1, d = -1;
	char tail = 0;
	std::istringstream iss(host);
	if(!(iss >> a)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> b)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> c)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> d)) return false;
	if(iss >> tail) return false;
	return a >= 224 && a <= 239 && b >= 0 && b <= 255 && c >= 0 && c <= 255 && d >= 0 && d <= 255;
}

bool topology_projector::is_ipv6_multicast(const std::string &host) {
	return lower(host).rfind("ff", 0) == 0;
}

std::string topology_projector::node_id_for_endpoint(const endpoint_parts &endpoint, const std::string &transport) {
	if(is_group_host(endpoint.host)) {
		return "group:" + endpoint.host + (endpoint.has_port ? ":" + std::to_string(endpoint.port) + "/" + transport : "");
	}
	if(endpoint.has_port && endpoint.port != 0 && transport != "icmp" && transport != "icmpv6" && transport != "igmp") {
		return "service:" + endpoint.host + ":" + std::to_string(endpoint.port) + "/" + transport;
	}
	return "host:" + endpoint.host;
}

json topology_projector::make_node_for_endpoint(const endpoint_parts &endpoint, const std::string &transport) {
	const auto id = node_id_for_endpoint(endpoint, transport);
	json node{
		{"id", id},
		{"label", id.substr(id.find(':') + 1)},
	};
	if(id.rfind("group:", 0) == 0) {
		node["type"] = "group";
		node["host"] = endpoint.host;
		if(endpoint.has_port) node["port"] = endpoint.port;
		node["transport"] = transport;
	}
	else if(id.rfind("service:", 0) == 0) {
		node["type"] = "service";
		node["host"] = endpoint.host;
		node["port"] = endpoint.port;
		node["transport"] = transport;
	}
	else {
		node["type"] = "host";
		node["host"] = endpoint.host;
	}
	return node;
}

json topology_projector::make_scope(const json &stream, const json &flow, const std::unordered_map<std::string, std::string> &interface_names) {
	json scope{
		{"interface_id", stream.contains("interface_id") ? stream["interface_id"] : json(nullptr)},
		{"interface_name", nullptr},
		{"vlan", nullptr},
	};
	const auto id = json_string_or_empty(scope, "interface_id");
	const auto it = interface_names.find(id);
	if(it != interface_names.end()) {
		scope["interface_name"] = it->second;
	}
	if(flow.contains("vlan") && !flow["vlan"].is_null()) {
		scope["vlan"] = flow["vlan"];
	}
	else if(stream.contains("vlan") && !stream["vlan"].is_null()) {
		scope["vlan"] = stream["vlan"];
	}
	return scope;
}

json topology_projector::summarize_metrics(const json &entry) {
	json out = json::object();
	double value = 0.0;
	if(entry.contains("bitrate") && number_value(entry["bitrate"], "bps", value)) {
		out["bitrate_bps"] = value;
	}
	if(entry.contains("packet_rate") && number_value(entry["packet_rate"], "pps", value)) {
		out["packet_rate_pps"] = value;
	}
	if(entry.contains("packet_count") && number_value(entry["packet_count"], "window", value)) {
		out["packet_count_window"] = value;
	}
	if(entry.contains("jitter") && number_value(entry["jitter"], "seconds", value)) {
		out["jitter_seconds"] = value;
	}
	if(entry.contains("rtt") && number_value(entry["rtt"], "value", value)) {
		out["rtt"] = value;
	}
	if(entry.contains("seq_stats") && entry["seq_stats"].is_object()) {
		json seq = json::object();
		for(const auto &name : {"gap", "dup", "reorder"}) {
			if(entry["seq_stats"].contains(name) && number_value(entry["seq_stats"][name], "window", value)) {
				seq[std::string(name) + "_window"] = value;
			}
		}
		if(!seq.empty()) {
			out["seq_stats"] = std::move(seq);
		}
	}
	return out;
}

void topology_projector::upsert_node(std::unordered_map<std::string, json> &nodes, json node) {
	const auto id = node.value("id", std::string{});
	if(id.empty()) {
		return;
	}
	nodes.emplace(id, std::move(node));
}
