json topology_projector::summarize_alerts(const std::vector<json> &alerts) {
	json::array_t compact;
	std::string severity = "info";
	int rank = 0;
	for(const auto &alert : alerts) {
		const auto alert_severity = json_string_or_empty(alert, "severity");
		const int alert_rank = severity_rank(alert_severity);
		if(alert_rank >= rank && !alert_severity.empty()) {
			rank = alert_rank;
			severity = alert_severity;
		}
		compact.push_back(compact_alert(alert));
	}
	return json{
		{"state", "active"},
		{"severity", severity},
		{"count", compact.size()},
		{"alerts", std::move(compact)},
	};
}

int topology_projector::severity_rank(const std::string &severity) {
	const auto s = lower(severity);
	if(s == "fatal" || s == "critical") return 4;
	if(s == "error") return 3;
	if(s == "warning" || s == "warn") return 2;
	if(s == "info") return 1;
	return 0;
}

void topology_projector::append_matching_alerts(std::vector<json> &out, const alert_index &alerts, const std::string &stream_key, const std::string &flow_key, const json &scope) {
	auto append_from = [&out](const auto &map, const std::string &key) {
		const auto it = map.find(key);
		if(it == map.end()) {
			return;
		}
		out.insert(out.end(), it->second.begin(), it->second.end());
	};
	append_from(alerts.by_flow, metric_key(stream_key, flow_key));
	append_from(alerts.by_stream, stream_key);
	const auto interface_id = json_string_or_empty(scope, "interface_id");
	if(!interface_id.empty()) {
		append_from(alerts.by_interface, "id:" + interface_id);
	}
	const auto interface_name = json_string_or_empty(scope, "interface_name");
	if(!interface_name.empty()) {
		append_from(alerts.by_interface, "name:" + interface_name);
	}
}

void topology_projector::merge_node_alert(std::unordered_map<std::string, json> &nodes, const std::string &node_id, const json &alert_summary) {
	auto it = nodes.find(node_id);
	if(it == nodes.end() || !alert_summary.is_object() || !alert_summary.contains("alerts") || !alert_summary["alerts"].is_array()) {
		return;
	}
	auto &node = it->second;
	if(!node.contains("alert") || !node["alert"].is_object()) {
		node["alert"] = json{
			{"state", "active"},
			{"severity", alert_summary.value("severity", std::string{"info"})},
			{"count", 0},
			{"alerts", json::array()},
		};
	}
	auto &node_alert = node["alert"];
	for(const auto &alert : alert_summary["alerts"]) {
		const auto id = alert_identity(alert);
		bool exists = false;
		for(const auto &existing : node_alert["alerts"]) {
			if(!id.empty() && alert_identity(existing) == id) {
				exists = true;
				break;
			}
		}
		if(!exists) {
			node_alert["alerts"].push_back(alert);
		}
	}
	node_alert["count"] = node_alert["alerts"].size();
	if(severity_rank(alert_summary.value("severity", std::string{})) > severity_rank(node_alert.value("severity", std::string{}))) {
		node_alert["severity"] = alert_summary["severity"];
	}
}

void topology_projector::upsert_node(std::unordered_map<std::string, json> &nodes, json node) {
	const auto id = node.value("id", std::string{});
	if(id.empty()) {
		return;
	}
	nodes.emplace(id, std::move(node));
}

