class sequence_stats {
public:
    struct update_result {
        bool updated{false};
        std::uint64_t seq{0};

        bool duplicate{false};
        bool reordered{false};
        std::uint64_t gap_added{0};
    };

public:
    void reset() {
        initialized_ = false;
        last_seq_ = 0;
        gap_count_.reset_all();
        reorder_count_.reset_all();
        dup_count_.reset_all();
    }

    void reset_stats() {
        gap_count_.reset();
        reorder_count_.reset();
        dup_count_.reset();
    }

    update_result update(std::uint64_t seq) {
        update_result r{};
        r.updated = true;
        r.seq = seq;

        if (!initialized_) {
            initialized_ = true;
            last_seq_ = seq;
            return r;
        }

        if (seq == last_seq_) {
            dup_count_.inc();
            r.duplicate = true;
            return r;
        }

        if (seq == last_seq_ + 1) {
            last_seq_ = seq;
            return r;
        }

        if (seq > last_seq_ + 1) {
            const std::uint64_t gap = seq - last_seq_ - 1;
            gap_count_.add(gap);
            r.gap_added = gap;
            last_seq_ = seq;
            return r;
        }

        reorder_count_.inc();
        r.reordered = true;
        return r;
    }

    const counter& gap_count() const {
        return gap_count_;
    }

    const counter& reorder_count() const {
        return reorder_count_;
    }

    const counter& dup_count() const {
        return dup_count_;
    }

    std::uint64_t last_seq() const {
        return last_seq_;
    }

    bool initialized() const {
        return initialized_;
    }

private:
    bool initialized_{false};
    std::uint64_t last_seq_{0};

    counter gap_count_;
    counter reorder_count_;
    counter dup_count_;
};

