	};
}

std::string stream_id::to_stream_key() const {
	std::ostringstream oss;
	oss << proto_name << "|if=" << interface_id << tsv::key_suffix(vlan)
	    << "|playlist=" << endpoint_text(host, port, playlist_path);
	return oss.str();
}

std::size_t stream_id_hash::operator()(const stream_id& v) const noexcept {
	std::size_t h = 0;
	hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
	hash_combine(h, std::hash<std::string>{}(v.host));
	hash_combine(h, std::hash<std::uint16_t>{}(v.port));
	hash_combine(h, std::hash<std::string>{}(v.playlist_path));
	hash_combine(h, tsv::hash_value(v.vlan));
	return h;
}

flow_id flow_id::from_request(std::uint32_t interface_id,
                              std::string_view host,
                              std::uint16_t port,
                              std::string_view path,
                              std::string_view role,
                              tsv::vlan_info vlan) {
	return flow_id{
		.interface_id = interface_id,
		.host = std::string(host),
		.port = port,
		.path = std::string(path),
		.role = std::string(role),
		.vlan = std::move(vlan),
	};
}

std::string flow_id::to_flow_key(const stream_id& sid) const {
	std::ostringstream oss;
	oss << sid.to_stream_key() << "|role=" << role << "|resource=" << endpoint_text(host, port, path);
	return oss.str();
}

std::size_t flow_id_hash::operator()(const flow_id& v) const noexcept {
	std::size_t h = 0;
	hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
	hash_combine(h, std::hash<std::string>{}(v.host));
	hash_combine(h, std::hash<std::uint16_t>{}(v.port));
	hash_combine(h, std::hash<std::string>{}(v.path));
	hash_combine(h, std::hash<std::string>{}(v.role));
	hash_combine(h, tsv::hash_value(v.vlan));
	return h;
}

void status_counters::update(std::uint16_t status) {
	total.inc();
	if(status >= 200 && status < 300) s2xx.inc();
	else if(status >= 300 && status < 400) s3xx.inc();
	else if(status >= 400 && status < 500) s4xx.inc();
	else if(status >= 500 && status < 600) s5xx.inc();
	else other.inc();
}

void status_counters::reset_window() {
	total.reset();
	s2xx.reset();
	s3xx.reset();
	s4xx.reset();
	s5xx.reset();
	other.reset();
}

flow::flow(const stream_id &sid, const flow_id fid, std::string interface_name, double error_recovery_sec, event_sink &events)
	: m_fid(std::move(fid))
	, m_stream_key(sid.to_stream_key())
	, m_flow_key(m_fid.to_flow_key(sid))
	, m_interface_name(std::move(interface_name))
	, m_error_state(error_recovery_sec)
	, m_event_source(stream_json::make_flow_event_source(proto_name,
	                                                    m_fid.interface_id,
	                                                    m_interface_name,
	                                                    m_stream_key,
	                                                    m_flow_key,
	                                                    m_fid.vlan))
	, m_events(events) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.status_code);
		if(i.status_code >= 400) {
			m_metrics.error_count.inc();
			++m_error_window;
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			m_metrics.download_time.add(i.time_epoch - i.request_time);
		}
	}
	return 0;
}

event_record flow::make_event(double now, std::string type, json detail) const {
	return event_record{
		.time_epoch = now,
		.type = std::move(type),
		.source = m_event_source,
		.detail = std::move(detail),
	};
}

void flow::emit_detected(double now) {
	m_events.emit(make_event(now, "flow_detected", json{
		{"role", m_fid.role},
		{"endpoint", {
			{"host", m_fid.host},
			{"port", m_fid.port},
			{"path", m_fid.path},
		}},
	}));
}

void flow::emit_lost(double now) {
	m_events.emit(make_event(now, "flow_lost", json{
		{"role", m_fid.role},
		{"endpoint", {
			{"host", m_fid.host},
			{"port", m_fid.port},
			{"path", m_fid.path},
		}},
		{"last_seen", last_seen()},
	}));
}

int flow::append_metrics(double now, json::array_t &out) {
	const auto bitrate = m_metrics.bitrate.snapshot_at(now);
	json j = stream_json::make_flow_metrics_base(proto_name,
	                                             m_fid.interface_id,
	                                             m_interface_name,
	                                             m_stream_key,
	                                             m_flow_key,
	                                             m_fid.vlan);
	j["role"] = m_fid.role;
	j["endpoint"] = {
		{"host", m_fid.host},
		{"port", m_fid.port},
		{"path", m_fid.path},
	};
	j.update(json{
		{"request_count", { {"window", m_metrics.request_count.count()}, {"total", m_metrics.request_count.total()} }},
		{"response_count", { {"window", m_metrics.response_count.count()}, {"total", m_metrics.response_count.total()} }},
		{"error_count", { {"window", m_metrics.error_count.count()}, {"total", m_metrics.error_count.total()} }},
		{"download_bytes", { {"window", m_metrics.download_bytes.count()}, {"total", m_metrics.download_bytes.total()} }},
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"request_interval", {
			{"seconds", m_metrics.request_interval.value()},
			{"count", m_metrics.request_interval.stats().count},
			{"min", m_metrics.request_interval.stats().min},
			{"max", m_metrics.request_interval.stats().max},
			{"avg", m_metrics.request_interval.stats().avg()},
		}},
		{"download_time", stats_json(m_metrics.download_time)},
		{"status", status_json(m_metrics.status)},
		{"duration", {
			{"seconds", m_metrics.lifetime.duration_sec()},
			{"first_seen", m_metrics.lifetime.first_seen()},
			{"last_seen", m_metrics.lifetime.last_seen()},
		}},
	});

	out.push_back(std::move(j));
	m_metrics_emitted = true;
	m_metrics.request_count.reset();
	m_metrics.response_count.reset();
	m_metrics.error_count.reset();
	m_metrics.download_bytes.reset();
	m_metrics.bitrate.clear_stats();
	m_metrics.request_interval.clear_stats();
	m_metrics.download_time.clear();
	m_metrics.status.reset_window();
	return 0;
}

json flow::to_list_json(double now) const {
	(void)now;
	json j = stream_json::make_flow_list_base(m_flow_key,
	                                         m_fid.interface_id,
	                                         m_interface_name,
	                                         m_fid.vlan);
	j["role"] = m_fid.role;
	j["endpoint"] = {
		{"host", m_fid.host},
		{"port", m_fid.port},
		{"path", m_fid.path},
	};
	j["last_seen"] = last_seen();
	return j;
}

int flow::update_events(double now) {
	const auto update = m_error_state.update(now, m_error_window);
	if(update.occurred) {
		m_events.emit(make_event(now, m_fid.role + "_error_occurred", json{
			{"role", m_fid.role},
			{"window_count", update.window_count},
			{"endpoint", { {"host", m_fid.host}, {"port", m_fid.port}, {"path", m_fid.path} }},
			{"severity", "warning"},
		}));
	}
	if(update.recovered) {
		m_events.emit(make_event(now, m_fid.role + "_error_recovered", json{
			{"role", m_fid.role},
			{"active_total", update.active_total},
			{"endpoint", { {"host", m_fid.host}, {"port", m_fid.port}, {"path", m_fid.path} }},
			{"severity", "info"},
		}));
	}
	m_error_window = 0;
	return 0;
}

stream::stream(const stream_id sid, std::string interface_name, config cfg, event_sink &events)
	: m_sid(std::move(sid))
