			{"host", m_sid.host},
			{"port", m_sid.port},
			{"playlist", m_sid.playlist_path},
		}},
		{"last_seen", last_seen()},
		{"flow_count", m_flows.size()},
	}));
	trace(1, "hls: stream lost %s", endpoint_text(m_sid.host, m_sid.port, m_sid.playlist_path).c_str());
}

flow_id stream::resolve_flow_id(const info &i) const {
	return flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
}

int stream::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(i.role == "playlist" && i.is_request) {
		m_has_playlist = true;
		m_playlist_last_seen = i.time_epoch;
	}
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.status_code);
		if(i.status_code >= 400) {
			m_metrics.error_count.inc();
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			m_metrics.download_time.add(i.time_epoch - i.request_time);
		}
	}

	const auto fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->process(i);
}

int stream::append_metrics(double now, json::array_t &out) {
	const auto bitrate = m_metrics.bitrate.snapshot_at(now);
	json j = stream_json::make_stream_metrics_base(proto_name,
	                                               m_sid.interface_id,
	                                               m_interface_name,
	                                               m_stream_key,
	                                               m_sid.vlan);
	j["endpoint"] = {
		{"host", m_sid.host},
		{"port", m_sid.port},
		{"playlist", m_sid.playlist_path},
	};
	j.update(json{
		{"request_count", { {"window", m_metrics.request_count.count()}, {"total", m_metrics.request_count.total()} }},
		{"response_count", { {"window", m_metrics.response_count.count()}, {"total", m_metrics.response_count.total()} }},
		{"error_count", { {"window", m_metrics.error_count.count()}, {"total", m_metrics.error_count.total()} }},
		{"download_bytes", { {"window", m_metrics.download_bytes.count()}, {"total", m_metrics.download_bytes.total()} }},
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"request_interval", {
			{"seconds", m_metrics.request_interval.value()},
			{"count", m_metrics.request_interval.stats().count},
			{"min", m_metrics.request_interval.stats().min},
			{"max", m_metrics.request_interval.stats().max},
			{"avg", m_metrics.request_interval.stats().avg()},
		}},
		{"download_time", stats_json(m_metrics.download_time)},
		{"status", status_json(m_metrics.status)},
		{"duration", {
			{"seconds", m_metrics.lifetime.duration_sec()},
			{"first_seen", m_metrics.lifetime.first_seen()},
			{"last_seen", m_metrics.lifetime.last_seen()},
		}},
	});
	out.push_back(std::move(j));

	m_metrics.request_count.reset();
	m_metrics.response_count.reset();
	m_metrics.error_count.reset();
	m_metrics.download_bytes.reset();
	m_metrics.bitrate.clear_stats();
	m_metrics.request_interval.clear_stats();
	m_metrics.download_time.clear();
	m_metrics.status.reset_window();

	for(auto& [fid, flow] : m_flows) {
		flow->append_metrics(now, out);
	}
	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	json::array_t flows;
	for(auto& [fid, flow] : m_flows) {
		flows.push_back(flow->to_list_json(now));
	}
	json stream_entry = stream_json::make_stream_list_base(m_sid.interface_id,
	                                                     m_interface_name,
	                                                     m_stream_key,
	                                                     m_sid.vlan);
	stream_entry["endpoint"] = {
		{"host", m_sid.host},
		{"port", m_sid.port},
		{"playlist", m_sid.playlist_path},
	};
	stream_entry["last_seen"] = last_seen();
	stream_entry["flow_count"] = m_flows.size();
	stream_entry["flows"] = std::move(flows);
	out.push_back(json{
		{"proto", proto_name},
		{"stream", std::move(stream_entry)},
	});
	return 0;
}

int stream::update_events(double now) {
	for(auto& [fid, flow] : m_flows) {
		flow->update_events(now);
	}
	if(m_has_playlist && (now - m_playlist_last_seen) >= m_cfg.timeout.playlist_stall_sec) {
		if(m_playlist_stall_state.occur(now)) {
			m_events.emit(make_event(now, "playlist_stalled_occurred", json{
				{"last_playlist_seen", m_playlist_last_seen},
				{"stall_seconds", now - m_playlist_last_seen},
				{"severity", "warning"},
			}));
		}
	}
	else if(m_playlist_stall_state.recover(now)) {
		m_events.emit(make_event(now, "playlist_stalled_recovered", json{
			{"last_playlist_seen", m_playlist_last_seen},
			{"severity", "info"},
		}));
	}
	if(m_playlist_stall_state.update(now)) {
		m_events.emit(make_event(now, "playlist_stalled_recovered", json{
			{"last_playlist_seen", m_playlist_last_seen},
			{"severity", "info"},
		}));
	}
	return 0;
}

void stream::expire_flows(double now, double flow_idle_sec) {
	for(auto it = m_flows.begin(); it != m_flows.end(); ) {
		if(it->second->metrics_emitted() && it->second->expired(now, flow_idle_sec)) {
			it->second->emit_lost(now);
			it = m_flows.erase(it);
		}
		else {
			++it;
		}
	}
}

streams::streams(config cfg, event_sink &events)
    : m_cfg(std::move(cfg))
    , m_events(events) {
}

std::string streams::host_key(std::uint32_t interface_id, std::string_view host, std::uint16_t port, const tsv::vlan_info &vlan) const {
	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << host << ':' << port;
	return oss.str();
}

stream_id streams::resolve_stream_id(const info &i) const {
	std::string playlist = i.role == "playlist" ? i.path : std::string{};
	if(playlist.empty()) {
		const auto it = m_last_playlist_by_host.find(host_key(i.interface_id, i.host, i.port, i.vlan));
		playlist = it == m_last_playlist_by_host.end() ? unknown_playlist : it->second;
	}
	return stream_id::from_playlist(i.interface_id, i.host, i.port, playlist, i.vlan);
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return 0;
	}

	stream_id sid;
	flow_id fid;
	if(i.is_response) {
		if(!i.has_tcp_stream) {
			return 0;
		}
		auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
		if(pending == m_pending_by_tcp_stream.end()) {
			return 0;
		}
		sid = pending->second.sid;
		fid = pending->second.fid;
		i.host = fid.host;
		i.port = fid.port;
		i.path = fid.path;
		i.role = fid.role;
		i.request_time = pending->second.request_time;
		i.has_request_time = true;
	}
	else {
		sid = resolve_stream_id(i);
		fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
		if(i.role == "playlist") {
			m_last_playlist_by_host[host_key(i.interface_id, i.host, i.port, i.vlan)] = i.path;
		}
		if(i.has_tcp_stream) {
			m_pending_by_tcp_stream[i.tcp_stream] = pending_request{sid, fid, i.time_epoch};
		}
	}

	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid, i.interface_name, m_cfg, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}

	const int rc = it->second->process(i);
	if(i.is_response && i.has_tcp_stream) {
		m_pending_by_tcp_stream.erase(i.tcp_stream);
	}
	expire_streams(i.time_epoch);
	return rc;
}

int streams::append_metrics(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		stream->append_metrics(now, out);
	}
	return 0;
}

int streams::update_events(double now) {
	expire_streams(now);
	for(auto& [sid, stream] : m_streams) {
		stream->update_events(now);
	}
	return 0;
}

int streams::append_list(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		stream->append_list(now, out);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.interface_id], i.interface_id);
	tsv::to_string(row[c.i.com.interface_name], i.interface_name);
	i.frame_len = c.r.com.frame_len;
	tsv::to_number(row[c.i.com.frame_len], i.frame_len);
	i.vlan = tsv::vlan_info{
		.id = std::string(tsv::field_or_empty(row, c.i.com.vlan_id)),
		.priority = std::string(tsv::field_or_empty(row, c.i.com.vlan_priority)),
		.dei = std::string(tsv::field_or_empty(row, c.i.com.vlan_dei)),
	};

	parse_ip(tsv::field_or_empty(row, c.i.com.ip_src), tsv::field_or_empty(row, c.i.com.ipv6_src), i.src.addr);
	parse_ip(tsv::field_or_empty(row, c.i.com.ip_dst), tsv::field_or_empty(row, c.i.com.ipv6_dst), i.dst.addr);
	std::uint32_t port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_srcport), port) && port <= 65535U) {
		i.src.port = static_cast<std::uint16_t>(port);
	}
	port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_dstport), port) && port <= 65535U) {
		i.dst.port = static_cast<std::uint16_t>(port);
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_stream), i.tcp_stream)) {
		i.has_tcp_stream = true;
	}

	i.method = std::string(tsv::field_or_empty(row, c.i.http.method));
	i.path = std::string(tsv::field_or_empty(row, c.i.http.uri));
	i.host = std::string(tsv::field_or_empty(row, c.i.http.host));
	i.is_request = !i.method.empty() && !i.path.empty();

	std::uint32_t status = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.status_code), status) && status <= 999U) {
		i.status_code = static_cast<std::uint16_t>(status);
		i.is_response = i.status_code > 0;
	}

	std::uint64_t len = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.content_length), len)) {
		i.content_length = len;
		i.has_content_length = true;
	}

	if(!i.is_request && !i.is_response) {
		return -1;
	}
	if(i.is_response) {
		return 0;
	}

	i.port = endpoint_port(i.dst, 80);
	parse_absolute_uri(i.host, i.port, i.path);
	if(i.host.empty()) {
		i.host = to_string(i.dst.addr);
	}
	split_host_port(i.host, i.port);
	i.role = classify_role(i.path);
	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);
		if(it->second->empty() && it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			it->second->emit_lost(now);
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

