int flow::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.status_code);
		if(i.status_code >= 400) {
			m_metrics.error_count.inc();
			++m_error_window;
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			m_metrics.download_time.add(i.time_epoch - i.request_time);
		}
	}
	return 0;
}

