stream_id streams::resolve_stream_id(const info &i) const {
	std::string playlist = i.role == "playlist" ? i.path : std::string{};
	if(playlist.empty()) {
		const auto it = m_last_playlist_by_host.find(host_key(i.interface_id, i.host, i.port, i.vlan));
		playlist = it == m_last_playlist_by_host.end() ? unknown_playlist : it->second;
	}
	return stream_id::from_playlist(i.interface_id, i.host, i.port, playlist, i.vlan);
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return 0;
	}

	stream_id sid;
	flow_id fid;
	if(i.is_response) {
		bool matched = false;
		pending_request req{};
		auto conn = m_pending_by_connection.find(connection_key(i));
		if(conn != m_pending_by_connection.end() && !conn->second.empty()) {
			req = conn->second.front();
			conn->second.pop_front();
			if(conn->second.empty()) {
				m_pending_by_connection.erase(conn);
			}
			matched = true;
		}
		else if(i.has_tcp_stream) {
			auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
			if(pending != m_pending_by_tcp_stream.end()) {
				req = pending->second;
				matched = true;
			}
		}
		if(!matched) {
			return 0;
		}
		sid = req.sid;
		fid = req.fid;
		i.host = fid.host;
		i.port = fid.port;
		i.path = fid.path;
		i.role = fid.role;
		i.request_time = req.request_time;
		i.has_request_time = true;
	}
	else {
		const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
		const bool has_known_playlist = m_last_playlist_by_host.find(hk) != m_last_playlist_by_host.end();
		if(i.role == "other" && !has_known_playlist) {
			return 0;
		}
		sid = resolve_stream_id(i);
		fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
		if(i.role == "playlist") {
			m_last_playlist_by_host[hk] = i.path;
		}
		pending_request req{sid, fid, i.time_epoch};
		m_pending_by_connection[connection_key(i)].push_back(req);
		if(i.has_tcp_stream) {
			m_pending_by_tcp_stream[i.tcp_stream] = req;
		}
	}

	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid, i.interface_name, m_cfg, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}

	const int rc = it->second->process(i);
	if(i.is_response && i.has_tcp_stream) {
		m_pending_by_tcp_stream.erase(i.tcp_stream);
	}
	expire_streams(i.time_epoch);
	return rc;
}

