std::string streams::host_key(std::uint32_t interface_id, std::string_view host, std::uint16_t port, const tsv::vlan_info &vlan) const {
	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << host << ':' << port;
	return oss.str();
}

std::string streams::connection_key(const info &i) const {
	std::string a = endpoint_key(i.src);
	std::string b = endpoint_key(i.dst);
	if(b < a) {
		std::swap(a, b);
	}
	std::ostringstream oss;
	oss << i.interface_id << tsv::key_suffix(i.vlan) << '|' << a << "<->" << b;
	return oss.str();
}

stream_id streams::resolve_stream_id(const info &i) const {
	std::string playlist = i.role == "playlist" ? i.path : std::string{};
	if(playlist.empty()) {
		const auto it = m_last_playlist_by_host.find(host_key(i.interface_id, i.host, i.port, i.vlan));
		playlist = it == m_last_playlist_by_host.end() ? unknown_playlist : it->second;
	}
	return stream_id::from_playlist(i.interface_id, i.host, i.port, playlist, i.vlan);
}

bool streams::same_request(const pending_request &lhs, const pending_request &rhs) const {
	return lhs.sid == rhs.sid &&
	       lhs.fid == rhs.fid &&
	       lhs.request_time == rhs.request_time;
}

bool streams::pop_connection_pending(const std::string &conn_key, const pending_request &req) {
	auto conn = m_pending_by_connection.find(conn_key);
	if(conn == m_pending_by_connection.end() || conn->second.empty()) {
		return false;
	}
	if(!same_request(conn->second.front(), req)) {
		return false;
	}
	conn->second.pop_front();
	if(conn->second.empty()) {
		m_pending_by_connection.erase(conn);
	}
	return true;
}

void streams::erase_tcp_pending(const pending_request &req) {
	for(auto it = m_pending_by_tcp_stream.begin(); it != m_pending_by_tcp_stream.end(); ) {
		if(same_request(it->second, req)) {
			it = m_pending_by_tcp_stream.erase(it);
		}
		else {
			++it;
		}
	}
}

int streams::process_resolved(const stream_id &sid, const flow_id &fid, const info &i) {
	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		it = m_streams.emplace(sid, std::make_unique<stream>(sid, i.interface_name, m_cfg, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}

	const int rc = it->second->process(i);
	expire_streams(i.time_epoch);
	return rc;
}

int streams::process_response(info i, const pending_request &req, const char *matched_by, std::size_t conn_pending, const std::string &conn_key) {
	i.host = req.fid.host;
	i.port = req.fid.port;
	i.path = req.fid.path;
	i.role = req.fid.role;
	i.is_response = true;
	i.request_time = req.request_time;
	i.has_request_time = true;
	trace(3, "hls: response matched by=%s status=%u tcp_payload=%d tcp_len=%u role=%s path=%s conn=%s conn_pending_before=%zu response_time=%.6f",
	      matched_by,
	      static_cast<unsigned>(i.status_code),
	      i.has_tcp_payload ? 1 : 0,
	      static_cast<unsigned>(i.tcp_len),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      conn_pending,
	      i.time_epoch >= i.request_time ? (i.time_epoch - i.request_time) : -1.0);
	return process_resolved(req.sid, req.fid, i);
}

int streams::flush_deferred(double now) {
	int rc = 0;
	for(auto it = m_deferred_by_connection.begin(); it != m_deferred_by_connection.end(); ) {
		if((now - it->second.response.time_epoch) < m_cfg.timeout.fallback_grace_sec) {
			++it;
			continue;
		}

		auto deferred = std::move(it->second);
		it = m_deferred_by_connection.erase(it);
		if(!pop_connection_pending(deferred.conn_key, deferred.req)) {
			continue;
		}
		erase_tcp_pending(deferred.req);
		trace(3, "hls: deferred tcp fallback expired role=%s path=%s conn=%s grace=%.3f",
		      deferred.req.fid.role.c_str(),
		      deferred.req.fid.path.c_str(),
		      deferred.conn_key.c_str(),
		      m_cfg.timeout.fallback_grace_sec);
		rc |= process_response(std::move(deferred.response), deferred.req, "tcp_fallback_timeout", 1, deferred.conn_key);
	}
	return rc;
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return 0;
	}

	int rc = 0;
	if(i.is_response || (!i.is_request && i.has_tcp_payload)) {
		const bool is_tcp_fallback = !i.is_response && i.has_tcp_payload;
		bool matched = false;
		const char *matched_by = "none";
		pending_request req{};
		const std::string conn_key = connection_key(i);
		auto conn = m_pending_by_connection.find(conn_key);
		const std::size_t conn_pending = conn == m_pending_by_connection.end() ? 0U : conn->second.size();
		if(conn != m_pending_by_connection.end() && !conn->second.empty()) {
			const auto candidate = conn->second.front();
			if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
				trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
				      candidate.fid.role.c_str(),
				      candidate.fid.path.c_str(),
				      endpoint_key(i.src).c_str(),
				      endpoint_key(i.dst).c_str(),
				      static_cast<unsigned>(candidate.fid.port));
				rc |= flush_deferred(i.time_epoch);
				return rc;
			}
			req = candidate;
			matched = true;
			matched_by = "connection";
		}
		else if(i.has_tcp_stream) {
			auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
			if(pending != m_pending_by_tcp_stream.end()) {
				const auto candidate = pending->second;
				if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
					trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
					      candidate.fid.role.c_str(),
					      candidate.fid.path.c_str(),
					      endpoint_key(i.src).c_str(),
					      endpoint_key(i.dst).c_str(),
					      static_cast<unsigned>(candidate.fid.port));
					rc |= flush_deferred(i.time_epoch);
					return rc;
				}
				req = candidate;
				matched = true;
				matched_by = "tcp_stream";
			}
		}
		if(!matched) {
			trace(4, "hls: response unmatched status=%u tcp_payload=%d tcp_len=%u conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u src=%s dst=%s",
			      static_cast<unsigned>(i.status_code),
			      i.has_tcp_payload ? 1 : 0,
			      static_cast<unsigned>(i.tcp_len),
			      conn_key.c_str(),
			      conn_pending,
			      i.has_tcp_stream ? 1 : 0,
			      static_cast<unsigned>(i.tcp_stream),
			      endpoint_key(i.src).c_str(),
			      endpoint_key(i.dst).c_str());
			rc |= flush_deferred(i.time_epoch);
			return rc;
		}

		if(is_tcp_fallback) {
			if(m_deferred_by_connection.find(conn_key) == m_deferred_by_connection.end()) {
				m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key});
				trace(3, "hls: tcp fallback deferred role=%s path=%s conn=%s grace=%.3f tcp_len=%u",
				      req.fid.role.c_str(),
				      req.fid.path.c_str(),
				      conn_key.c_str(),
				      m_cfg.timeout.fallback_grace_sec,
				      static_cast<unsigned>(i.tcp_len));
			}
			else {
				trace(4, "hls: extra tcp fallback ignored while deferred conn=%s tcp_len=%u",
				      conn_key.c_str(),
				      static_cast<unsigned>(i.tcp_len));
			}
			rc |= flush_deferred(i.time_epoch);
			return rc;
		}

		m_deferred_by_connection.erase(conn_key);
		pop_connection_pending(conn_key, req);
		erase_tcp_pending(req);
		rc |= process_response(std::move(i), req, matched_by, conn_pending, conn_key);
		rc |= flush_deferred(i.time_epoch);
		return rc;
	}

	const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
	const bool has_known_playlist = m_last_playlist_by_host.find(hk) != m_last_playlist_by_host.end();
	if(i.role == "other" && !has_known_playlist) {
		trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
		      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
		rc |= flush_deferred(i.time_epoch);
		return rc;
	}
	const auto sid = resolve_stream_id(i);
	const auto fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
	if(i.role == "playlist") {
		m_last_playlist_by_host[hk] = i.path;
	}
	pending_request req{sid, fid, i.time_epoch};
	const std::string conn_key = connection_key(i);
	auto &queue = m_pending_by_connection[conn_key];
	queue.push_back(req);
	if(i.has_tcp_stream) {
		m_pending_by_tcp_stream[i.tcp_stream] = req;
	}
	trace(3, "hls: request registered method=%s role=%s path=%s conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u stream=%s flow=%s",
	      i.method.c_str(),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      queue.size(),
	      i.has_tcp_stream ? 1 : 0,
	      static_cast<unsigned>(i.tcp_stream),
	      sid.to_stream_key().c_str(),
	      fid.to_flow_key(sid).c_str());

	rc |= process_resolved(sid, fid, i);
	rc |= flush_deferred(i.time_epoch);
	return rc;
}

