flow_id stream::resolve_flow_id(const info &i) const {
	return flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
}

int stream::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	if(i.role == "playlist" && i.is_request) {
		m_has_playlist = true;
		m_playlist_last_seen = i.time_epoch;
	}
	if(i.is_request) {
		m_metrics.request_count.inc();
		m_metrics.request_interval.update(i.time_epoch);
	}
	if(i.is_response) {
		m_metrics.response_count.inc();
		m_metrics.status.update(i.effective_status_code);
		if(i.effective_status_code >= 400) {
			m_metrics.error_count.inc();
		}
		if(i.has_content_length) {
			m_metrics.download_bytes.add(i.content_length);
			m_metrics.bitrate.update(i.time_epoch, i.content_length);
		}
		if(i.has_request_time && i.time_epoch >= i.request_time) {
			m_metrics.download_time.add(i.time_epoch - i.request_time);
		}
	}

	const auto fid = resolve_flow_id(i);
	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->process(i);
}

int stream::append_metrics(double now, json::array_t &out) {
	const auto bitrate = m_metrics.bitrate.snapshot_at(now);
	json j = stream_json::make_stream_metrics_base(proto_name,
	                                               m_sid.interface_id,
	                                               m_interface_name,
	                                               m_stream_key,
	                                               m_sid.vlan);
	j["endpoint"] = {
		{"host", m_sid.host},
		{"port", m_sid.port},
		{"playlist", m_sid.playlist_path},
	};
	j.update(json{
		{"request_count", { {"window", m_metrics.request_count.count()}, {"total", m_metrics.request_count.total()} }},
		{"response_count", { {"window", m_metrics.response_count.count()}, {"total", m_metrics.response_count.total()} }},
		{"error_count", { {"window", m_metrics.error_count.count()}, {"total", m_metrics.error_count.total()} }},
		{"download_bytes", { {"window", m_metrics.download_bytes.count()}, {"total", m_metrics.download_bytes.total()} }},
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"request_interval", {
			{"seconds", m_metrics.request_interval.value()},
			{"count", m_metrics.request_interval.stats().count},
			{"min", m_metrics.request_interval.stats().min},
			{"max", m_metrics.request_interval.stats().max},
			{"avg", m_metrics.request_interval.stats().avg()},
		}},
		{"download_time", stats_json(m_metrics.download_time)},
		{"status", status_json(m_metrics.status)},
		{"duration", {
			{"seconds", m_metrics.lifetime.duration_sec()},
			{"first_seen", m_metrics.lifetime.first_seen()},
			{"last_seen", m_metrics.lifetime.last_seen()},
		}},
	});
	out.push_back(std::move(j));

	m_metrics.request_count.reset();
	m_metrics.response_count.reset();
	m_metrics.error_count.reset();
	m_metrics.download_bytes.reset();
	m_metrics.bitrate.clear_stats();
	m_metrics.request_interval.clear_stats();
	m_metrics.download_time.clear();
	m_metrics.status.reset_window();

	for(auto& [fid, flow] : m_flows) {
		flow->append_metrics(now, out);
	}
	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	json::array_t flows;
	for(auto& [fid, flow] : m_flows) {
		flows.push_back(flow->to_list_json(now));
	}
	json stream_entry = stream_json::make_stream_list_base(m_sid.interface_id,
	                                                     m_interface_name,
	                                                     m_stream_key,
	                                                     m_sid.vlan);
	stream_entry["endpoint"] = {
		{"host", m_sid.host},
		{"port", m_sid.port},
		{"playlist", m_sid.playlist_path},
	};
	stream_entry["last_seen"] = last_seen();
	stream_entry["flow_count"] = m_flows.size();
	stream_entry["flows"] = std::move(flows);
	out.push_back(json{
		{"proto", proto_name},
		{"stream", std::move(stream_entry)},
	});
	return 0;
}

int stream::update_events(double now) {
	for(auto& [fid, flow] : m_flows) {
		flow->update_events(now);
	}
	if(m_has_playlist && (now - m_playlist_last_seen) >= m_cfg.timeout.playlist_stall_sec) {
		if(m_playlist_stall_state.occur(now)) {
			m_events.emit(make_event(now, "playlist_stalled_occurred", json{
				{"last_playlist_seen", m_playlist_last_seen},
				{"stall_seconds", now - m_playlist_last_seen},
				{"severity", "warning"},
			}));
		}
	}
	else if(m_playlist_stall_state.recover(now)) {
		m_events.emit(make_event(now, "playlist_stalled_recovered", json{
			{"last_playlist_seen", m_playlist_last_seen},
			{"severity", "info"},
		}));
	}
	if(m_playlist_stall_state.update(now)) {
		m_events.emit(make_event(now, "playlist_stalled_recovered", json{
			{"last_playlist_seen", m_playlist_last_seen},
			{"severity", "info"},
		}));
	}
	return 0;
}

void stream::expire_flows(double now, double flow_idle_sec) {
	for(auto it = m_flows.begin(); it != m_flows.end(); ) {
		if(it->second->metrics_emitted() && it->second->expired(now, flow_idle_sec)) {
			it->second->emit_lost(now);
			it = m_flows.erase(it);
		}
		else {
			++it;
		}
	}
}

