		stream->append_list(now, out);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.interface_id], i.interface_id);
	tsv::to_string(row[c.i.com.interface_name], i.interface_name);
	i.frame_len = c.r.com.frame_len;
	tsv::to_number(row[c.i.com.frame_len], i.frame_len);
	i.vlan = tsv::vlan_info{
		.id = std::string(tsv::field_or_empty(row, c.i.com.vlan_id)),
		.priority = std::string(tsv::field_or_empty(row, c.i.com.vlan_priority)),
		.dei = std::string(tsv::field_or_empty(row, c.i.com.vlan_dei)),
	};

	parse_ip(tsv::field_or_empty(row, c.i.com.ip_src), tsv::field_or_empty(row, c.i.com.ipv6_src), i.src.addr);
	parse_ip(tsv::field_or_empty(row, c.i.com.ip_dst), tsv::field_or_empty(row, c.i.com.ipv6_dst), i.dst.addr);
	std::uint32_t port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_srcport), port) && port <= 65535U) {
		i.src.port = static_cast<std::uint16_t>(port);
	}
	port = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_dstport), port) && port <= 65535U) {
		i.dst.port = static_cast<std::uint16_t>(port);
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_stream), i.tcp_stream)) {
		i.has_tcp_stream = true;
	}
	if(tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_len), i.tcp_len) && i.tcp_len > 0) {
		i.has_tcp_payload = true;
		i.payload_seen = true;
	}

	i.method = std::string(tsv::field_or_empty(row, c.i.http.method));
	i.path = std::string(tsv::field_or_empty(row, c.i.http.uri));
	i.host = std::string(tsv::field_or_empty(row, c.i.http.host));
	i.is_request = !i.method.empty() && !i.path.empty();

	std::uint32_t status = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.status_code), status) && status <= 999U) {
		i.status_code = static_cast<std::uint16_t>(status);
		i.is_response = i.status_code > 0;
		if(i.is_response) {
			i.effective_status_code = i.status_code;
			i.status_source = "http_header";
		}
	}

	std::uint64_t len = 0;
	if(tsv::to_number(tsv::field_or_empty(row, c.i.http.content_length), len)) {
		i.content_length = len;
		i.has_content_length = true;
	}
	else if(i.is_response && i.frame_len > 0) {
		// Content-Length is not available on all tshark versions; frame length keeps bitrate observable.
		i.content_length = i.frame_len;
		i.has_content_length = true;
	}
	else if(i.has_tcp_payload) {
		i.content_length = i.tcp_len;
		i.has_content_length = true;
	}

	if(!i.is_request && !i.is_response && !i.has_tcp_payload) {
		return -1;
	}
	if(i.is_response || (!i.is_request && i.has_tcp_payload)) {
		return 0;
	}

	i.port = endpoint_port(i.dst, 80);
	parse_absolute_uri(i.host, i.port, i.path);
	if(i.host.empty()) {
		i.host = to_string(i.dst.addr);
	}
	split_host_port(i.host, i.port);
	i.role = classify_role(i.path);
	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);
		if(it->second->empty() && it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			it->second->emit_lost(now);
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

