		trace(4, "monitor: effective proto %.*s -> %.*s method=%s uri=%s status=%s",
		      static_cast<int>(proto.size()), proto.data(),
		      static_cast<int>(dispatch_proto.size()), dispatch_proto.data(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}
	tsv::to_number(row[tc.i.com.time_epoch], tc.r.com.time_epoch);
	tsv::to_number(row[tc.i.com.interface_id], tc.r.com.interface_id);
	tsv::to_string(row[tc.i.com.interface_name], tc.r.com.interface_name);
	tc.r.com.vlan_id = std::string(tsv::field_or_empty(row, tc.i.com.vlan_id));
	tc.r.com.vlan_priority = std::string(tsv::field_or_empty(row, tc.i.com.vlan_priority));
	tc.r.com.vlan_dei = std::string(tsv::field_or_empty(row, tc.i.com.vlan_dei));

	m_interfaces->observe(tc.r.com.interface_id, tc.r.com.interface_name);

	tsv::vlan_info packet_vlan{
		.id = tc.r.com.vlan_id,
		.priority = tc.r.com.vlan_priority,
		.dei = tc.r.com.vlan_dei,
	};
	ip_endpoint src_endpoint{};
	ip_endpoint dst_endpoint{};
	read_packet_endpoint(tc, row, true, src_endpoint);
	read_packet_endpoint(tc, row, false, dst_endpoint);
	const auto host = observed_host(tc, row);
	const std::string conn_key = tcp_connection_key(tc.r.com.interface_id, packet_vlan, src_endpoint, dst_endpoint);
	const bool hls_host_match = !host.empty() && m_protocol_map.should_observe("HTTP", src_endpoint, dst_endpoint, packet_vlan, host);
	if(hls_host_match) {
		remember_hls_connection(conn_key, tc.r.com.time_epoch);
	}
	const bool known_hls_connection = hls_connection_known(conn_key);
	const bool observe_stream =
		m_protocol_map.should_observe(dispatch_proto, src_endpoint, dst_endpoint, packet_vlan, host) ||
		(dispatch_proto == "HTTP" && known_hls_connection);
	if(observe_stream) {
		auto it = m_dispatcher.find(dispatch_proto);
		if(it != m_dispatcher.end()) {
			it->second->process(tc, row);
		}
		else {
			m_other->process(tc, row);
		}
	}

	if(dispatch_proto != "HTTP" &&
	   has_tcp_payload(tc, row) &&
	   known_hls_connection) {
		trace(4, "monitor: tcp payload fallback to HLS proto=%.*s tcp_len=%s src_port=%u dst_port=%u",
		      static_cast<int>(proto.size()), proto.data(),
		      std::string(tsv::field_or_empty(row, tc.i.com.tcp_len)).c_str(),
		      static_cast<unsigned>(src_endpoint.port),
		      static_cast<unsigned>(dst_endpoint.port));
		m_hls->process(tc, row);
	}

	auto br = m_second_boundary.update(tc.r.com.time_epoch);
	if(!br.changed) {
		return 0;
	}

// {
// 	double d = tc.r.com.time_epoch - _time_epoch;
// 	if(d < 0) {
// 		trace(1, "%f %f %f", tc.r.com.time_epoch, _time_epoch, d);
// 	}
// 	_time_epoch = tc.r.com.time_epoch;
// }

	m_interfaces->process(tc.r.com.time_epoch);
	prune_hls_connections(tc.r.com.time_epoch);

	m_srt->update_events(tc.r.com.time_epoch);
	m_rtp->update_events(tc.r.com.time_epoch);
	m_hls->update_events(tc.r.com.time_epoch);
	m_other->update_events(tc.r.com.time_epoch);
	m_interfaces->update_events(tc.r.com.time_epoch);

	json::array_t metrics_list;
	m_srt->append_metrics(tc.r.com.time_epoch, metrics_list);
	m_rtp->append_metrics(tc.r.com.time_epoch, metrics_list);
	m_hls->append_metrics(tc.r.com.time_epoch, metrics_list);
	m_other->append_metrics(tc.r.com.time_epoch, metrics_list);

	json::array_t interface_metrics;
	m_interfaces->append_metrics(tc.r.com.time_epoch, interface_metrics);

	json metrics_root{
		{"time", tc.r.com.time_epoch},
		{"metrics", std::move(metrics_list)},
		{"interfaces", std::move(interface_metrics)},
