	m_rtp->append_list(tc.r.com.time_epoch, streams_list);
	m_hls->append_list(tc.r.com.time_epoch, streams_list);
	m_other->append_list(tc.r.com.time_epoch, streams_list);

	json::array_t interface_list;
	m_interfaces->append_list(tc.r.com.time_epoch, interface_list);

	json list_root{
		{"time", tc.r.com.time_epoch},
		{"streams", std::move(streams_list)},
		{"interfaces", std::move(interface_list)},
	};
	if(packet_vlan.empty() == false) {
		list_root["vlan"] = tsv::to_json(packet_vlan);
	}
	m_logs->write_streams(list_root);

	auto topology = m_topology_projector.build(tc.r.com.time_epoch,
	                                         list_root.at("streams").get<json::array_t>(),
	                                         list_root.at("interfaces").get<json::array_t>(),
	                                         metrics_root.at("metrics").get<json::array_t>(),
	                                         active_alerts);
	m_logs->write_topology(topology);

	return 0;
}

std::string monitor::tcp_connection_key(std::uint32_t interface_id,
                                        const tsv::vlan_info &vlan,
                                        const ip_endpoint &src,
                                        const ip_endpoint &dst) const {
	std::string a = endpoint_key(src);
	std::string b = endpoint_key(dst);
	if(b < a) {
		std::swap(a, b);
	}

	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << a << "<->" << b;
	return oss.str();
}

bool monitor::hls_connection_known(const std::string &conn_key) const {
	return m_hls_connections.find(conn_key) != m_hls_connections.end();
}

void monitor::remember_hls_connection(const std::string &conn_key, double now) {
	if(conn_key.empty()) {
		return;
	}
	m_hls_connections[conn_key] = now;
}

void monitor::prune_hls_connections(double now) {
	for(auto it = m_hls_connections.begin(); it != m_hls_connections.end(); ) {
		if((now - it->second) >= hls_connection_ttl_sec) {
			it = m_hls_connections.erase(it);
		}
		else {
			++it;
		}
	}
}

