std::string monitor::tcp_connection_key(std::uint32_t interface_id,
                                        const tsv::vlan_info &vlan,
                                        const ip_endpoint &src,
                                        const ip_endpoint &dst) const {
	std::string a = endpoint_key(src);
	std::string b = endpoint_key(dst);
	if(b < a) {
		std::swap(a, b);
	}

	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << a << "<->" << b;
	return oss.str();
}

bool monitor::hls_connection_known(const std::string &conn_key) const {
	return m_hls_connections.find(conn_key) != m_hls_connections.end();
}

bool monitor::hls_tcp_fallback_ready(const std::string &conn_key, double now) const {
	const auto it = m_hls_connections.find(conn_key);
	if(it == m_hls_connections.end() || it->second.detailed) {
		return false;
	}
	return (now - it->second.first_seen) >= hls_tcp_fallback_delay_sec;
}

void monitor::remember_hls_connection(const std::string &conn_key, double now) {
	if(conn_key.empty()) {
		return;
	}
	auto [it, inserted] = m_hls_connections.emplace(conn_key, hls_connection_state{
		.first_seen = now,
		.last_seen = now,
		.detailed = false,
	});
	if(!inserted) {
		it->second.last_seen = now;
	}
}

void monitor::remember_hls_detailed_connection(const std::string &conn_key, double now) {
	remember_hls_connection(conn_key, now);
	m_hls_connections[conn_key].detailed = true;
}

void monitor::prune_hls_connections(double now) {
	for(auto it = m_hls_connections.begin(); it != m_hls_connections.end(); ) {
		if((now - it->second.last_seen) >= hls_connection_ttl_sec) {
			it = m_hls_connections.erase(it);
		}
		else {
			++it;
		}
	}
}

