namespace {

constexpr const char *hls_tcp_fallback_proto = "HLS-TCP";

struct protocol_configs {
	hls::config hls;
	srt::config srt;
	rtp::config rtp;
	rtmp::config rtmp;
	other::config other;
	netif::config netif;
};


bool read_packet_endpoint(const tsv::ctx &tc,
                          const tsv::row_t &row,
                          bool src,
                          ip_endpoint &out) {
	ip_addr addr{};
	const int ipv4_idx = src ? tc.i.com.ip_src : tc.i.com.ip_dst;
	const int ipv6_idx = src ? tc.i.com.ipv6_src : tc.i.com.ipv6_dst;
	if(!parse_ip(tsv::field_or_empty(row, ipv4_idx), tsv::field_or_empty(row, ipv6_idx), addr)) {
		return false;
	}

	std::uint32_t port32 = 0;
	const int udp_idx = src ? tc.i.com.udp_srcport : tc.i.com.udp_dstport;
	const int tcp_idx = src ? tc.i.com.tcp_srcport : tc.i.com.tcp_dstport;
	if(!tsv::to_number(tsv::field_or_empty(row, udp_idx), port32)) {
		port32 = 0;
		tsv::to_number(tsv::field_or_empty(row, tcp_idx), port32);
	}
	if(port32 > 65535U) {
		return false;
	}

	out = ip_endpoint{addr, static_cast<std::uint16_t>(port32)};
	return true;
}

bool has_http_fields(const tsv::ctx &tc, const tsv::row_t &row) {
	return !tsv::field_or_empty(row, tc.i.http.method).empty() ||
	       !tsv::field_or_empty(row, tc.i.http.uri).empty() ||
	       !tsv::field_or_empty(row, tc.i.http.status_code).empty();
}

bool has_tcp_payload(const tsv::ctx &tc, const tsv::row_t &row) {
	std::uint32_t tcp_len = 0;
	return tsv::to_number(tsv::field_or_empty(row, tc.i.com.tcp_len), tcp_len) && tcp_len > 0;
}

std::string endpoint_key(const ip_endpoint &ep) {
	std::ostringstream oss;
	oss << to_string(ep.addr) << ':' << ep.port;
	return oss.str();
}

std::string_view observed_host(const tsv::ctx &tc, const tsv::row_t &row) {
	const auto http_host = tsv::field_or_empty(row, tc.i.http.host);
	if(!http_host.empty()) {
		return http_host;
	}
	return tsv::field_or_empty(row, tc.i.tls.server_name);
}

std::string_view effective_dispatch_proto(std::string_view proto,
                                          const tsv::ctx &tc,
                                          const tsv::row_t &row) {
	if(has_http_fields(tc, row)) {
		return "HTTP";
	}
	return proto;
}

protocol_configs make_protocol_configs(const protocol_map &map) {
	protocol_configs cfg{};
	cfg.rtp.fec_base_endpoints = map.rtp_fec_base_endpoints();
	return cfg;
}

