};


bool read_packet_endpoint(const tsv::ctx &tc,
                          const tsv::row_t &row,
                          bool src,
                          ip_endpoint &out) {
	ip_addr addr{};
	const int ipv4_idx = src ? tc.i.com.ip_src : tc.i.com.ip_dst;
	const int ipv6_idx = src ? tc.i.com.ipv6_src : tc.i.com.ipv6_dst;
	if(!parse_ip(tsv::field_or_empty(row, ipv4_idx), tsv::field_or_empty(row, ipv6_idx), addr)) {
		return false;
	}

	std::uint32_t port32 = 0;
	const int udp_idx = src ? tc.i.com.udp_srcport : tc.i.com.udp_dstport;
	const int tcp_idx = src ? tc.i.com.tcp_srcport : tc.i.com.tcp_dstport;
	if(!tsv::to_number(tsv::field_or_empty(row, udp_idx), port32)) {
		port32 = 0;
		tsv::to_number(tsv::field_or_empty(row, tcp_idx), port32);
	}
	if(port32 > 65535U) {
		return false;
	}

	out = ip_endpoint{addr, static_cast<std::uint16_t>(port32)};
	return true;
}

bool has_http_fields(const tsv::ctx &tc, const tsv::row_t &row) {
	return !tsv::field_or_empty(row, tc.i.http.method).empty() ||
	       !tsv::field_or_empty(row, tc.i.http.uri).empty() ||
	       !tsv::field_or_empty(row, tc.i.http.status_code).empty();
}

bool has_tcp_payload(const tsv::ctx &tc, const tsv::row_t &row) {
	std::uint32_t tcp_len = 0;
	return tsv::to_number(tsv::field_or_empty(row, tc.i.com.tcp_len), tcp_len) && tcp_len > 0;
}

std::string endpoint_key(const ip_endpoint &ep) {
	std::ostringstream oss;
	oss << to_string(ep.addr) << ':' << ep.port;
	return oss.str();
}

std::string_view observed_host(const tsv::ctx &tc, const tsv::row_t &row) {
	const auto http_host = tsv::field_or_empty(row, tc.i.http.host);
	if(!http_host.empty()) {
		return http_host;
	}
	return tsv::field_or_empty(row, tc.i.tls.server_name);
}

std::string_view effective_dispatch_proto(std::string_view proto,
                                          const tsv::ctx &tc,
                                          const tsv::row_t &row) {
	if(has_http_fields(tc, row)) {
		return "HTTP";
	}
	return proto;
}

protocol_configs make_protocol_configs(const protocol_map &map) {
	protocol_configs cfg{};
	cfg.rtp.fec_base_endpoints = map.rtp_fec_base_endpoints();
	return cfg;
}

} // namespace

monitor::monitor()
	: monitor(config{}) {
}

monitor::monitor(config cfg)
	: m_cfg(std::move(cfg)) {
	m_init_status = init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	if(m_cfg.protocol_map_file.empty() == false) {
		if(m_protocol_map.load(m_cfg.protocol_map_file) != 0) {
			return -1;
		}
	}

	auto proto_cfg = make_protocol_configs(m_protocol_map);

	m_logs = std::make_unique<log_pipeline>(m_cfg.log);
	m_alerts = std::make_unique<alert_evaluator>(m_logs->events());
	if(!m_cfg.alert_config_file.empty() && m_alerts->load(m_cfg.alert_config_file) != 0) {
		return -1;
	}

	m_srt   = std::make_unique<srt::streams>(proto_cfg.srt, m_logs->events());
	m_rtp   = std::make_unique<rtp::streams>(proto_cfg.rtp, m_logs->events());
	m_rtmp  = std::make_unique<rtmp::streams>(proto_cfg.rtmp, m_logs->events());
	m_hls   = std::make_unique<hls::streams>(proto_cfg.hls, m_logs->events());
	m_other = std::make_unique<other::streams>(proto_cfg.other, m_logs->events());
	m_interfaces = std::make_unique<netif::interfaces>(proto_cfg.netif, m_logs->events());

	m_dispatcher = { { "SRT",   m_srt.get() },
	                 { "RTP",   m_rtp.get() },
	                 { "HTTP",  m_hls.get() },
	                 { "RTMP",  m_rtmp.get() },
	                 { "RTMPT", m_rtmp.get() } };

	m_pcap_source = pcap_input::make_source(m_cfg.input);
	if(!m_pcap_source) {
		std::cerr << "[ERROR] failed to create pcap input source" << std::endl;
		return -1;
	}
	m_pcap_source->set_callback([this](const std::filesystem::path &path) {
		return process_pcap(path);
	});

	return 0;
}

int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_pcap_source) {
		std::cerr << "[ERROR] pcap input source is not initialized" << std::endl;
		return 1;
	}
	return m_pcap_source->run();
}

bool monitor::process_pcap(const std::filesystem::path& file_path) {
	std::string command = tshark::build_read_command(file_path, m_cfg.tshark, m_protocol_map.decode_as_rules());

	FILE* pipe = popen(command.c_str(), "r");
	if(!pipe) {
