std::string monitor::tcp_connection_key(std::uint32_t interface_id,
                                        const tsv::vlan_info &vlan,
                                        const ip_endpoint &src,
                                        const ip_endpoint &dst) const {
	std::string a = endpoint_key(src);
	std::string b = endpoint_key(dst);
	if(b < a) {
		std::swap(a, b);
	}

	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << a << "<->" << b;
	return oss.str();
}


int monitor::flush_ready_rows(tsv::ctx &tc, double watermark_time) {
	while(!m_reorder_buffer.empty()) {
		auto it = m_reorder_buffer.begin();
		if(it->first.time_epoch > watermark_time) {
			break;
		}

		const std::string line = std::move(it->second);
		m_reorder_buffer.erase(it);
		process_ordered_line(tc, line);
	}

	return 0;
}

int monitor::flush_all_rows(tsv::ctx &tc) {
	while(!m_reorder_buffer.empty()) {
		auto it = m_reorder_buffer.begin();
		const std::string line = std::move(it->second);
		m_reorder_buffer.erase(it);
		process_ordered_line(tc, line);
	}

	return 0;
}

