hls_dispatch_state::hls_dispatch_state()
	: hls_dispatch_state(config{}) {
}

hls_dispatch_state::hls_dispatch_state(config cfg)
	: m_cfg(cfg) {
}

bool hls_dispatch_state::known(const std::string &conn_key) const {
	return m_connections.find(conn_key) != m_connections.end();
}

bool hls_dispatch_state::tcp_fallback_ready(const std::string &conn_key, double now) const {
	const auto it = m_connections.find(conn_key);
	if(it == m_connections.end() || it->second.detailed) {
		return false;
	}
	return (now - it->second.first_seen) >= m_cfg.fallback_delay_sec;
}

void hls_dispatch_state::remember_candidate(const std::string &conn_key, double now) {
	if(conn_key.empty()) {
		return;
	}
	auto [it, inserted] = m_connections.emplace(conn_key, connection_state{
		.first_seen = now,
		.last_seen = now,
		.detailed = false,
	});
	if(!inserted) {
		it->second.last_seen = now;
	}
}

void hls_dispatch_state::remember_detailed(const std::string &conn_key, double now) {
	remember_candidate(conn_key, now);
	m_connections[conn_key].detailed = true;
}

void hls_dispatch_state::prune(double now) {
	for(auto it = m_connections.begin(); it != m_connections.end(); ) {
		if((now - it->second.last_seen) >= m_cfg.ttl_sec) {
			it = m_connections.erase(it);
		}
		else {
			++it;
		}
	}
}

