	: m_protocols(protocols),
	  m_hls(hls_streams),
	  m_other(other_streams) {
}

hls_dispatch_adapter::result hls_dispatch_adapter::prepare(const packet_context &packet) {
	result out{};
	out.connection_key = packet_connection_key(packet);
	out.host_match =
		!packet.host.empty() &&
		m_protocols.should_observe("HTTP", packet.src, packet.dst, packet.vlan, packet.host);
	if(out.host_match) {
		m_state.remember_candidate(out.connection_key, packet.time_epoch);
	}

	out.known_connection = m_state.known(out.connection_key);
	out.observe_http = packet.dispatch_proto == "HTTP" && out.known_connection;
	out.suppress_other = out.host_match || out.known_connection;
	return out;
}

void hls_dispatch_adapter::mark_detailed_if_needed(const packet_context &packet, const result &dispatch) {
	if(packet.dispatch_proto != "HTTP") {
		return;
	}
	if(!dispatch.host_match && !dispatch.known_connection) {
		return;
	}
	m_state.remember_detailed(dispatch.connection_key, packet.time_epoch);
}

void hls_dispatch_adapter::process_transport_fallback(tsv::ctx &tc,
                                                      const tsv::row_t &row,
                                                      const packet_context &packet,
                                                      const result &dispatch) {
	if(packet.dispatch_proto == "HTTP" || !packet.has_tcp_payload || !dispatch.known_connection) {
		return;
