bool monitor::process_pcap(const std::filesystem::path& file_path) {
	std::string command = tshark::build_read_command(file_path, m_cfg.tshark, m_protocol_map.decode_as_rules());

	FILE* pipe = popen(command.c_str(), "r");
	if(!pipe) {
		return false;
	}

	const bool parse_ok = (process_tsv(pipe) == 0);
	if(!parse_ok) {
		trace(0, "warn: parse_tsv failed for %s", file_path.filename().string().c_str());
	}

	int status = pclose(pipe);
	if(status == -1) {
		trace(0, "warn: pclose failed for %s", file_path.filename().string().c_str());
		return false;
	}

	if(WIFEXITED(status)) {
		int exit_code = WEXITSTATUS(status);
		if(exit_code == 0) {
			return parse_ok;
		}

		trace(0, "warn: tshark failed for %s, exit_code=%d",
		      file_path.filename().string().c_str(),
		      exit_code);
		return false;
	}

	if(WIFSIGNALED(status)) {
		trace(0, "warn: tshark terminated by signal for %s, signal=%d",
		      file_path.filename().string().c_str(),
		      WTERMSIG(status));
		return false;
	}

	trace(0, "warn: tshark ended unexpectedly for %s, status=%d",
	      file_path.filename().string().c_str(),
	      status);

	return false;
}

int monitor::process_tsv(FILE *pipe) {
	tsv::ctx tc;
	char line[32768];

	m_reorder_buffer.clear();
	m_reorder_seen_any = false;
	m_reorder_latest_seen_time = 0.0;
	m_reorder_seq = 0;

	if(fgets(line, sizeof(line), pipe) == nullptr) {
		trace(1, "info: tshark output is empty");
		return 0;
	}
	if(!tsv::init_ctx(tc, line)) {
		return -1;
	}

	trace(7, "%s", line);

	while(fgets(line, sizeof(line), pipe) != nullptr) {
		trace(7, "%s", line);

		std::string buffered_line{line};
		tsv::row_t row;
		tsv::split(buffered_line, row);

		double time_epoch = 0.0;
		tsv::to_number(row[tc.i.com.time_epoch], time_epoch);
		m_reorder_buffer.emplace(buffered_row_key{
			                         .time_epoch = time_epoch,
			                         .seq = m_reorder_seq++,
		                         },
		                         std::move(buffered_line));

		if(!m_reorder_seen_any || time_epoch > m_reorder_latest_seen_time) {
			m_reorder_seen_any = true;
			m_reorder_latest_seen_time = time_epoch;
		}

		const double watermark_time = m_reorder_latest_seen_time - m_cfg.reorder_holdback_sec;
		flush_ready_rows(tc, watermark_time);
	}

	flush_all_rows(tc);

	return 0;
}

int monitor::process_ordered_line(tsv::ctx &tc, std::string_view line) {
	tsv::row_t row;
	tsv::split(line, row);

	const packet_context packet = make_packet_context(tc, row);
	if(packet.dispatch_proto_changed()) {
		trace(4, "monitor: effective proto %s -> %s method=%s uri=%s status=%s",
		      packet.proto.c_str(),
		      packet.dispatch_proto.c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}

	m_interfaces->observe(packet.interface_id, packet.interface_name);

	m_streams->process_packet(tc, row, packet);

	auto br = m_second_boundary.update(packet.time_epoch);
	if(!br.changed) {
		return 0;
	}

	m_interfaces->process(packet.time_epoch);
	m_streams->update_events(tc.r.com.time_epoch);
	m_interfaces->update_events(tc.r.com.time_epoch);

	json::array_t metrics_list;
	m_streams->append_metrics(tc.r.com.time_epoch, metrics_list);

	json::array_t interface_metrics;
	m_interfaces->append_metrics(tc.r.com.time_epoch, interface_metrics);

	json metrics_root{
		{"time", tc.r.com.time_epoch},
		{"metrics", std::move(metrics_list)},
		{"interfaces", std::move(interface_metrics)},
	};
	if(packet.vlan.empty() == false) {
		metrics_root["vlan"] = tsv::to_json(packet.vlan);
	}

	json::array_t active_alerts;
	if(m_alerts && !m_alerts->empty()) {
		m_alerts->evaluate(tc.r.com.time_epoch,
		                   metrics_root.at("metrics").get<json::array_t>(),
		                   metrics_root.at("interfaces").get<json::array_t>());
		active_alerts = m_alerts->active_alerts();
	}
	m_logs->append_metrics_history(tc.r.com.time_epoch,
	                               metrics_root.at("metrics").get<json::array_t>(),
	                               metrics_root.at("interfaces").get<json::array_t>());
	m_logs->write_metrics(metrics_root);

	json::array_t streams_list;
	m_streams->append_list(tc.r.com.time_epoch, streams_list);

	json::array_t interface_list;
	m_interfaces->append_list(tc.r.com.time_epoch, interface_list);

	json list_root{
		{"time", tc.r.com.time_epoch},
		{"streams", std::move(streams_list)},
		{"interfaces", std::move(interface_list)},
	};
	if(packet.vlan.empty() == false) {
		list_root["vlan"] = tsv::to_json(packet.vlan);
	}
	m_logs->write_streams(list_root);

	auto topology = m_topology_projector.build(tc.r.com.time_epoch,
	                                         list_root.at("streams").get<json::array_t>(),
	                                         list_root.at("interfaces").get<json::array_t>(),
	                                         metrics_root.at("metrics").get<json::array_t>(),
	                                         active_alerts);
	m_logs->write_topology(topology);

	return 0;
}


int monitor::flush_ready_rows(tsv::ctx &tc, double watermark_time) {
	while(!m_reorder_buffer.empty()) {
		auto it = m_reorder_buffer.begin();
		if(it->first.time_epoch > watermark_time) {
			break;
		}

		const std::string line = std::move(it->second);
		m_reorder_buffer.erase(it);
		process_ordered_line(tc, line);
	}

	return 0;
}

int monitor::flush_all_rows(tsv::ctx &tc) {
	while(!m_reorder_buffer.empty()) {
		auto it = m_reorder_buffer.begin();
		const std::string line = std::move(it->second);
		m_reorder_buffer.erase(it);
		process_ordered_line(tc, line);
	}

	return 0;
}

