#include "event.h"

#include <utility>

#include "writer.h"
#include "timeline.h"

namespace {

json to_event_json(const event_record &e) {
	json j{
		{"time", e.time_epoch},
		{"type", e.type},
	};

	if(e.source.is_null() == false && e.source.empty() == false) {
		j["source"] = e.source;
	}
	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	return j;
}

bool is_lifetime_timeline_event(const event_record &e) {
	return e.type == "stream_detected" || e.type == "stream_lost" ||
	       e.type == "flow_detected" || e.type == "flow_lost";
}

bool ends_with(const std::string &value, const std::string &suffix) {
	return value.size() >= suffix.size() &&
	       value.compare(value.size() - suffix.size(), suffix.size(), suffix) == 0;
}

bool is_timeline_marker_event(const event_record &e) {
	if(e.type == "alert_detected" || e.type == "alert_recovered") {
		return true;
	}
	if(e.type.rfind("stream_", 0) == 0 || e.type.rfind("flow_", 0) == 0) {
		return false;
	}
	return ends_with(e.type, "_occurred") || ends_with(e.type, "_recovered");
}

std::string marker_action(const std::string &type) {
	if(ends_with(type, "_detected") || ends_with(type, "_occurred")) {
		return "detected";
	}
	if(ends_with(type, "_recovered")) {
		return "recovered";
	}
	return "event";
}

json make_marker_subject(const event_record &e) {
	json subject = e.source.is_object() ? e.source : json::object();
	if(!subject.contains("type")) {
		if(subject.contains("target") && subject["target"].is_string()) {
			subject["type"] = subject["target"];
		}
		else if(subject.contains("flow_key")) {
			subject["type"] = "flow";
		}
		else if(subject.contains("stream_key")) {
			subject["type"] = "stream";
		}
		else if(subject.contains("interface_id") || subject.contains("name")) {
			subject["type"] = "interface";
		}
	}
	return subject;
}

json make_marker_detail(const event_record &e) {
	json detail = e.detail.is_object() ? e.detail : json::object();
	detail["event_type"] = e.type;
	detail["action"] = marker_action(e.type);
	if(e.source.is_object()) {
		for(const auto &key : {"alert_id", "severity", "target", "proto", "stream_key", "flow_key", "interface_id", "name"}) {
			if(e.source.contains(key) && !detail.contains(key)) {
				detail[key] = e.source[key];
			}
		}
	}
	if(!detail.contains("label")) {
		if(detail.contains("alert_id") && detail["alert_id"].is_string()) {
			detail["label"] = detail["alert_id"];
		}
		else if(detail.contains("metric") && detail["metric"].is_string()) {
			detail["label"] = detail["metric"];
		}
		else {
			detail["label"] = e.type;
		}
	}
	if(!detail.contains("severity")) {
		detail["severity"] = e.type == "alert_detected" ? "warning" : "info";
	}
	return detail;
}

} // namespace

//--------------------------------------------------------------------------------
void event_sink::add_consumer(event_consumer &consumer) {
	m_consumers.push_back(&consumer);
}

//--------------------------------------------------------------------------------
int event_sink::emit(const event_record &e) {
	int rc = 0;
	for(auto *consumer : m_consumers) {
		if(consumer == nullptr) {
			continue;
		}
		const int consumer_rc = consumer->handle_event(e);
		if(rc == 0 && consumer_rc != 0) {
			rc = consumer_rc;
		}
	}
	return rc;
}

//--------------------------------------------------------------------------------
event_log_sink::event_log_sink(writer &w)
	: m_writer(w) {
}

//--------------------------------------------------------------------------------
int event_log_sink::handle_event(const event_record &e) {
	return m_writer.dump(to_event_json(e));
}

//--------------------------------------------------------------------------------
timeline_projector::timeline_projector(timeline_sink &timeline)
	: m_timeline(timeline) {
}

//--------------------------------------------------------------------------------
int timeline_projector::handle_event(const event_record &e) {
	if(is_timeline_marker_event(e)) {
		return m_timeline.emit(e.time_epoch,
		                       "marker",
		                       make_marker_subject(e),
		                       make_marker_detail(e));
	}

	if(is_lifetime_timeline_event(e) == false) {
		return 0;
	}

	json subject = e.source.is_object() ? e.source : json::object();
	json detail = json::object();

	if(e.type.rfind("stream_", 0) == 0) {
		subject["type"] = "stream";
	}
	else {
		subject["type"] = "flow";
	}

	if(e.detail.is_object()) {
		for(const auto &key : {"interface_id", "endpoint", "streamid", "role", "label"}) {
			if(e.detail.contains(key)) {
				subject[key] = e.detail[key];
			}
		}
		for(const auto &key : {"last_seen", "flow_count"}) {
			if(e.detail.contains(key)) {
				detail[key] = e.detail[key];
			}
		}
	}

	return m_timeline.emit(e.time_epoch, e.type, std::move(subject), std::move(detail));
}

//--------------------------------------------------------------------------------
event_state::event_state(double recovery_retention_sec, bool enable, bool mask)
	: m_enable(enable)
	, m_mask(mask)
	, m_recovery_retention_sec(recovery_retention_sec) {
}

//--------------------------------------------------------------------------------
void event_state::clear() {
	m_active = false;
	m_recovery_pending = false;
	m_recovery_time = 0.0;
}

//--------------------------------------------------------------------------------
bool event_state::occur(double now) {
	(void)now;
	++m_occurred_total;

	if(m_active) {
		return false;
	}

	m_active = true;
	m_recovery_pending = false;
	return fire();
}

//--------------------------------------------------------------------------------
bool event_state::recover(double now) {
	if(m_active == false) {
		return false;
	}

	m_active = false;
	m_recovery_time = now;

	if(m_recovery_retention_sec <= 0.0) {
		m_recovery_pending = false;
		return fire();
	}

	m_recovery_pending = true;
	return false;
}

//--------------------------------------------------------------------------------
bool event_state::update(double now) {
	if(m_recovery_pending == false) {
		return false;
	}
	if(m_active) {
		m_recovery_pending = false;
		return false;
	}
	if((now - m_recovery_time) < m_recovery_retention_sec) {
		return false;
	}

	m_recovery_pending = false;
	return fire();
}

//--------------------------------------------------------------------------------
bool event_state::remove(double now) {
	(void)now;
	const bool was_active = m_active || m_recovery_pending;
	clear();
	return was_active ? fire() : false;
}

//--------------------------------------------------------------------------------
std::uint64_t event_state::occurred_total_diff() {
	const std::uint64_t diff = m_occurred_total - m_occurred_total_last;
	m_occurred_total_last = m_occurred_total;
	return output_enabled() ? diff : 0;
}

