std::string topology_projector::transport_from_entry(const json &stream_entry, const json &flow_entry, const json *metric_entry) {
	for(const json *candidate : {&flow_entry, metric_entry}) {
		if(candidate != nullptr && candidate->is_object() && candidate->contains("ip_proto") && (*candidate)["ip_proto"].is_number_integer()) {
			const auto transport = transport_from_ip_proto((*candidate)["ip_proto"].get<int>());
			if(transport != "unknown") {
				return transport;
			}
		}
	}
	return transport_from_proto(stream_entry.value("proto", std::string{}));
}

std::string topology_projector::transport_from_ip_proto(int ip_proto) {
	switch(ip_proto) {
	case 6: return "tcp";
	case 17: return "udp";
	case 1: return "icmp";
	case 58: return "icmpv6";
	case 2: return "igmp";
	default: return "unknown";
	}
}

std::string topology_projector::transport_from_proto(const std::string &proto) {
	const auto p = upper(proto);
	if(p == "ARP") return "arp";
	if(p == "ICMP") return "icmp";
	if(p == "ICMPV6") return "icmpv6";
	if(p == "IGMP") return "igmp";
	if(p == "TCP" || p == "HTTP" || p == "HTTPS" || p == "SSH" || p == "RTMP") return "tcp";
	if(p == "UDP" || p == "RTP" || p == "SRT" || p == "NTP" || p == "DHCP" || p == "DNS" || p == "MDNS" || p == "SSDP") return "udp";
	return "unknown";
}

bool topology_projector::is_group_host(const std::string &host) {
	return is_ipv4_broadcast(host) || is_ipv4_multicast(host) || is_ipv6_multicast(host);
}

bool topology_projector::is_ipv4_broadcast(const std::string &host) {
	int a = -1, b = -1, c = -1, d = -1;
	char tail = 0;
	std::istringstream iss(host);
	if(!(iss >> a)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> b)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> c)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> d)) return false;
	if(iss >> tail) return false;
	return a >= 0 && a <= 255 && b >= 0 && b <= 255 && c >= 0 && c <= 255 && d == 255;
}

bool topology_projector::is_ipv4_multicast(const std::string &host) {
	int a = -1, b = -1, c = -1, d = -1;
	char tail = 0;
	std::istringstream iss(host);
	if(!(iss >> a)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> b)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> c)) return false;
	if(iss.get() != '.') return false;
	if(!(iss >> d)) return false;
	if(iss >> tail) return false;
	return a >= 224 && a <= 239 && b >= 0 && b <= 255 && c >= 0 && c <= 255 && d >= 0 && d <= 255;
}

bool topology_projector::is_ipv6_multicast(const std::string &host) {
	return lower(host).rfind("ff", 0) == 0;
}

bool topology_projector::service_role_for_endpoint(const endpoint_parts &self, const endpoint_parts &peer, const std::string &transport, bool is_src) {
	if(is_group_host(self.host) || transport == "icmp" || transport == "icmpv6" || transport == "igmp" || transport == "arp") {
		return false;
	}
	if(!self.has_port || self.port == 0) {
		return false;
	}
	if(is_group_host(peer.host) || !peer.has_port || peer.port == 0) {
		return !is_src;
	}
	if(self.port == peer.port) {
		return !is_src;
	}
	return self.port < peer.port;
}

std::string topology_projector::node_id_for_endpoint(const endpoint_parts &endpoint, const std::string &transport, bool service_role) {
	if(is_group_host(endpoint.host)) {
		return "group:" + endpoint.host + (endpoint.has_port ? ":" + std::to_string(endpoint.port) + "/" + transport : "");
	}
	if(service_role) {
		return "service:" + endpoint.host + ":" + std::to_string(endpoint.port) + "/" + transport;
	}
	return "host:" + endpoint.host;
}

json topology_projector::make_node_for_endpoint(const endpoint_parts &endpoint, const std::string &transport, bool service_role) {
	const auto id = node_id_for_endpoint(endpoint, transport, service_role);
	json node{
		{"id", id},
		{"label", id.substr(id.find(':') + 1)},
	};
	if(id.rfind("group:", 0) == 0) {
		node["type"] = "group";
		node["host"] = endpoint.host;
		if(endpoint.has_port) node["port"] = endpoint.port;
		node["transport"] = transport;
	}
	else if(id.rfind("service:", 0) == 0) {
		node["type"] = "service";
		node["host"] = endpoint.host;
		node["port"] = endpoint.port;
		node["transport"] = transport;
	}
	else {
		node["type"] = "host";
		node["host"] = endpoint.host;
	}
	return node;
}

json topology_projector::make_scope(const json &stream, const json &flow, const std::unordered_map<std::string, std::string> &interface_names) {
	json scope = json::object();
	if(stream.contains("scope") && stream["scope"].is_object()) {
		scope = stream["scope"];
	}
	if(flow.contains("scope") && flow["scope"].is_object()) {
		for(const auto &[key, value] : flow["scope"].items()) {
			scope[key] = value;
		}
	}

	if(!scope.contains("interface_id")) {
		scope["interface_id"] = stream.contains("interface_id") ? stream["interface_id"] : json(nullptr);
	}
	if(!scope.contains("interface_name")) {
		scope["interface_name"] = nullptr;
	}
	if(!scope.contains("vlan")) {
		scope["vlan"] = nullptr;
	}
	if(!scope.contains("vxlan")) {
		scope["vxlan"] = nullptr;
	}

	const auto id = json_string_or_empty(scope, "interface_id");
	const auto it = interface_names.find(id);
	if(it != interface_names.end()) {
		scope["interface_name"] = it->second;
	}
	if((scope["vlan"].is_null()) && flow.contains("vlan") && !flow["vlan"].is_null()) {
		scope["vlan"] = flow["vlan"];
	}
	else if((scope["vlan"].is_null()) && stream.contains("vlan") && !stream["vlan"].is_null()) {
		scope["vlan"] = stream["vlan"];
	}
	return scope;
}

json topology_projector::summarize_metrics(const json &entry) {
	json out = json::object();
	double value = 0.0;
	if(entry.contains("bitrate") && number_value(entry["bitrate"], "bps", value)) {
		out["bitrate_bps"] = value;
	}
	if(entry.contains("packet_rate") && number_value(entry["packet_rate"], "pps", value)) {
		out["packet_rate_pps"] = value;
	}
	if(entry.contains("packet_count") && number_value(entry["packet_count"], "window", value)) {
		out["packet_count_window"] = value;
	}
	if(entry.contains("jitter") && number_value(entry["jitter"], "seconds", value)) {
		out["jitter_seconds"] = value;
	}
	if(entry.contains("rtt") && number_value(entry["rtt"], "value", value)) {
		out["rtt"] = value;
	}
	if(entry.contains("seq_stats") && entry["seq_stats"].is_object()) {
		json seq = json::object();
		for(const auto &name : {"gap", "dup", "reorder"}) {
			if(entry["seq_stats"].contains(name) && number_value(entry["seq_stats"][name], "window", value)) {
				seq[std::string(name) + "_window"] = value;
			}
		}
		if(!seq.empty()) {
			out["seq_stats"] = std::move(seq);
		}
	}
	return out;
}

json topology_projector::summarize_alerts(const std::vector<json> &alerts) {
	json::array_t compact;
	std::vector<std::string> seen;
	std::string severity = "info";
	int rank = 0;
	for(const auto &alert : alerts) {
		const auto id = alert_identity(alert);
		if(!id.empty() && std::find(seen.begin(), seen.end(), id) != seen.end()) {
			continue;
		}
		if(!id.empty()) {
			seen.push_back(id);
		}
		const auto alert_severity = json_string_or_empty(alert, "severity");
		const int alert_rank = severity_rank(alert_severity);
		if(alert_rank >= rank && !alert_severity.empty()) {
			rank = alert_rank;
			severity = alert_severity;
		}
		compact.push_back(compact_alert(alert));
	}
	return json{
		{"state", "active"},
		{"severity", severity},
		{"count", compact.size()},
		{"alerts", std::move(compact)},
	};
}

int topology_projector::severity_rank(const std::string &severity) {
	const auto s = lower(severity);
	if(s == "fatal" || s == "critical") return 4;
	if(s == "error") return 3;
	if(s == "warning" || s == "warn") return 2;
	if(s == "info") return 1;
	return 0;
}

void topology_projector::append_matching_alerts(std::vector<json> &out, const alert_index &alerts, const std::string &stream_key, const std::string &flow_key, const json &scope) {
	auto append_from = [&out](const auto &map, const std::string &key) {
		const auto it = map.find(key);
		if(it == map.end()) {
			return;
		}
		out.insert(out.end(), it->second.begin(), it->second.end());
	};
	append_from(alerts.by_flow, metric_key(stream_key, flow_key));
	append_from(alerts.by_stream, stream_key);
	const auto interface_id = json_string_or_empty(scope, "interface_id");
	if(!interface_id.empty()) {
		append_from(alerts.by_interface, "id:" + interface_id);
	}
	const auto interface_name = json_string_or_empty(scope, "interface_name");
	if(!interface_name.empty()) {
		append_from(alerts.by_interface, "name:" + interface_name);
	}
}

void topology_projector::merge_node_alert(std::unordered_map<std::string, json> &nodes, const std::string &node_id, const json &alert_summary) {
	auto it = nodes.find(node_id);
	if(it == nodes.end() || !alert_summary.is_object() || !alert_summary.contains("alerts") || !alert_summary["alerts"].is_array()) {
		return;
	}
	auto &node = it->second;
	if(!node.contains("alert") || !node["alert"].is_object()) {
		node["alert"] = json{
			{"state", "active"},
			{"severity", alert_summary.value("severity", std::string{"info"})},
			{"count", 0},
			{"alerts", json::array()},
		};
	}
	auto &node_alert = node["alert"];
	for(const auto &alert : alert_summary["alerts"]) {
		const auto id = alert_identity(alert);
		bool exists = false;
		for(const auto &existing : node_alert["alerts"]) {
			if(!id.empty() && alert_identity(existing) == id) {
				exists = true;
				break;
			}
		}
		if(!exists) {
			node_alert["alerts"].push_back(alert);
		}
	}
	node_alert["count"] = node_alert["alerts"].size();
	if(severity_rank(alert_summary.value("severity", std::string{})) > severity_rank(node_alert.value("severity", std::string{}))) {
		node_alert["severity"] = alert_summary["severity"];
	}
}

void topology_projector::upsert_node(std::unordered_map<std::string, json> &nodes, json node) {
	const auto id = node.value("id", std::string{});
	if(id.empty()) {
		return;
	}
	nodes.emplace(id, std::move(node));
}

