{"cmd":"python3 - <<'PY'
import json
from pathlib import Path

path = Path('be/src/conf/alerts_config.schema.json')
schema = json.loads(path.read_text())
props = schema['$defs']['alertRule']['properties']
metric_prop = props['metric']
metrics = metric_prop.get('enum')
if not metrics:
    metrics = [entry['const'] for entry in metric_prop.get('oneOf', [])]

control_names = {
    'ack': 'SRT ACK control packets',
    'ackack': 'SRT ACKACK control packets',
    'dropreq': 'SRT DROPREQ control packets',
    'handshake': 'SRT handshake control packets',
    'keepalive': 'SRT keepalive control packets',
    'nak': 'SRT NAK control packets',
    'other': 'SRT other control packets',
    'peer_error': 'SRT peer error control packets',
    'shutdown': 'SRT shutdown control packets',
    'total': 'SRT control packets',
    'user_defined': 'SRT user-defined control packets',
}
packet_breakdown_names = {
    'control': 'SRT control packets',
    'data': 'SRT data packets',
    'retransmit': 'SRT retransmitted packets',
    'total': 'SRT packets',
}
seq_names = {
    'dup': 'duplicate packets',
    'gap': 'sequence gaps',
    'reorder': 'reordered packets',
}

def unit_for(metric: str):
    if metric.endswith('.count'):
        return 'samples'
    if metric.endswith('.bps') or metric.endswith('.bitrate_bps') or metric.endswith('.headroom_bps'):
        return 'bps'
    if metric.endswith('.pps'):
        return 'pps'
    if metric.endswith('.seconds') or metric == 'interval_sec':
        return 's'
    if metric.endswith('.first_seen') or metric.endswith('.last_seen'):
        return 's'
    if metric.endswith('.speed_mbps'):
        return 'Mbps'
    if metric.endswith('.mtu'):
        return 'bytes'
    if '.bytes.' in metric:
        return 'bytes'
    if '.packets.' in metric or '.dropped.' in metric:
        return 'packets'
    if '.errors.' in metric:
        return 'errors'
    if metric.endswith('.utilization'):
        return 'ratio'
    if metric.endswith('.skew_ppm'):
        return 'ppm'
    if metric.endswith('.skew_ratio'):
        return 'ratio'
    if metric.endswith('.observed_rate'):
        return 'ticks/s'
    if metric.startswith('bitrate.'):
        return 'bps'
    if metric.startswith('packet_rate.'):
        return 'pps'
    if metric.startswith('jitter.') or metric.startswith('interval.'):
        return 's'
    if metric.startswith(('rtt.', 'rttvar.')) and not metric.endswith('.count'):
        return 'decoder-unit'
    if metric.startswith(('rate.', 'rcvrate.', 'bandwidth.')) and not metric.endswith('.count'):
        return 'decoder-unit'
    if metric.startswith('packet_count.'):
        return 'packets'
    if metric.startswith('packet_breakdown.') or metric.startswith('control_type_count.'):
        return 'packets'
    if metric.startswith('seq_stats.'):
        return 'packets'
    if metric.startswith('nak_seqno.') and not metric.endswith('.count'):
        return 'sequence-number'
    if metric == 'link.carrier':
        return 'boolean'
    return None

def desc_for(metric: str, unit):
    parts = metric.split('.')
    if metric.startswith('bitrate.'):
        tail = parts[-1]
        if tail == 'bps':
            return 'Current bitrate in bits per second.'
        if tail == 'count':
            return 'Number of bitrate samples in the current statistics window.'
        return f'{tail.capitalize()} bitrate sample value in bits per second.'
    if metric.startswith('packet_rate.'):
        tail = parts[-1]
        if tail == 'pps':
            return 'Current packet rate in packets per second.'
        if tail == 'count':
            return 'Number of packet-rate samples in the current statistics window.'
        return f'{tail.capitalize()} packet-rate sample value in packets per second.'
    if metric.startswith('jitter.'):
        tail = parts[-1]
        if tail == 'seconds':
            return 'Current jitter value in seconds.'
        if tail == 'count':
            return 'Number of jitter samples in the current statistics window.'
        return f'{tail.capitalize()} jitter sample value in seconds.'
    if metric.startswith('interval.'):
        tail = parts[-1]
        if tail == 'seconds':
            return 'Current packet or request interval in seconds.'
        if tail == 'count':
            return 'Number of interval samples in the current statistics window.'
        return f'{tail.capitalize()} interval sample value in seconds.'
    if metric.startswith('duration.'):
        tail = parts[-1]
        if tail == 'seconds':
            return 'Observed lifetime duration in seconds.'
        return f'{tail.replace("_", " ").capitalize()} timestamp as Unix epoch seconds.'
    if metric == 'interval_sec':
        return 'Interface sampling interval in seconds.'
    if metric.startswith('clock_skew.'):
        tail = parts[-1]
        if tail == 'observed_rate':
            return 'Observed RTP/RTMP timestamp clock rate in ticks per second.'
        if tail == 'skew_ppm':
            return 'Clock skew in parts per million.'
        return 'Clock skew as a ratio relative to the nominal clock rate.'
    if metric.startswith('link.'):
        tail = parts[-1]
        if tail == 'speed_mbps':
            return 'Interface link speed in megabits per second.'
        if tail == 'mtu':
            return 'Interface MTU in bytes.'
        return 'Interface carrier state. This metric is boolean in metrics.log.'
    if metric.startswith('rx.') or metric.startswith('tx.'):
        direction = 'receive' if metric.startswith('rx.') else 'transmit'
        if '.rate.bitrate_bps' in metric:
            return f'Interface {direction} bitrate in bits per second.'
        if '.rate.headroom_bps' in metric:
            return f'Interface {direction} remaining capacity in bits per second.'
        if '.rate.utilization' in metric:
            return f'Interface {direction} utilization ratio from 0.0 to 1.0.'
        base = parts[1]
        window = parts[2] if len(parts) > 2 else ''
        label = {'bytes': 'bytes', 'packets': 'packets', 'errors': 'errors', 'dropped': 'dropped packets'}.get(base, base)
        return f'Interface {direction} {label} {window} counter.'
    if metric.startswith('packet_breakdown.'):
        name = packet_breakdown_names.get(parts[1], parts[1])
        return f'{name} {parts[2]} counter.'
    if metric.startswith('control_type_count.'):
        name = control_names.get(parts[1], parts[1])
        return f'{name} {parts[2]} counter.'
    if metric.startswith('seq_stats.'):
        name = seq_names.get(parts[1], parts[1])
        return f'Sequence {name} {parts[2]} counter.'
    if metric.startswith('packet_count.'):
        return f'Packet {parts[-1]} counter.'
    if metric.startswith('nak_seqno.'):
        tail = parts[-1]
        if tail == 'count':
            return 'Number of SRT NAK sequence number samples.'
        return f'{tail.capitalize()} SRT NAK sequence number sample value.'
    if metric.startswith(('rtt.', 'rttvar.', 'rate.', 'rcvrate.', 'bandwidth.')):
        group = parts[0]
        tail = parts[-1]
        if tail == 'count':
            return f'Number of {group} samples in the current statistics window.'
        return f'{tail.capitalize()} {group} decoder value. Unit follows the tshark SRT decoder output.'
    return f'Metric path {metric}. Unit depends on the metrics.log field.'

one_of = []
for metric in metrics:
    unit = unit_for(metric)
    entry = {
        'const': metric,
        'description': desc_for(metric, unit),
    }
    if unit is not None:
        entry['x-unit'] = unit
    one_of.append(entry)

props['metric'] = {
    'type': 'string',
    'oneOf': one_of,
    'description': 'Dot-separated JSON metric path read from metrics.log entries. Each candidate documents the expected unit for thresholds.'
}
props['error_threshold']['description'] = 'Threshold used by threshold rules to enter alert state. The value uses the same unit as the selected metric.'
props['recover_threshold']['description'] = 'Threshold used by threshold rules to leave alert state. The value uses the same unit as the selected metric. Defaults to error_threshold in stm if omitted.'
props['delta_threshold']['description'] = 'Delta threshold used by counter_delta rules. The value uses the same unit or count increment as the selected metric.'
props['recover_after_sec']['description'] = 'Seconds without counter_delta error before recovery is emitted.'
props['recover_after_sec']['x-unit'] = 's'

path.write_text(json.dumps(schema, indent=2, ensure_ascii=False) + '\n')
PY","workdir":"/var/work/repo3/stm/stm","sandbox_permissions":"require_escalated","justification":"alerts_config.schema.jsonのmetric候補をoneOf+const化し、単位説明とx-unitを追加します。","max_output_tokens":6000}

