namespace {
std::string make_capture_id() {
	auto now = std::chrono::system_clock::now();
	auto sec = std::chrono::time_point_cast<std::chrono::seconds>(now);
	auto us = std::chrono::duration_cast<std::chrono::microseconds>(now - sec).count();
	std::time_t tt = std::chrono::system_clock::to_time_t(sec);
	std::tm tm{};
	gmtime_r(&tt, &tm);
	char buf[64];
	std::snprintf(buf,
	              sizeof(buf),
	              "%04d%02d%02dT%02d%02d%02dZ-%06lld-%d",
	              tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
	              tm.tm_hour, tm.tm_min, tm.tm_sec,
	              static_cast<long long>(us),
	              static_cast<int>(getpid()));
	return buf;
}
} // namespace

log_pipeline::log_pipeline(config cfg)
	: m_cfg(std::move(cfg)) {
	if(!m_cfg.dir.empty()) {
		std::filesystem::create_directories(m_cfg.dir);
	}

	m_metrics_writer = std::make_unique<writer>("STM",
	                                           m_cfg.resolve(m_cfg.metrics_file).string(),
	                                           m_cfg.rotate_size_bytes,
	                                           m_cfg.rotate_files,
	                                           m_cfg.truncate_on_start);
	m_streams_writer = std::make_unique<list_writer>("STM_LIST",
	                                                m_cfg.resolve(m_cfg.streams_file).string(),
	                                                m_cfg.rotate_size_bytes,
	                                                m_cfg.rotate_files,
	                                                m_cfg.truncate_on_start);
	m_event_writer = std::make_unique<writer>("STM_EVENT",
	                                        m_cfg.resolve(m_cfg.events_file).string(),
	                                        m_cfg.rotate_size_bytes,
	                                        m_cfg.rotate_files,
	                                        m_cfg.truncate_on_start);
	m_timeline_writer = std::make_unique<writer>("STM_TIMELINE",
	                                           m_cfg.resolve(m_cfg.timeline_file).string(),
	                                           m_cfg.rotate_size_bytes,
	                                           m_cfg.rotate_files,
	                                           m_cfg.truncate_on_start);
	m_topology_writer = std::make_unique<writer>("STM_TOPOLOGY",
	                                           m_cfg.resolve(m_cfg.topology_file).string(),
	                                           m_cfg.rotate_size_bytes,
	                                           m_cfg.rotate_files,
	                                           m_cfg.truncate_on_start);
	m_timeline_sink = std::make_unique<timeline_sink>(timeline_sink::config{
		.live_writer = *m_timeline_writer,
		.capture_id = make_capture_id(),
		.history_root = m_cfg.history_enabled ? m_cfg.resolve(m_cfg.timeline_history_dir) : std::filesystem::path{},
	});
	if(m_cfg.history_enabled) {
		m_event_hourly_writer = std::make_unique<time_rotating_writer>("STM_EVENT_HOURLY",
		                                                          m_cfg.resolve(m_cfg.events_hourly_dir),
		                                                          m_cfg.events_part_size_bytes,
		                                                          m_cfg.events_retention_hours);
		m_history_sink = std::make_unique<metrics_history_sink>(metrics_history_sink::config{
			.root_dir = m_cfg.resolve(m_cfg.history_dir),
		});
	}

	m_event_sink = std::make_unique<event_sink>();
	m_event_log_sink = std::make_unique<event_log_sink>(*m_event_writer);
	m_timeline_projector = std::make_unique<timeline_projector>(*m_timeline_sink);
	m_event_sink->add_consumer(*m_event_log_sink);
	if(m_event_hourly_writer) {
		m_event_hourly_log_sink = std::make_unique<event_log_sink>(*m_event_hourly_writer);
		m_event_sink->add_consumer(*m_event_hourly_log_sink);
	}
	m_event_sink->add_consumer(*m_timeline_projector);
}

event_sink& log_pipeline::events() {
	return *m_event_sink;
}

void log_pipeline::write_metrics(const json &root) {
	m_metrics_writer->dump(root);
}

void log_pipeline::write_streams(const json &root) {
	m_streams_writer->dump(root);
}

void log_pipeline::write_topology(const json &root) {
	m_topology_writer->dump(root);
}

void log_pipeline::append_metrics_history(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	if(!m_history_sink) {
		return;
	}
	m_history_sink->append_snapshot(now, metrics, interfaces);
}
