			out.by_flow[metric_key(stream_key, flow_key)].push_back(alert);
		}
		else if(!stream_key.empty()) {
			out.by_stream[stream_key].push_back(alert);
		}

		const auto interface_id = json_string_or_empty(alert, "interface_id");
		if(!interface_id.empty()) {
			out.by_interface["id:" + interface_id].push_back(alert);
		}
		const auto name = json_string_or_empty(alert, "name");
		if(!name.empty()) {
			out.by_interface["name:" + name].push_back(alert);
		}
	}
	return out;
}

std::string topology_projector::metric_key(const std::string &stream_key, const std::string &flow_key) {
	return stream_key + "\n" + flow_key;
}

topology_projector::endpoint_parts topology_projector::parse_endpoint(const std::string &value) {
	endpoint_parts out;
	if(value.empty()) {
		return out;
	}
	if(value.front() == '[') {
		const auto close = value.find(']');
		if(close == std::string::npos) {
			out.host = value;
			return out;
		}
		out.host = value.substr(1, close - 1);
		if(close + 1 < value.size() && value[close + 1] == ':') {
			out.port = std::atoi(value.c_str() + close + 2);
			out.has_port = true;
		}
		return out;
	}

	const auto colon = value.rfind(':');
	if(colon == std::string::npos || value.find(':') != colon) {
		out.host = value;
		return out;
	}
	out.host = value.substr(0, colon);
	out.port = std::atoi(value.c_str() + colon + 1);
	out.has_port = true;
	return out;
}

std::string topology_projector::transport_from_entry(const json &stream_entry, const json &flow_entry, const json *metric_entry) {
	for(const json *candidate : {&flow_entry, metric_entry}) {
		if(candidate != nullptr && candidate->is_object() && candidate->contains("ip_proto") && (*candidate)["ip_proto"].is_number_integer()) {
			const auto transport = transport_from_ip_proto((*candidate)["ip_proto"].get<int>());
			if(transport != "unknown") {
				return transport;
			}
		}
	}
	return transport_from_proto(stream_entry.value("proto", std::string{}));
}

std::string topology_projector::transport_from_ip_proto(int ip_proto) {
	switch(ip_proto) {
	case 6: return "tcp";
	case 17: return "udp";
	case 1: return "icmp";
	case 58: return "icmpv6";
	case 2: return "igmp";
	default: return "unknown";
	}
}

std::string topology_projector::transport_from_proto(const std::string &proto) {
	const auto p = upper(proto);
	if(p == "ARP") return "arp";
	if(p == "ICMP") return "icmp";
	if(p == "ICMPV6") return "icmpv6";
	if(p == "IGMP") return "igmp";
	if(p == "TCP" || p == "HTTP" || p == "HTTPS" || p == "SSH" || p == "RTMP") return "tcp";
	if(p == "UDP" || p == "RTP" || p == "SRT" || p == "NTP" || p == "DHCP" || p == "DNS" || p == "MDNS" || p == "SSDP") return "udp";
	return "unknown";
}

