	std::shared_ptr<spdlog::logger> m_logger;
	std::string m_current_hour_tag;
	std::filesystem::path m_current_file_path;
	std::uint32_t m_current_part_index{0};
	std::uint64_t m_max_part_size_bytes{0};
	std::uint32_t m_retention_hours{0};
	std::atomic<bool> m_enable;
	int m_interval_sec{3};

	std::string hour_tag(double epoch_sec) const;
	std::filesystem::path file_path_for_tag(const std::string &tag, std::uint32_t part_index) const;
