/* -*- coding: utf-8 -*- */

#include "logger.h"

#include <time.h>

#include <cstdint>
#include <cstdio>
#include <ctime>
#include <iomanip>
#include <sstream>
#include <system_error>

#include "spdlog/spdlog.h"
#include "spdlog/async.h"
#include "spdlog/fmt/ostr.h"
#include "spdlog/sinks/basic_file_sink.h"
#include "spdlog/sinks/rotating_file_sink.h"

#include "json.h"
#include "trace.h"

//--------------------------------------------------------------------------------
logger::logger(const char *name, const char *file, size_t max_size, size_t max_files, bool truncate_on_start, int interval_sec)
	: m_name(name) {
	m_enable = false;

	if(truncate_on_start) {
		std::ofstream ofs(file, std::ios::trunc);
	}

	if(max_size == 0 || max_files == 0) {
		m_logger = spdlog::basic_logger_mt<spdlog::async_factory>(name, file, true);
	}
	else {
		m_logger = spdlog::rotating_logger_mt<spdlog::async_factory>(name, file, max_size, max_files);
	}
	m_logger->set_pattern("%v");
	m_logger->set_level(spdlog::level::trace);

	spdlog::flush_every(std::chrono::seconds(interval_sec));

	m_enable = true;
}

//--------------------------------------------------------------------------------
logger::~logger() {
	if(m_logger) {
		m_logger->flush();
	}

	spdlog::drop(m_name);
}

//--------------------------------------------------------------------------------
int logger::start() {
	m_enable = true;

	return 0;
}

//--------------------------------------------------------------------------------
int logger::stop() {
	m_enable = false;
	m_logger->flush();

	return 0;
}

//--------------------------------------------------------------------------------
int logger::dump(const json &j) {
	if(!m_enable) {
		return 0;
	}

	m_logger->info(j.dump());

	return 0;
}

//--------------------------------------------------------------------------------
int logger::event(const ordered_json &j) {
	if(!m_enable) {
		return 0;
	}

	ordered_json t = { timestamp(), { "type", "event" } };
	if(!j.empty()) {
		t.update(j);
	}

	m_logger->info(t.dump());

	return 0;
}

//--------------------------------------------------------------------------------
int logger::metrics(const ordered_json &j) {
	if(!m_enable) {
		return 0;
	}

	ordered_json t = { timestamp(), { "type", "metrics" } };
	if(!j.empty()) {
		t.update(j);
	}

	m_logger->info(t.dump());

	return 0;
}

//--------------------------------------------------------------------------------
int logger::trace(const ordered_json &j) {
	if(!m_enable) {
		return 0;
	}

	ordered_json t = { timestamp(), { "type", "trace" } };
	if(!j.empty()) {
		t.update(j);
	}

	m_logger->info(t.dump());

	return 0;
}

//--------------------------------------------------------------------------------
int logger::object(const ordered_json &j) {
	if(!m_enable) {
		return 0;
	}

	ordered_json t = { timestamp("date") };
	if(!j.empty()) {
		t.update(j);
	}

	m_logger->info(t.dump());

	return 0;
}

//--------------------------------------------------------------------------------
ordered_json logger::timestamp(const std::string &key) {
	timespec ts;
	clock_gettime(CLOCK_REALTIME, &ts);
	std::tm *ptm = std::localtime(&ts.tv_sec);

	char work[64];
	std::snprintf(work,
	              sizeof(work),
	              "%04d-%02d-%02dT%02d:%02d:%02d.%03d%+03d%02d",
	              ptm->tm_year + 1900, ptm->tm_mon + 1, ptm->tm_mday,
	              ptm->tm_hour, ptm->tm_min, ptm->tm_sec, (int)(ts.tv_nsec / 1000000),
	              (int)(ptm->tm_gmtoff / 3600), (int)(ptm->tm_gmtoff % 3600) / 60);

	return { key, work };
}

//--------------------------------------------------------------------------------
time_logger::time_logger(const char *name,
                         const std::filesystem::path &root_dir,
                         std::uint64_t max_part_size_bytes,
                         std::uint32_t retention_hours,
                         int interval_sec)
	: m_name(name)
	, m_root_dir(root_dir)
	, m_max_part_size_bytes(max_part_size_bytes)
	, m_retention_hours(retention_hours)
	, m_enable(false)
	, m_interval_sec(interval_sec) {
	if(m_root_dir.empty() == false) {
		std::filesystem::create_directories(m_root_dir);
	}
	m_enable = true;
}

//--------------------------------------------------------------------------------
time_logger::~time_logger() {
	if(m_logger) {
		m_logger->flush();
	}
	if(m_name.empty() == false) {
		spdlog::drop(m_name);
	}
}

//--------------------------------------------------------------------------------
int time_logger::start() {
	m_enable = true;
	return 0;
}

//--------------------------------------------------------------------------------
int time_logger::stop() {
	m_enable = false;
	if(m_logger) {
		m_logger->flush();
	}
	return 0;
}

//--------------------------------------------------------------------------------
int time_logger::dump(const json &j) {
	if(!m_enable) {
		return 0;
	}
	timespec ts{};
	clock_gettime(CLOCK_REALTIME, &ts);
	const double now = static_cast<double>(ts.tv_sec) + static_cast<double>(ts.tv_nsec) / 1000000000.0;
	rotate_if_needed(now);
	if(!m_logger) {
		return -1;
	}
	m_logger->info(j.dump());
	enforce_part_size();
	return 0;
}

//--------------------------------------------------------------------------------
std::string time_logger::hour_tag(double epoch_sec) const {
	std::time_t tt = static_cast<std::time_t>(epoch_sec);
	std::tm tm{};
	gmtime_r(&tt, &tm);
	std::ostringstream tag;
	tag << std::setfill('0')
	    << std::setw(4) << (tm.tm_year + 1900)
	    << std::setw(2) << (tm.tm_mon + 1)
	    << std::setw(2) << tm.tm_mday
	    << std::setw(2) << tm.tm_hour;
	return tag.str();
}

//--------------------------------------------------------------------------------
std::filesystem::path time_logger::file_path_for_tag(const std::string &tag, std::uint32_t part_index) const {
	if(tag.size() != 10) {
		return m_root_dir / "unknown.ndjson";
	}
	const std::string day = tag.substr(0, 8);
	const std::string hour = tag.substr(8, 2);
	if(part_index == 0) {
		return m_root_dir / day / (hour + ".ndjson");
	}
	return m_root_dir / day / (hour + ".part" + std::to_string(part_index) + ".ndjson");
}

//--------------------------------------------------------------------------------
void time_logger::rotate_if_needed(double epoch_sec) {
	const std::string tag = hour_tag(epoch_sec);
	if(tag == m_current_hour_tag && m_logger) {
		return;
	}

	if(m_logger) {
		m_logger->flush();
		spdlog::drop(m_name);
		m_logger.reset();
	}

	const auto file_path = file_path_for_tag(tag, 0);
	std::filesystem::create_directories(file_path.parent_path());
	m_logger = spdlog::basic_logger_mt<spdlog::async_factory>(m_name, file_path.string(), true);
	m_logger->set_pattern("%v");
	m_logger->set_level(spdlog::level::trace);
	spdlog::flush_every(std::chrono::seconds(m_interval_sec));
	m_current_hour_tag = tag;
	m_current_part_index = 0;
	m_current_file_path = file_path;
	cleanup_retention(epoch_sec);
}

//--------------------------------------------------------------------------------
void time_logger::enforce_part_size() {
	if(m_max_part_size_bytes == 0 || !m_logger || m_current_file_path.empty()) {
		return;
	}
	std::error_code ec{};
	const auto size = std::filesystem::file_size(m_current_file_path, ec);
	if(ec || size < m_max_part_size_bytes) {
		return;
	}

	m_logger->flush();
	spdlog::drop(m_name);
	m_logger.reset();

	++m_current_part_index;
	m_current_file_path = file_path_for_tag(m_current_hour_tag, m_current_part_index);
	std::filesystem::create_directories(m_current_file_path.parent_path());
	m_logger = spdlog::basic_logger_mt<spdlog::async_factory>(m_name, m_current_file_path.string(), true);
	m_logger->set_pattern("%v");
	m_logger->set_level(spdlog::level::trace);
	spdlog::flush_every(std::chrono::seconds(m_interval_sec));
}

//--------------------------------------------------------------------------------
void time_logger::cleanup_retention(double epoch_sec) {
	if(m_retention_hours == 0 || m_root_dir.empty()) {
		return;
	}
	const auto cutoff = static_cast<std::time_t>(epoch_sec) -
	                    static_cast<std::time_t>(m_retention_hours) * 3600;
	if(cutoff <= 0) {
		return;
	}

	std::error_code ec{};
	for(const auto &entry : std::filesystem::directory_iterator(m_root_dir, ec)) {
		if(ec) break;
		if(!entry.is_directory()) continue;
		const auto day = entry.path().filename().string();
		if(day.size() != 8) continue;

		std::tm tm{};
		tm.tm_year = std::stoi(day.substr(0, 4)) - 1900;
		tm.tm_mon = std::stoi(day.substr(4, 2)) - 1;
		tm.tm_mday = std::stoi(day.substr(6, 2));
		tm.tm_hour = 23;
		tm.tm_min = 59;
		tm.tm_sec = 59;
		const auto day_end = timegm(&tm);
		if(day_end != static_cast<std::time_t>(-1) && day_end < cutoff) {
			std::filesystem::remove_all(entry.path(), ec);
		}
	}
}

