int app::run(int argc, char *argv[]) {
	if(parse_options(argc, argv, &m_param) != 0) {
		return -1;
	}

    task reporter(std::bind(&app::report, this), 1000);
    reporter.start();

    m_monitor = std::make_unique<monitor>(monitor::config{
		    .log = {
			    .dir = m_param.log_dir,
			    .metrics_file = m_param.metrics_log,
			    .streams_file = m_param.streams_log,
			    .events_file = m_param.events_log,
			    .events_hourly_dir = m_param.events_hourly_dir,
			    .events_part_size_bytes = m_param.events_part_size_bytes,
			    .events_retention_hours = m_param.events_retention_hours,
			    .timeline_file = m_param.timeline_log,
			    .topology_file = m_param.topology_log,
			    .timeline_history_dir = m_param.timeline_history_dir,
			    .history_dir = m_param.history_dir,
			    .rotate_size_bytes = m_param.log_rotate_size_bytes,
			    .rotate_files = m_param.log_rotate_files,
			    .policy_mode = m_param.log_policy_mode,
			    .history_enabled = m_param.log_history_enabled,
			    .truncate_on_start = m_param.log_truncate_on_start,
		    },
		    .input = {
			    .input_mode = m_param.input_mode,
			    .watch_dir = m_param.input_watch_dir,
			    .file = m_param.input_file,
			    .dir = m_param.input_dir,
			    .pcap_prefix = m_param.pcap_prefix,
			    .ring_file_count = m_param.pcap_ring_files,
			    .backlog_trend_threshold = m_param.pcap_backlog_trend_threshold,
		    },
		    .tshark = m_param.tshark,
		    .protocol_map_file = m_param.protocol_map_file,
		    .alert_config_file = m_param.alert_config_file,
	    });

	int rc = 0;
	if(!m_abort) {
		rc = m_monitor->run();
	}

    reporter.stop();

	return rc;
}

