namespace {
std::tm utc_tm(double now) {
	std::time_t tt = static_cast<std::time_t>(std::floor(now));
	std::tm tm{};
	gmtime_r(&tt, &tm);
	return tm;
}
}

metrics_history_sink::metrics_history_sink(config cfg)
	: m_cfg(std::move(cfg)) {
