async function readDashboardLayouts(): Promise<DashboardLayout[]> {
  if (!existsSync(config.dashboardLayoutsFile)) return [DEFAULT_DASHBOARD_LAYOUT];
  try {
    const parsed = JSON.parse(await readFile(config.dashboardLayoutsFile, "utf8")) as unknown;
    if (!Array.isArray(parsed)) return [DEFAULT_DASHBOARD_LAYOUT];
    const layouts = parsed.map(normalizeDashboardLayout).filter(Boolean) as DashboardLayout[];
    return layouts.length > 0 ? layouts : [DEFAULT_DASHBOARD_LAYOUT];
  } catch {
    return [DEFAULT_DASHBOARD_LAYOUT];
  }
}

async function writeDashboardLayouts(layouts: DashboardLayout[]) {
  await writeFile(config.dashboardLayoutsFile, `${JSON.stringify(layouts.map(normalizeDashboardLayout).filter(Boolean), null, 2)}\n`, "utf8");
}

function normalizeDashboardLayout(input: any): DashboardLayout | undefined {
  if (!input || typeof input !== "object") return undefined;
  const id = String(input.id ?? "default");
  const name = String(input.name ?? id);
  const columns = clampInt(input.columns, 6, 48, 24);
  const rowHeight = clampInt(input.rowHeight, 20, 80, 32);
  const legacyCells = Array.isArray(input.cells) ? input.cells.map((cell: any, index: number) => normalizeDashboardCell(cell, index, columns)).filter(Boolean) : [];
  const responsiveColumns = { desktop: 24, tablet: 12, mobile: 4 } as const;
import { createReadStream, existsSync } from "node:fs";
import readline from "node:readline";
import { normalizeInterfacesLine, normalizeStreamsLine, normalizeTopologyLine } from "../normalizer";
import type { InterfaceListItem, StreamListItem, TopologySnapshot } from "../types";

type StreamsSnapshot = {
  time: number;
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
};

type RawRecord = Record<string, any>;

export async function queryStreamsSnapshotAt(file: string, time: number): Promise<StreamsSnapshot | undefined> {
  const line = await findLatestJsonLineAt(file, time);
  if (!line) return undefined;
  const parsed = JSON.parse(line) as RawRecord;
  const snapshotTime = Number(parsed.time ?? time);
  const streams = normalizeStreamsLine(line).map((item) => ({
    ...item.stream,
    overview: { gap: 0, dup: 0, reorder: 0, events: 0 },
    flows: item.stream.flows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      active: flow.active,
      interfaceId: flow.interfaceId,
      interfaceName: flow.interfaceName,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      lastSeen: flow.lastSeen,
      bitrate: flow.metrics.bitrate ?? {},
      sparkline: [],
      overview: { gap: 0, dup: 0, reorder: 0, events: 0 }
    }))
  } satisfies StreamListItem));
  const interfaces = normalizeInterfacesLine(line).map((item) => ({
    key: item.key,
    interfaceId: item.interfaceId,
    name: item.name,
    observed: item.observed,
    available: item.available,
    link: item.link,
    lastSeen: item.lastSeen,
    rx: item.rx,
    tx: item.tx,
    rxRate: item.rxRate,
    txRate: item.txRate,
    rxBitrate: item.rxBitrate,
    txBitrate: item.txBitrate,
    rxSparkline: item.rxSparkline,
    txSparkline: item.txSparkline,
    streamCount: 0
  }));
  return { time: snapshotTime, streams, interfaces };
}

export async function queryTopologySnapshotAt(file: string, time: number): Promise<TopologySnapshot | undefined> {
  const line = await findLatestJsonLineAt(file, time);
  if (!line) return undefined;
  return normalizeTopologyLine(line);
}

async function findLatestJsonLineAt(file: string, time: number) {
  if (!existsSync(file)) return undefined;
  let latestLine: string | undefined;
  let latestTime = Number.NEGATIVE_INFINITY;
  const rl = readline.createInterface({
    input: createReadStream(file),
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line) continue;
    let parsed: RawRecord;
    try {
      parsed = JSON.parse(line) as RawRecord;
    } catch {
      continue;
    }
    const entryTime = Number(parsed.time ?? 0);
    if (!Number.isFinite(entryTime)) continue;
    if (entryTime > time) continue;
    if (entryTime >= latestTime) {
      latestTime = entryTime;
      latestLine = line;
    }
  }
  return latestLine;
}
import type { EventLogItem } from "./types";

type AnyRecord = Record<string, any>;

export function normalizeEventLine(line: string): EventLogItem | undefined {
  const raw = JSON.parse(line) as AnyRecord;
  const time = Number(raw.time ?? Date.now() / 1000);
  const type = String(raw.type ?? "event");
  const source = raw.source ?? {};
  const detail = raw.detail;
  const streamKey = source.stream_key ? String(source.stream_key) : undefined;
  const flowKey = source.flow_key ? String(source.flow_key) : undefined;
  const proto = source.proto ? String(source.proto) : undefined;
  const interfaceId = interfaceIdFromKey(flowKey) ?? interfaceIdFromKey(streamKey);
  return {
    id: `${time}:${type}:${streamKey ?? "system"}:${flowKey ?? ""}`,
    time,
    type,
    level: levelForType(type),
    scope: flowKey ? "flow" : streamKey ? "stream" : "system",
    proto,
    interfaceId,
    streamKey,
    flowKey,
    targetLabel: targetLabel(proto, streamKey, flowKey, detail),
    message: messageForType(type),
    detail
  };
}

function levelForType(type: string): EventLogItem["level"] {
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string) {
  return type
    .split("_")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function targetLabel(proto?: string, streamKey?: string, flowKey?: string, detail?: AnyRecord) {
  const endpoint = detail?.endpoint;
  if (proto && endpoint?.a && endpoint?.b) return `${proto} ${endpoint.a} ↔ ${endpoint.b}`;
  if (flowKey) return shortKey(flowKey);
  if (streamKey) return shortKey(streamKey);
  return "System";
}

function shortKey(key: string) {
  return key.length > 96 ? `${key.slice(0, 93)}...` : key;
}

function interfaceIdFromKey(key?: string) {
  const match = key?.match(/(?:^|\|)if=(\d+)/);
  return match ? Number(match[1]) : undefined;
}
