export function ensureLogFilesExist() {
  const required = [
    { label: "streams", path: config.streamsLog },
    { label: "metrics", path: config.metricsLog },
    { label: "events", path: config.eventsLog },
    { label: "timeline", path: config.timelineLog }
  ];

  for (const file of required) {
    if (!existsSync(file.path)) {
      throw new Error(`missing ${file.label} log file: ${file.path}`);
    }
  }
}

function resolveDirValue(value: unknown, label: string) {
  const dirName = String(value ?? "").trim();
  if (!dirName) throw new Error(`missing ${label} directory`);
  return dirName;
}

function resolveDirPath(baseDir: string, dirValue: string) {
  if (path.isAbsolute(dirValue)) {
    return dirValue;
  }
  return path.resolve(baseDir, dirValue);
}

function resolveLogFileName(value: unknown, label: string) {
  const fileName = String(value ?? "").trim();
  if (!fileName) throw new Error(`missing ${label} log file name`);
  if (path.basename(fileName) !== fileName) {
    throw new Error(`${label} log file must be a file name, not a path: ${fileName}`);
  }
  return fileName;
}

function resolveRootDir() {
  const cwd = process.cwd();
  if (path.basename(cwd) === "server" && existsSync(path.join(cwd, "package.json"))) {
    return path.resolve(cwd, "..");
  }
  if (existsSync(path.join(cwd, "client", "package.json")) && existsSync(path.join(cwd, "server", "package.json"))) {
    return cwd;
  }
  if (existsSync(path.join(cwd, "fe", "client", "package.json")) && existsSync(path.join(cwd, "fe", "server", "package.json"))) {
    return path.join(cwd, "fe");
  }
  if (existsSync(path.join(cwd, "server", "package.json"))) {
    return cwd;
  }
  return path.resolve(cwd, "..");
}

function parseArgs(args: string[]) {
  const parsed: Record<string, string> = {};
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith("--")) continue;
    const [rawKey, ...rest] = arg.slice(2).split("=");
    const inlineValue = rest.join("=");
    const value = inlineValue || (args[index + 1]?.startsWith("--") ? "" : args[index + 1] ?? "");
    if (!rawKey || !value) continue;
    if (!inlineValue) index += 1;
    if (rawKey === "log-dir") parsed.logDir = value;
    else if (rawKey === "log-streams") parsed.logStreams = value;
    else if (rawKey === "log-metrics") parsed.logMetrics = value;
    else if (rawKey === "log-events") parsed.logEvents = value;
    else if (rawKey === "log-events-dir") parsed.logEventsDir = value;
    else if (rawKey === "log-event-journal-dir") parsed.logEventJournalDir = value;
    else if (rawKey === "log-timeline") parsed.logTimeline = value;
    else if (rawKey === "log-topology") parsed.logTopology = value;
    else if (rawKey === "log-timeline-dir") parsed.logTimelineDir = value;
    else if (rawKey === "log-history-dir") parsed.logHistoryDir = value;
    else if (rawKey === "log-metrics-raw-dir") parsed.logMetricsRawDir = value;
    else if (rawKey === "log-metrics-rollup-dir") parsed.logMetricsRollupDir = value;
    else if (rawKey === "log-stream-state-dir") parsed.logStreamStateDir = value;
    else if (rawKey === "host") parsed.host = value;
    else if (rawKey === "port") parsed.port = value;
    else if (rawKey === "max-events") parsed.maxEvents = value;
    else if (rawKey === "max-timeline-rows") parsed.maxTimelineRows = value;
    else if (rawKey === "streams-patch-interval-ms") parsed.streamsPatchIntervalMs = value;
    else if (rawKey === "ws-max-buffered-bytes") parsed.wsMaxBufferedBytes = value;
    else if (rawKey === "http-access-log") parsed.httpAccessLog = value;
    else if (rawKey === "metrics-chunk-log") parsed.metricsChunkLog = value;
    else if (rawKey === "events-query-debug-log") parsed.eventsQueryDebugLog = value;
    else if (rawKey === "diagnostic-log") parsed.diagnosticLog = value;
  }
  return parsed;
}

function toBool(value: unknown, defaultValue: boolean) {
  if (value === undefined || value === null || value === "") return defaultValue;
  const normalized = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return defaultValue;
}
import { createReadStream, existsSync, statSync } from "node:fs";
import readline from "node:readline";
import fastify from "fastify";
import fastifyStatic from "@fastify/static";
import { config, ensureLogFilesExist } from "./config";
import { TailFile } from "./ingest/tailFile";
import { normalizeInterfacesLine, normalizeMetricsLine, normalizeStreamsLine, normalizeTimelineLine, normalizeTopologyLine } from "./normalizer";
import { queryTopologySnapshotAt } from "./history/snapshot_query";
import { normalizeEventLine } from "./events";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";
import type { EventLogItem } from "./types";

async function main() {
  ensureLogFilesExist();
  diagnostic("startup cwd=" + process.cwd() + " root=" + config.rootDir + " logDir=" + config.logDir + " port=" + config.port);
  for (const entry of Object.entries({ streams: config.streamsLog, metrics: config.metricsLog, events: config.eventsLog, timeline: config.timelineLog, topology: config.topologyLog })) {
    try {
      const info = statSync(entry[1]);
      diagnostic("file " + entry[0] + " path=" + entry[1] + " size=" + info.size + " mtime=" + info.mtime.toISOString());
    } catch (error) {
      diagnostic("file " + entry[0] + " path=" + entry[1] + " error=" + String(error));
    }
  }

  const app = fastify({ logger: config.httpAccessLog });
  const store = new StreamStore(
    config.historyWindowSec,
    config.timelineWindowSec,
    config.staleAfterSec,
    config.lostRetentionSec,
    config.maxEvents,
    config.maxTimelineRows
  );

  await loadInitialEvents(config.eventsLog, config.maxEvents, (event) => store.addEvent(event));

  const initialTopology = await queryTopologySnapshotAt(config.topologyLog, Date.now() / 1000);
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic("initial state events=" + store.listEvents({ limit: config.maxEvents }).length + " topology=" + (initialTopology ? "loaded" : "missing"));

  await registerRoutes(app, store);

  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, {
      root: config.clientDist,
      prefix: "/"
    });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") {
        return reply.code(404).send({ error: "not found" });
      }
      return reply.sendFile("index.html");
    });
  }

  const sockets = new SocketServer(app.server, store, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  sockets.start();

  const streamsTail = new TailFile({
    path: config.streamsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        store.upsertInterfaces(normalizeInterfacesLine(line));
        store.applyStreamSnapshot(normalizeStreamsLine(line).map((item) => item.stream), Date.now() / 1000);
      } catch (error) {
        app.log.warn({ error }, "failed to parse streams log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail streams log")
  });

  const metricsTail = new TailFile({
    path: config.metricsLog,
    pollMs: config.pollMs,
    onChunk: ({ start, end, bytes, lines, observedAt, processedAt, processingMs }) => {
      if (!config.metricsChunkLog) return;
      app.log.info({
        path: config.metricsLog,
        start,
        end,
        bytes,
        lines,
        observedAt,
        observedAtIso: new Date(observedAt).toISOString(),
        processedAt,
        processedAtIso: new Date(processedAt).toISOString(),
        processingMs
      }, "metrics log update detected");
    },
    onLine: (line) => {
      try {
        store.upsertInterfaces(normalizeInterfacesLine(line));
        for (const item of normalizeMetricsLine(line)) store.addMetric(item);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metrics log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail metrics log")
  });


  const eventsTail = new TailFile({
    path: config.eventsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        const event = normalizeEventLine(line);
        if (event) store.addEvent(event);
      } catch (error) {
        app.log.warn({ error }, "failed to parse events log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail events log")
  });



  const topologyTail = new TailFile({
    path: config.topologyLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        const snapshot = normalizeTopologyLine(line);
        if (snapshot) store.applyTopologySnapshot(snapshot);
      } catch (error) {
        app.log.warn({ error }, "failed to parse topology log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail topology log")
  });

  const timelineTail = new TailFile({
    path: config.timelineLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        const item = normalizeTimelineLine(line);
        if (item) store.addTimelineEvent(item);
      } catch (error) {
        app.log.warn({ error }, "failed to parse timeline log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail timeline log")
  });

  streamsTail.start();
  metricsTail.start();
  eventsTail.start();
  timelineTail.start();
  topologyTail.start();

  const close = async () => {
    streamsTail.stop();
    metricsTail.stop();
    eventsTail.stop();
    timelineTail.stop();
    topologyTail.stop();
    await app.close();
  };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());

  await app.listen({ host: config.host, port: config.port });
}

function diagnostic(message: string) {
  if (config.diagnosticLog) console.error("[STM_DIAG] " + message);
}

async function loadInitialEvents(file: string, limit: number, onEvent: (event: EventLogItem) => void) {
  const retained: EventLogItem[] = [];
  const input = createReadStream(file);
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const event = normalizeEventLine(line);
      if (!event) continue;
      retained.push(event);
      if (retained.length > limit) retained.shift();
    } catch {
      // Ignore malformed historical lines.
    }
  }
  for (const event of retained) onEvent(event);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
import { readFile, writeFile } from "node:fs/promises";
