private:
	config m_cfg;
	std::unique_ptr<time_rotating_writer> m_updates_writer;
	json m_previous = json::object();
	std::int64_t m_last_checkpoint_bucket{-1};
	std::uint64_t m_update_seq{0};
	std::uint64_t m_checkpoint_seq{0};

	static json diff_collection(const json &previous, const json &current, const char *field);
	static std::filesystem::path checkpoint_path(const std::filesystem::path &root, double time);
	void write_checkpoint(double time, const json &topology, const json &source);
};

