    else if (rawKey === "log-topology") parsed.logTopology = value;
    else if (rawKey === "log-timeline-dir") parsed.logTimelineDir = value;
    else if (rawKey === "log-history-dir") parsed.logHistoryDir = value;
    else if (rawKey === "log-metrics-raw-dir") parsed.logMetricsRawDir = value;
    else if (rawKey === "log-metrics-rollup-dir") parsed.logMetricsRollupDir = value;
    else if (rawKey === "log-stream-state-dir") parsed.logStreamStateDir = value;
    else if (rawKey === "log-topology-checkpoint-dir") parsed.logTopologyCheckpointDir = value;
    else if (rawKey === "log-topology-updates-dir") parsed.logTopologyUpdatesDir = value;
    else if (rawKey === "host") parsed.host = value;
    else if (rawKey === "port") parsed.port = value;
    else if (rawKey === "max-events") parsed.maxEvents = value;
    else if (rawKey === "max-timeline-rows") parsed.maxTimelineRows = value;
    else if (rawKey === "streams-patch-interval-ms") parsed.streamsPatchIntervalMs = value;
    else if (rawKey === "ws-max-buffered-bytes") parsed.wsMaxBufferedBytes = value;
    else if (rawKey === "http-access-log") parsed.httpAccessLog = value;
    else if (rawKey === "metrics-chunk-log") parsed.metricsChunkLog = value;
    else if (rawKey === "events-query-debug-log") parsed.eventsQueryDebugLog = value;
    else if (rawKey === "diagnostic-log") parsed.diagnosticLog = value;
  }
  return parsed;
}

function toBool(value: unknown, defaultValue: boolean) {
  if (value === undefined || value === null || value === "") return defaultValue;
  const normalized = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return defaultValue;
}
