std::string record_id(const json &source, const char *suffix, std::uint64_t sequence) {
	const auto source_id = source.value("record_id", std::string{});
	if(!source_id.empty()) return source_id + suffix;
	return "topology:" + std::to_string(sequence);
}
}

topology_state_projector::topology_state_projector(config cfg)
	: m_cfg(std::move(cfg)) {
	std::filesystem::create_directories(m_cfg.root_dir / "checkpoint");
	m_updates_writer = std::make_unique<time_rotating_writer>("STM_PROJECTOR_TOPOLOGY_UPDATES",
	                                                        m_cfg.root_dir / "updates",
	                                                        m_cfg.part_size_bytes,
	                                                        m_cfg.retention_hours);
}

void topology_state_projector::publish(double time, const json &topology, const json &source) {
	if(time <= 0.0 || !topology.is_object()) return;

	const auto nodes = diff_collection(m_previous, topology, "nodes");
	const auto edges = diff_collection(m_previous, topology, "edges");
	if(!nodes["upserts"].empty() || !nodes["removes"].empty() ||
	   !edges["upserts"].empty() || !edges["removes"].empty()) {
		const auto sequence = m_update_seq++;
		json update{
			{"schema_version", 2},
			{"record_type", "topology_delta"},
			{"record_id", record_id(source, ":topology-delta", sequence)},
			{"sequence", sequence},
			{"time", time},
			{"source", source},
			{"nodes", nodes},
			{"edges", edges},
		};
		m_updates_writer->dump_at(time, update);
	}

	m_previous = topology;
	const auto bucket = static_cast<std::int64_t>(std::floor(time / static_cast<double>(m_cfg.checkpoint_interval_sec)));
	if(m_last_checkpoint_bucket != bucket) {
		write_checkpoint(time, topology, source);
		m_last_checkpoint_bucket = bucket;
		prune_checkpoints(time);
	}
}

json topology_state_projector::export_state() const {
	return json{
		{"previous", m_previous},
		{"last_checkpoint_bucket", m_last_checkpoint_bucket},
		{"update_seq", m_update_seq},
		{"checkpoint_seq", m_checkpoint_seq},
	};
}

void topology_state_projector::import_state(const json &state) {
	if(!state.is_object()) return;
	if(state.contains("previous") && state["previous"].is_object()) m_previous = state["previous"];
	if(state.contains("last_checkpoint_bucket") && state["last_checkpoint_bucket"].is_number_integer()) {
		m_last_checkpoint_bucket = state["last_checkpoint_bucket"].get<std::int64_t>();
	}
	if(state.contains("update_seq") && state["update_seq"].is_number_unsigned()) {
		m_update_seq = state["update_seq"].get<std::uint64_t>();
	}
	if(state.contains("checkpoint_seq") && state["checkpoint_seq"].is_number_unsigned()) {
		m_checkpoint_seq = state["checkpoint_seq"].get<std::uint64_t>();
	}
}

json topology_state_projector::diff_collection(const json &previous, const json &current, const char *field) {
	const auto before = index_by_id(previous.value(field, json::array()));
	const auto after = index_by_id(current.value(field, json::array()));
	json::array_t upserts;
	json::array_t removes;

	for(const auto &[id, value] : after) {
		const auto before_it = before.find(id);
		if(before_it == before.end() || before_it->second != value) {
			upserts.push_back(value);
		}
	}
	for(const auto &[id, _] : before) {
		if(!after.contains(id)) removes.push_back(id);
	}
	return json{{"upserts", std::move(upserts)}, {"removes", std::move(removes)}};
}

std::filesystem::path topology_state_projector::checkpoint_path(const std::filesystem::path &root, double time) {
	const auto seconds = static_cast<std::time_t>(std::floor(time));
	std::tm tm{};
	gmtime_r(&seconds, &tm);
	char day[16];
	char file[16];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);
	std::snprintf(file, sizeof(file), "%02d%02d.json", tm.tm_hour, tm.tm_min);
	return root / "checkpoint" / day / file;
}

void topology_state_projector::write_checkpoint(double time, const json &topology, const json &source) {
	const auto path = checkpoint_path(m_cfg.root_dir, time);
	std::filesystem::create_directories(path.parent_path());
	const auto temporary = path.string() + ".tmp";
	std::ofstream output(temporary, std::ios::trunc);
	if(!output) return;
	const auto sequence = m_checkpoint_seq++;
	json checkpoint{
		{"schema_version", 2},
		{"record_type", "topology_checkpoint"},
		{"record_id", record_id(source, ":topology-checkpoint", sequence)},
		{"sequence", sequence},
		{"time", time},
		{"source", source},
		{"topology", topology},
	};
	output << checkpoint.dump() << '\n';
	output.flush();
	std::error_code ec{};
	std::filesystem::rename(temporary, path, ec);
	if(ec) {
		std::filesystem::remove(path, ec);
		ec.clear();
		std::filesystem::rename(temporary, path, ec);
	}
}

void topology_state_projector::prune_checkpoints(double now) const {
	if(m_cfg.retention_hours == 0U) return;
	const double oldest = now - static_cast<double>(m_cfg.retention_hours) * 3600.0;
	std::error_code ec{};
	const auto root = m_cfg.root_dir / "checkpoint";
	for(const auto &entry : std::filesystem::recursive_directory_iterator(root, ec)) {
		if(ec) break;
		if(!entry.is_regular_file() || entry.path().extension() != ".json") continue;
		std::ifstream input(entry.path());
		json checkpoint;
		try {
			input >> checkpoint;
		}
		catch(const std::exception &) {
			continue;
		}
		if(checkpoint.value("record_type", std::string{}) != "topology_checkpoint") continue;
		if(checkpoint.value("time", 0.0) < oldest) {
			std::filesystem::remove(entry.path(), ec);
			ec.clear();
		}
	}
}

import { createReadStream, existsSync } from "node:fs";
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import readline from "node:readline";
import { normalizeTopologyLine } from "../normalizer";
import type { TopologyEdge, TopologyNode, TopologySnapshot } from "../types";

type RawRecord = Record<string, any>;

type QueryOptions = {
  checkpointDir: string;
  updatesDir: string;
  time: number;
};

type Checkpoint = {
  time: number;
  topology: RawRecord;
};

type TopologyDelta = {
  time: number;
  sequence: number;
  nodes?: { upserts?: TopologyNode[]; removes?: string[] };
  edges?: { upserts?: TopologyEdge[]; removes?: string[] };
};

export async function queryProjectedTopologyAt(options: QueryOptions): Promise<TopologySnapshot | undefined> {
  if (!Number.isFinite(options.time) || options.time <= 0) return undefined;
  const checkpoint = await findLatestCheckpoint(options.checkpointDir, options.time);
  if (!checkpoint) return undefined;

  const topology = cloneTopology(checkpoint.topology, checkpoint.time);
  const updates = await readTopologyDeltas(options.updatesDir, checkpoint.time, options.time);
  for (const update of updates) applyDelta(topology, update);
  topology.time = updates.length > 0 ? updates[updates.length - 1].time : checkpoint.time;
  return normalizeTopologyLine(JSON.stringify(topology));
}

async function findLatestCheckpoint(root: string, time: number): Promise<Checkpoint | undefined> {
  let latest: Checkpoint | undefined;
  const cutoff = minutePathTag(time);
  const files = await listFiles(root, ".json");
  for (const file of files.reverse()) {
    if (path.relative(root, file).replaceAll(path.sep, "/") > cutoff) continue;
    let parsed: RawRecord;
    try {
      parsed = JSON.parse(await readFile(file, "utf8")) as RawRecord;
    } catch {
      continue;
    }
    if (parsed.record_type !== "topology_checkpoint" || !parsed.topology || typeof parsed.topology !== "object") continue;
    const checkpointTime = Number(parsed.time ?? parsed.topology.time ?? 0);
    if (!Number.isFinite(checkpointTime) || checkpointTime > time) continue;
    latest = { time: checkpointTime, topology: parsed.topology };
    break;
  }
  return latest;
}

async function readTopologyDeltas(root: string, from: number, to: number): Promise<TopologyDelta[]> {
  const updates: TopologyDelta[] = [];
  const firstHour = hourPathTag(from);
  const lastHour = hourPathTag(to);
  for (const file of await listFiles(root, ".ndjson")) {
    const relative = path.relative(root, file).replaceAll(path.sep, "/");
    const hour = relative.slice(0, "YYYYMMDD/HH".length);
    if (hour < firstHour || hour > lastHour) continue;
    const lines = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of lines) {
      if (!line) continue;
      let parsed: RawRecord;
      try {
        parsed = JSON.parse(line) as RawRecord;
      } catch {
        continue;
      }
      if (parsed.record_type !== "topology_delta") continue;
      const time = Number(parsed.time ?? 0);
      if (!Number.isFinite(time) || time <= from || time > to) continue;
      updates.push({ time, sequence: Number(parsed.sequence ?? 0), nodes: parsed.nodes, edges: parsed.edges });
    }
  }
  updates.sort((left, right) => left.time - right.time || left.sequence - right.sequence);
  return updates;
}

function cloneTopology(value: RawRecord, fallbackTime: number): RawRecord {
  return {
    ...value,
    time: Number(value.time ?? fallbackTime),
    nodes: Array.isArray(value.nodes) ? value.nodes.map((item) => ({ ...item })) : [],
    edges: Array.isArray(value.edges) ? value.edges.map((item) => ({ ...item })) : []
  };
}

function applyDelta(topology: RawRecord, delta: TopologyDelta) {
  applyCollection<TopologyNode>(topology, "nodes", delta.nodes, (item) => item.id);
  applyCollection<TopologyEdge>(topology, "edges", delta.edges, (item) => item.id);
}

function applyCollection<T extends { id: string }>(
  topology: RawRecord,
  field: "nodes" | "edges",
  change: { upserts?: T[]; removes?: string[] } | undefined,
  key: (item: T) => string
) {
  if (!change) return;
  const values = Array.isArray(topology[field]) ? topology[field] as T[] : [];
  const indexed = new Map(values.map((item) => [key(item), item]));
  for (const id of change.removes ?? []) indexed.delete(id);
  for (const item of change.upserts ?? []) {
    if (item && typeof key(item) === "string" && key(item)) indexed.set(key(item), item);
  }
  topology[field] = [...indexed.values()].sort((left, right) => key(left).localeCompare(key(right)));
}

function hourPathTag(time: number) {
  const value = new Date(time * 1000);
  const day = `${value.getUTCFullYear()}${String(value.getUTCMonth() + 1).padStart(2, "0")}${String(value.getUTCDate()).padStart(2, "0")}`;
  return `${day}/${String(value.getUTCHours()).padStart(2, "0")}`;
}

function minutePathTag(time: number) {
  const value = new Date(time * 1000);
  return `${hourPathTag(time)}${String(value.getUTCMinutes()).padStart(2, "0")}.json`;
}

async function listFiles(root: string, extension: string): Promise<string[]> {
  if (!existsSync(root)) return [];
  const files: string[] = [];
  async function walk(directory: string): Promise<void> {
    let entries;
    try {
      entries = await readdir(directory, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const item = path.join(directory, entry.name);
      if (entry.isDirectory()) await walk(item);
      else if (entry.isFile() && item.endsWith(extension)) files.push(item);
    }
  }
  await walk(root);
  return files.sort();
}

