class log_pipeline {
public:
	struct config {
		std::string dir;
		std::string metrics_file{"metrics.log"};
		std::string streams_file{"streams.log"};
		std::string events_file{"events.log"};
		std::string events_hourly_dir{"events"};
		std::uint64_t events_part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t events_retention_hours{72U};
		std::string event_journal_dir{"event-journal"};
		std::string metrics_journal_dir{"metrics-journal"};
		std::uint64_t journal_part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t journal_retention_hours{72U};
		bool journal_enabled{true};
		std::string timeline_file{"timeline.log"};
		std::string topology_file{"topology.log"};
		std::string timeline_history_dir{"timeline"};
		std::string history_dir{"history"};
		std::uint64_t rotate_size_bytes{2ULL * 1024ULL * 1024ULL};
		std::size_t rotate_files{3};
		std::string policy_mode{"live"};
		bool history_enabled{true};
		bool truncate_on_start{true};

		std::filesystem::path resolve(const std::string &filename) const {
			if(dir.empty()) {
				return std::filesystem::path(filename);
			}
			return std::filesystem::path(dir) / filename;
		}
	};

	explicit log_pipeline(config cfg);

	event_sink& events();
	void write_metrics(const json &root);
	void write_streams(const json &root);
	void write_topology(const json &root);
	void append_metrics_history(double now, const json::array_t &metrics, const json::array_t &interfaces);

private:
	config m_cfg;
	std::unique_ptr<writer> m_metrics_writer;
	std::unique_ptr<list_writer> m_streams_writer;
	std::unique_ptr<writer> m_event_writer;
	std::unique_ptr<writer> m_event_hourly_writer;
	std::unique_ptr<time_rotating_writer> m_event_journal_writer;
	std::unique_ptr<time_rotating_writer> m_metrics_journal_writer;
	std::unique_ptr<writer> m_timeline_writer;
	std::unique_ptr<writer> m_topology_writer;
	std::unique_ptr<metrics_history_sink> m_history_sink;
	std::unique_ptr<event_sink> m_event_sink;
	std::unique_ptr<event_log_sink> m_event_log_sink;
	std::unique_ptr<event_log_sink> m_event_hourly_log_sink;
	std::unique_ptr<event_journal_sink> m_event_journal_sink;
	std::string m_capture_id;
	std::uint64_t m_metrics_journal_seq{0};
	std::unique_ptr<timeline_sink> m_timeline_sink;
	std::unique_ptr<timeline_projector> m_timeline_projector;
};

