export function ensureLogFilesExist() {
  if (config.dataSource === "projected") return;

  const required = [
    { label: "streams", path: config.streamsLog },
    { label: "metrics", path: config.metricsLog },
    { label: "events", path: config.eventsLog },
    { label: "timeline", path: config.timelineLog }
  ];
  for (const file of required) {
    if (!existsSync(file.path)) throw new Error(`missing ${file.label} log file: ${file.path}`);
  }
}

function resolveDataSource(value: unknown): DataSource {
  const source = String(value ?? "legacy").trim().toLowerCase();
  if (source === "legacy" || source === "projected") return source;
  throw new Error(`unsupported data source: ${source}; expected legacy or projected`);
}

function resolveDirValue(value: unknown, label: string) {
  const dirName = String(value ?? "").trim();
  if (!dirName) throw new Error(`missing ${label} directory`);
  return dirName;
}

function resolveDirPath(baseDir: string, dirValue: string) {
  return path.isAbsolute(dirValue) ? dirValue : path.resolve(baseDir, dirValue);
}

function resolveFilePath(baseDir: string, value: unknown, label: string) {
  const file = String(value ?? "").trim();
  if (!file) throw new Error(`missing ${label} file`);
  return path.isAbsolute(file) ? file : path.resolve(baseDir, file);
}

function resolveLogFileName(value: unknown, label: string) {
  const fileName = String(value ?? "").trim();
  if (!fileName) throw new Error(`missing ${label} log file name`);
  if (path.basename(fileName) !== fileName) throw new Error(`${label} log file must be a file name, not a path: ${fileName}`);
  return fileName;
}

function resolveRootDir() {
  const cwd = process.cwd();
  if (path.basename(cwd) === "server" && existsSync(path.join(cwd, "package.json"))) return path.resolve(cwd, "..");
  if (existsSync(path.join(cwd, "client", "package.json")) && existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  if (existsSync(path.join(cwd, "fe", "client", "package.json")) && existsSync(path.join(cwd, "fe", "server", "package.json"))) return path.join(cwd, "fe");
  if (existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  return path.resolve(cwd, "..");
}

