int stm_projector::run_once() {
	std::vector<pending_journal_record> pending;
	std::size_t ordinal = 0;
	const auto event_result = m_events.read_after(m_event_cursor, [&](const json &record) {
		pending.push_back(pending_journal_record{
			.time = record_time(record, journal_kind::event),
			.kind = journal_kind::event,
			.ordinal = ordinal++,
			.record = record,
		});
		return 0;
	});
	const auto metrics_result = m_metrics.read_after(m_metrics_cursor, [&](const json &record) {
		pending.push_back(pending_journal_record{
			.time = record_time(record, journal_kind::metrics),
			.kind = journal_kind::metrics,
			.ordinal = ordinal++,
			.record = record,
		});
		return 0;
	});
	std::stable_sort(pending.begin(), pending.end(), [](const auto &left, const auto &right) {
		if(left.time != right.time) return left.time < right.time;
		if(left.kind != right.kind) return left.kind == journal_kind::event;
		return left.ordinal < right.ordinal;
	});
	for(const auto &item : pending) {
		const int rc = item.kind == journal_kind::event ? project_event(item.record) : project_metrics(item.record);
		if(rc != 0) return rc;
	}
	if(event_result.advanced || metrics_result.advanced) {
		save_state();
	}
	trace(1, "projector: events=%zu metrics=%zu", event_result.records, metrics_result.records);
	return 0;
}

int stm_projector::run_follow() {
	for(;;) {
		if(run_once() != 0) {
			return -1;
		}
		std::this_thread::sleep_for(m_cfg.poll_interval);
	}
}

void stm_projector::load_state() {
	std::ifstream input(m_cfg.state_file);
	if(!input) {
		return;
	}
	try {
		json state;
		input >> state;
		m_event_cursor = journal_reader::cursor_from_json(state.value("event_cursor", json::object()));
		m_metrics_cursor = journal_reader::cursor_from_json(state.value("metrics_cursor", json::object()));
		if(m_stream_state) m_stream_state->import_state(state.value("stream_state", json::object()));
		if(state.contains("current_metrics") && state["current_metrics"].is_array()) m_current_metrics = state["current_metrics"].get<json::array_t>();
		if(state.contains("current_interfaces") && state["current_interfaces"].is_array()) m_current_interfaces = state["current_interfaces"].get<json::array_t>();
		if(state.contains("active_alerts") && state["active_alerts"].is_object()) m_active_alerts = state["active_alerts"];
		if(state.contains("last_event_record_id") && state["last_event_record_id"].is_string()) m_last_event_record_id = state["last_event_record_id"];
		if(state.contains("last_metrics_record_id") && state["last_metrics_record_id"].is_string()) m_last_metrics_record_id = state["last_metrics_record_id"];
		if(m_topology_state) m_topology_state->import_state(state.value("topology_state", json::object()));
	}
	catch(const std::exception &e) {
		trace(1, "projector: state load failed: %s", e.what());
	}
}

void stm_projector::save_state() const {
	if(!m_cfg.state_file.parent_path().empty()) {
		std::filesystem::create_directories(m_cfg.state_file.parent_path());
	}
	const auto temporary = m_cfg.state_file.string() + ".tmp";
	std::ofstream output(temporary, std::ios::trunc);
	if(!output) {
		trace(1, "projector: state write failed: %s", temporary.c_str());
		return;
	}
	output << json{
		{"schema_version", 1},
		{"event_cursor", journal_reader::cursor_json(m_event_cursor)},
		{"metrics_cursor", journal_reader::cursor_json(m_metrics_cursor)},
		{"stream_state", m_stream_state ? m_stream_state->export_state() : json::object()},
		{"current_metrics", m_current_metrics},
		{"current_interfaces", m_current_interfaces},
		{"active_alerts", m_active_alerts},
		{"last_event_record_id", m_last_event_record_id},
		{"last_metrics_record_id", m_last_metrics_record_id},
		{"topology_state", m_topology_state ? m_topology_state->export_state() : json::object()},
	}.dump() << '\n';
	output.flush();
	std::error_code ec{};
	std::filesystem::rename(temporary, m_cfg.state_file, ec);
	if(ec) {
		std::filesystem::remove(m_cfg.state_file, ec);
		ec.clear();
		std::filesystem::rename(temporary, m_cfg.state_file, ec);
	}
}

int stm_projector::project_event(const json &record) {
	event_record event;
	if(!as_event_record(record, event)) {
		return 0;
	}
	const int rc = m_timeline_projector->handle_event(event);
	m_last_event_record_id = record.value("record_id", std::string{});
	const bool changed = m_stream_state->apply_event(record);
	const std::string type = record.value("type", std::string{});
	if(type == "alert_detected" || type == "alert_recovered") {
		json alert = record.value("source", json::object());
		const json detail = record.value("detail", json::object());
		if(detail.is_object()) {
			for(const auto &[key, value] : detail.items()) alert[key] = value;
		}
		const std::string key = alert.value("state_key", alert.value("alert_id", std::string{}));
		if(!key.empty()) {
			if(type == "alert_detected") m_active_alerts[key] = std::move(alert);
			else m_active_alerts.erase(key);
		}
	}
	if(changed) write_topology_event(record);
	write_topology(event.time_epoch, record);
	return rc;
}

int stm_projector::project_metrics(const json &record) {
	if(!record.is_object() || record.value("record_type", std::string{}) != "metrics_snapshot") {
		return 0;
	}
	const double time = record.value("time", 0.0);
	if(time <= 0.0 || !record.contains("metrics") || !record["metrics"].is_array() ||
	   !record.contains("interfaces") || !record["interfaces"].is_array()) {
		return 0;
	}
	m_current_metrics = record["metrics"].get<json::array_t>();
	m_current_interfaces = record["interfaces"].get<json::array_t>();
	m_last_metrics_record_id = record.value("record_id", std::string{});
	m_metrics_history->append_snapshot(time, m_current_metrics, m_current_interfaces);
	write_metrics_v2(record);
	write_topology(time, record);
	return 0;
}

void stm_projector::write_topology(double time, const json &source_record) {
	if(!m_topology_writer || !m_topology_projector || !m_stream_state) return;
	json::array_t alerts;
	for(const auto &[_, alert] : m_active_alerts.items()) alerts.push_back(alert);
	const auto streams = m_stream_state->snapshot(time).value("streams", json::array_t{});
	const auto topology = m_topology_projector->build(time, streams, m_current_interfaces, m_current_metrics, alerts);
	m_topology_writer->dump(topology);
	if(m_topology_state) {
		json source{
			{"record_id", source_record.value("record_id", std::string{})},
			{"event_record_id", m_last_event_record_id},
			{"metrics_record_id", m_last_metrics_record_id},
		};
		m_topology_state->publish(time, topology, source);
	}
}

void stm_projector::write_topology_event(const json &event) {
	if(!m_topology_events_writer) return;
	const std::string type = event.value("type", std::string{});
	if(type != "flow_detected" && type != "flow_lost" && type != "flow_recovered") return;
	const auto source = event.value("source", json::object());
	json record{
		{"schema_version", 2},
		{"record_type", "topology_event"},
		{"record_id", event.value("record_id", std::string{}) + ":topology"},
		{"source_record_id", event.value("record_id", std::string{})},
		{"capture_id", event.value("capture_id", std::string{})},
		{"time", event.value("event_time", event.value("time", 0.0))},
		{"type", type == "flow_lost" ? "edge_lost" : (type == "flow_recovered" ? "edge_recovered" : "edge_detected")},
		{"identity", {
			{"stream_key", source.value("stream_key", std::string{})},
			{"flow_key", source.value("flow_key", std::string{})},
		}},
		{"proto", source.value("proto", std::string{})},
		{"scope", source.value("scope", json::object())},
		{"endpoint", event.value("detail", json::object()).value("endpoint", json::object())},
	};
	m_topology_events_writer->dump_at(record["time"].get<double>(), record);
}

void stm_projector::write_metrics_v2(const json &record) {
	if(!m_metrics_v2_writer) return;
	const double time = record.value("time", 0.0);
	for(const auto &entry : m_current_metrics) {
		if(!entry.is_object()) continue;
		const std::string stream_key = entry.value("stream_key", std::string{});
		if(stream_key.empty()) continue;
		const std::string flow_key = entry.value("flow_key", std::string{});
		json sample{
			{"schema_version", 2},
			{"record_type", "metric_sample"},
			{"record_id", record.value("record_id", std::string{}) + ":" + (flow_key.empty() ? stream_key : flow_key)},
			{"capture_id", record.value("capture_id", std::string{})},
			{"time", time},
			{"resolution_sec", 1},
			{"target", {
				{"kind", flow_key.empty() ? "stream" : "flow"},
				{"stream_key", stream_key},
				{"flow_key", flow_key},
				{"scope", entry.value("scope", json::object())},
			}},
			{"metrics", entry},
		};
		m_metrics_v2_writer->dump_at(time, sample);
	}
}

import { createReadStream, existsSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { descriptorForMetric, normalizeInterfacesLine, normalizeMetricsLine, type NormalizedInterfaceInput, type NormalizedMetricInput } from "../normalizer";
import { config } from "../config";
import type { InterfaceMetricsResponse, MetricDescriptor, MetricPoint, NumericStat, StreamMetricsResponse, TimeSeriesMetric } from "../types";

type AnyRecord = Record<string, any>;

type QueryOptions = {
  streamKey: string;
  from: number;
  to: number;
  resolutionSec?: number;
};

type FlowSeries = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export async function queryMetricsSnapshotAt(time: number): Promise<{ interfaces: NormalizedInterfaceInput[]; metrics: NormalizedMetricInput[] } | undefined> {
  let latestTime = Number.NEGATIVE_INFINITY;
  let latestLine: string | undefined;
  for (const file of listHistoryFiles("raw", Math.max(0, time - 3600), time)) {
    const rl = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      try {
        const parsed = JSON.parse(line) as AnyRecord;
        const entryTime = Number(parsed.time ?? 0);
        if (Number.isFinite(entryTime) && entryTime <= time && entryTime >= latestTime) {
          latestTime = entryTime;
          latestLine = line;
        }
      } catch {
        // Skip partial or malformed JSONL records.
      }
    }
  }
  if (!latestLine) return undefined;
  return { interfaces: normalizeInterfacesLine(latestLine), metrics: normalizeMetricsLine(latestLine) };
}

export async function queryInterfaceMetricsHistory(options: { key: string; from: number; to: number }): Promise<InterfaceMetricsResponse | undefined> {
  const points: Array<{ time: number; metrics: Record<string, NumericStat> }> = [];
  let latest: NormalizedInterfaceInput | undefined;
  for (const file of listHistoryFiles("raw", options.from, options.to)) {
    const rl = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      let items: NormalizedInterfaceInput[];
      try { items = normalizeInterfacesLine(line); } catch { continue; }
      const item = items.find((candidate) => candidate.key === options.key);
      if (!item) continue;
      latest = item;
      points.push({ time: item.lastSeen ?? 0, metrics: interfaceMetrics(item) });
    }
  }
  if (!latest) return undefined;
  return {
    key: latest.key,
    interfaceId: latest.interfaceId,
    name: latest.name,
    windowSec: Math.max(1, options.to - options.from),
    metrics: buildMetricSeries(points)
  };
}

export async function queryStreamMetricsHistory(options: QueryOptions): Promise<StreamMetricsResponse> {
  const source = selectSource(options);
  const files = listHistoryFiles(source, options.from, options.to);
  const flows = new Map<string, FlowSeries>();
  const metricKeys = new Set<string>();

  for (const file of files) {
    await readHistoryFile(file, (entryTime, entry) => {
      if (entryTime < options.from || entryTime > options.to) return;
      if (String(entry?.stream_key ?? "") !== options.streamKey) return;
      const flowKey = typeof entry?.flow_key === "string" ? entry.flow_key : undefined;
      if (!flowKey) return;

      const flow = ensureFlowSeries(flows, flowKey, entry);
      const metrics = extractMetrics(entry);
      for (const [metricKey, stat] of Object.entries(metrics)) {
        metricKeys.add(metricKey);
        flow.metrics[metricKey] ??= {
          key: metricKey,
          label: descriptorForMetric(metricKey).label,
          unit: descriptorForMetric(metricKey).unit,
          points: []
        };
        flow.metrics[metricKey].points.push({
          time: entryTime,
          ...stat
        });
      }
    });
  }

  const orderedFlows = [...flows.values()].sort((a, b) => a.label.localeCompare(b.label) || a.flowKey.localeCompare(b.flowKey));
  for (const flow of orderedFlows) {
    for (const metric of Object.values(flow.metrics)) {
      metric.points.sort((a, b) => a.time - b.time);
    }
  }
  const streamBitrate = buildStreamBitrate(orderedFlows);
  if (streamBitrate.points.length > 0) metricKeys.add("bitrate");

  const descriptors = [...metricKeys]
    .map(descriptorForMetric)
    .sort((a, b) => a.priority - b.priority || a.label.localeCompare(b.label));

  return {
    streamKey: options.streamKey,
    windowSec: Math.max(1, options.to - options.from),
    streamBitrate,
    flows: orderedFlows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      metrics: flow.metrics
    })),
    descriptors
  };
}

function interfaceMetrics(item: NormalizedInterfaceInput): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {
    "rx.bitrate": item.rxBitrate,
    "tx.bitrate": item.txBitrate,
    "rx.packets": item.rx.packets,
    "tx.packets": item.tx.packets,
    "rx.errors": item.rx.errors,
    "tx.errors": item.tx.errors,
    "rx.dropped": item.rx.dropped,
    "tx.dropped": item.tx.dropped
  };
  if (item.rxRate?.utilization !== undefined) metrics["rx.utilization"] = scalarMetric(item.rxRate.utilization);
  if (item.txRate?.utilization !== undefined) metrics["tx.utilization"] = scalarMetric(item.txRate.utilization);
  if (item.rxRate?.headroomBps !== undefined) metrics["rx.headroom"] = scalarMetric(item.rxRate.headroomBps);
  if (item.txRate?.headroomBps !== undefined) metrics["tx.headroom"] = scalarMetric(item.txRate.headroomBps);
  return metrics;
}

function scalarMetric(value: number): NumericStat { return { value, avg: value, min: value, max: value }; }

function buildMetricSeries(points: Array<{ time: number; metrics: Record<string, NumericStat> }>): Record<string, TimeSeriesMetric> {
  const result: Record<string, TimeSeriesMetric> = {};
  for (const point of points) {
    for (const [key, stat] of Object.entries(point.metrics)) {
      const descriptor = descriptorForMetric(key);
      result[key] ??= { key, label: descriptor.label, unit: descriptor.unit, points: [] };
      result[key].points.push({ time: point.time, ...stat });
    }
  }
  for (const metric of Object.values(result)) metric.points.sort((left, right) => left.time - right.time);
  return result;
}

function ensureFlowSeries(flows: Map<string, FlowSeries>, flowKey: string, entry: AnyRecord) {
  const existing = flows.get(flowKey);
  if (existing) return existing;
  const role = String(entry?.role ?? inferRoleFromKey(flowKey) ?? "flow");
  const endpointSrc = typeof entry?.endpoint?.src === "string" ? entry.endpoint.src : undefined;
  const endpointDst = typeof entry?.endpoint?.dst === "string" ? entry.endpoint.dst : undefined;
  const created: FlowSeries = {
    flowKey,
    role,
    label: endpointSrc && endpointDst ? `${role}: ${endpointSrc} → ${endpointDst}` : role,
    endpointSrc,
    endpointDst,
    metrics: {}
  };
  flows.set(flowKey, created);
  return created;
}

function buildStreamBitrate(flows: FlowSeries[]): TimeSeriesMetric {
  const byTime = new Map<number, NumericStat[]>();
  for (const flow of flows) {
    const points = flow.metrics["bitrate"]?.points ?? [];
    for (const point of points) {
      const bucket = byTime.get(point.time) ?? [];
      bucket.push(point);
      byTime.set(point.time, bucket);
    }
  }

  const points: MetricPoint[] = [...byTime.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([time, stats]) => ({
      time,
      value: sumStat(stats, "value"),
      avg: sumStat(stats, "avg"),
      min: sumStat(stats, "min"),
      max: sumStat(stats, "max"),
      count: sumStat(stats, "count")
    }));

  return { key: "bitrate", label: "Stream Bitrate", unit: "bps", points };
}

function sumStat(stats: NumericStat[], field: keyof NumericStat) {
  const values = stats.map((stat) => stat[field]).filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  return values.length > 0 ? values.reduce((sum, value) => sum + value, 0) : undefined;
}

function extractMetrics(entry: AnyRecord): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {};
  for (const [key, value] of Object.entries(entry)) {
    if (ignoredMetricKeys.has(key)) continue;
    collectMetric(key, value, metrics);
  }
  return metrics;
}

const ignoredMetricKeys = new Set([
  "proto",
  "stream_key",
  "flow_key",
  "endpoint",
  "role",
  "interface_id",
  "interface_name",
  "payload_type",
  "ssrc"
]);

function collectMetric(prefix: string, value: unknown, output: Record<string, NumericStat>) {
  if (typeof value === "number" && Number.isFinite(value)) {
    output[prefix] = { value, avg: value, min: value, max: value };
    return;
  }

  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const record = value as AnyRecord;
  const stat = statFromObject(record);
  if (stat) {
    output[prefix] = stat;
    return;
  }

  for (const [childKey, childValue] of Object.entries(record)) {
    collectMetric(`${prefix}.${childKey}`, childValue, output);
  }
}

function statFromObject(record: AnyRecord): NumericStat | undefined {
  const stat: NumericStat = {};
  const value = firstNumber(record.value, record.bps, record.pps, record.seconds, record.total);
  if (value !== undefined) stat.value = value;
  if (isNumber(record.avg)) stat.avg = record.avg;
  if (isNumber(record.min)) stat.min = record.min;
  if (isNumber(record.max)) stat.max = record.max;
  if (isNumber(record.count)) stat.count = record.count;

  if (stat.avg === undefined && stat.value !== undefined) stat.avg = stat.value;
  if (stat.min === undefined && stat.value !== undefined) stat.min = stat.value;
  if (stat.max === undefined && stat.value !== undefined) stat.max = stat.value;

  return stat.value !== undefined || stat.avg !== undefined || stat.min !== undefined || stat.max !== undefined
    ? stat
    : undefined;
}

function firstNumber(...values: unknown[]) {
  return values.find(isNumber) as number | undefined;
}

function isNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function inferRoleFromKey(flowKey?: string) {
  if (!flowKey) return undefined;
  const match = flowKey.match(/(?:^|\|)role=([^|]+)/);
  return match?.[1];
}

function selectSource(options: QueryOptions) {
  if ((options.resolutionSec ?? 0) >= 60) return "rollup_1m" as const;
  if (options.to - options.from > 600) return "rollup_1m" as const;
  return "raw" as const;
}

function listHistoryFiles(source: "raw" | "rollup_1m", from: number, to: number) {
  const root = source === "raw" ? config.metricsRawDir : config.metricsRollupDir;
  const files: string[] = [];
  const current = new Date(Math.floor(from) * 1000);
  current.setUTCMinutes(0, 0, 0);
  const end = new Date(Math.floor(to) * 1000);
  end.setUTCMinutes(0, 0, 0);

  while (current.getTime() <= end.getTime()) {
    const yyyy = current.getUTCFullYear().toString().padStart(4, "0");
    const mm = String(current.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(current.getUTCDate()).padStart(2, "0");
    const hh = String(current.getUTCHours()).padStart(2, "0");
    const file = path.join(root, `${yyyy}${mm}${dd}`, `${hh}.jsonl`);
    if (existsSync(file)) files.push(file);
    current.setUTCHours(current.getUTCHours() + 1);
  }

  return files;
}

async function readHistoryFile(file: string, onEntry: (time: number, entry: AnyRecord) => void) {
  const rl = readline.createInterface({
    input: createReadStream(file),
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line) continue;
    const parsed = JSON.parse(line) as AnyRecord;
    const entryTime = Number(parsed.bucket_end ?? parsed.time ?? 0);
    const entries = Array.isArray(parsed.metrics) ? parsed.metrics : [];
    for (const entry of entries) {
      onEntry(entryTime, entry);
    }
  }
}
