#include <cmath>
#include <utility>

metric_sample_projector::metric_sample_projector(config cfg)
	: m_cfg(std::move(cfg)) {
	m_samples_1s_writer = std::make_unique<time_rotating_writer>(
		"STM_PROJECTOR_METRICS_1S",
		m_cfg.root_dir / m_cfg.samples_1s_dir,
		m_cfg.part_size_bytes,
		m_cfg.retention_hours);
	m_samples_1m_writer = std::make_unique<time_rotating_writer>(
		"STM_PROJECTOR_METRICS_1M",
		m_cfg.root_dir / m_cfg.samples_1m_dir,
		m_cfg.part_size_bytes,
		m_cfg.retention_hours);
}

metric_sample_projector::~metric_sample_projector() {
	flush_bucket();
}

void metric_sample_projector::append_snapshot(double now,
                                               const json::array_t &metrics,
                                               const json::array_t &interfaces,
                                               const json &source_record) {
	append_entries(now, metrics, false, source_record);
	append_entries(now, interfaces, true, source_record);
}

double metric_sample_projector::minute_floor(double now) {
	return std::floor(now / 60.0) * 60.0;
}

std::string metric_sample_projector::target_key(const json &entry, bool is_interface) {
	if(is_interface) {
		if(entry.contains("interface_id") && entry.at("interface_id").is_number_integer()) {
			return "interface:" + std::to_string(entry.at("interface_id").get<int>());
		}
		if(entry.contains("name") && entry.at("name").is_string()) {
			return "interface:name:" + entry.at("name").get<std::string>();
		}
		return "interface:unknown";
	}

	const auto stream_key = entry.value("stream_key", std::string{});
	const auto flow_key = entry.value("flow_key", std::string{});
	if(flow_key.empty()) return "stream:" + stream_key;
	return "flow:" + stream_key + "::" + flow_key;
}

json metric_sample_projector::make_target(const json &entry, bool is_interface) {
	const auto key = target_key(entry, is_interface);
	json target{
		{"kind", is_interface ? "interface" : (entry.value("flow_key", std::string{}).empty() ? "stream" : "flow")},
		{"key", key},
		{"scope", entry.value("scope", json::object())},
	};

	if(is_interface) {
		if(entry.contains("interface_id")) target["interface_id"] = entry["interface_id"];
		if(entry.contains("name")) target["interface_name"] = entry["name"];
		if(entry.contains("link")) target["link"] = entry["link"];
		return target;
	}

	if(entry.contains("stream_key")) target["stream_key"] = entry["stream_key"];
	if(entry.contains("flow_key") && entry["flow_key"].is_string() && !entry["flow_key"].get<std::string>().empty()) {
		target["flow_key"] = entry["flow_key"];
	}
	if(entry.contains("proto")) target["proto"] = entry["proto"];
	if(entry.contains("role")) target["role"] = entry["role"];
	if(entry.contains("endpoint")) target["endpoint"] = entry["endpoint"];
	if(entry.contains("interface_id")) target["interface_id"] = entry["interface_id"];
	if(entry.contains("interface_name")) target["interface_name"] = entry["interface_name"];
	return target;
}

bool metric_sample_projector::is_stat_object(const json &value) {
	if(!value.is_object()) return false;
	static const char *keys[] = {"value", "avg", "min", "max", "count", "bps", "pps", "seconds", "total", "window"};
	for(const char *key : keys) {
		if(value.contains(key) && value.at(key).is_number()) return true;
	}
	return false;
}

json metric_sample_projector::make_template(const json &value) {
	if(value.is_array()) return json::array();
	if(is_stat_object(value)) return nullptr;
	if(!value.is_object()) return value;

	json out = json::object();
	for(auto it = value.begin(); it != value.end(); ++it) {
		const json child = make_template(it.value());
		if(child.is_null()) continue;
		if(child.is_object() && child.empty()) continue;
		if(child.is_array() && child.empty()) continue;
		out[it.key()] = child;
	}
	return out;
}

double metric_sample_projector::first_stat_value(const json &record) {
	static const char *keys[] = {"value", "bps", "pps", "seconds", "total", "window", "avg", "min", "max"};
	for(const char *key : keys) {
		if(record.contains(key) && record.at(key).is_number()) return record.at(key).get<double>();
	}
	return 0.0;
}

void metric_sample_projector::collect_values(const std::string &prefix,
                                             const json &value,
                                             std::map<std::string, double> &out) {
	if(is_stat_object(value)) {
		out[prefix] = first_stat_value(value);
		return;
	}
	if(value.is_number()) {
		out[prefix] = value.get<double>();
		return;
	}
	if(!value.is_object() || value.is_array()) return;
	for(auto it = value.begin(); it != value.end(); ++it) {
		const auto child_prefix = prefix.empty() ? it.key() : prefix + "." + it.key();
		collect_values(child_prefix, it.value(), out);
	}
}

void metric_sample_projector::set_path(json &out, const std::string &path, json value) {
	json *cursor = &out;
	std::size_t start = 0;
	while(true) {
		const std::size_t dot = path.find('.', start);
		const auto part = path.substr(start, dot == std::string::npos ? std::string::npos : dot - start);
		if(dot == std::string::npos) {
			(*cursor)[part] = std::move(value);
			return;
		}
		if(!cursor->contains(part) || !(*cursor)[part].is_object()) (*cursor)[part] = json::object();
		cursor = &(*cursor)[part];
		start = dot + 1;
	}
}

json metric_sample_projector::make_sample(double now,
                                          const json &entry,
                                          bool is_interface,
                                          const json &source_record) const {
	const auto target = make_target(entry, is_interface);
	const auto source_id = source_record.value("record_id", std::string{});
	return json{
		{"schema_version", 3},
		{"record_type", "metric_sample"},
		{"record_id", source_id + ":sample:" + target.value("key", std::string{})},
		{"source_record_id", source_id},
		{"capture_id", source_record.value("capture_id", std::string{})},
		{"time", now},
		{"resolution_sec", 1},
		{"target", target},
		{"metrics", entry},
	};
}

void metric_sample_projector::append_entries(double now,
                                              const json::array_t &entries,
                                              bool is_interface,
                                              const json &source_record) {
	for(const auto &entry : entries) {
		if(!entry.is_object()) continue;
		auto sample = make_sample(now, entry, is_interface, source_record);
		m_samples_1s_writer->dump_at(now, sample);
		update_rollup(sample);
	}
}

void metric_sample_projector::update_rollup(const json &sample) {
	const double time = sample.value("time", 0.0);
	const double bucket_start = minute_floor(time);
	if(!m_bucket.has_value()) {
		m_bucket = minute_bucket{.bucket_start = bucket_start, .bucket_end = bucket_start + 60.0, .subjects = {}};
	}
	else if(bucket_start != m_bucket->bucket_start) {
		flush_bucket();
		m_bucket = minute_bucket{.bucket_start = bucket_start, .bucket_end = bucket_start + 60.0, .subjects = {}};
	}
	observe_sample(sample);
}

void metric_sample_projector::observe_sample(const json &sample) {
	if(!m_bucket.has_value()) return;
	const auto target = sample.value("target", json::object());
	const auto key = target.value("key", std::string{});
	if(key.empty()) return;

	auto &acc = m_bucket->subjects[key];
	if(acc.target.is_null()) acc.target = target;
	const auto &metrics = sample.value("metrics", json::object());
	if(acc.template_metrics.is_null()) acc.template_metrics = make_template(metrics);
	acc.capture_id = sample.value("capture_id", std::string{});
	acc.source_record_id = sample.value("source_record_id", std::string{});

	std::map<std::string, double> values;
	collect_values("", metrics, values);
	for(const auto &[path, value] : values) {
		acc.stats_by_path[path].add(value);
		acc.last_by_path[path] = value;
	}
}

void metric_sample_projector::flush_bucket() {
	if(!m_bucket.has_value()) return;
	for(const auto &[key, acc] : m_bucket->subjects) {
		json rolled_metrics = acc.template_metrics.is_null() ? json::object() : acc.template_metrics;
		for(const auto &[path, stats] : acc.stats_by_path) {
			json stat{
				{"value", stats.avg()},
				{"avg", stats.avg()},
				{"min", stats.min},
				{"max", stats.max},
				{"count", stats.count},
			};
			if(const auto last = acc.last_by_path.find(path); last != acc.last_by_path.end()) stat["last"] = last->second;
			set_path(rolled_metrics, path, std::move(stat));
		}
		json sample{
			{"schema_version", 3},
			{"record_type", "metric_sample"},
			{"record_id", "rollup:" + std::to_string(static_cast<long long>(m_bucket->bucket_end)) + ":" + std::to_string(m_rollup_sequence++) + ":" + key},
			{"source_record_id", acc.source_record_id},
			{"capture_id", acc.capture_id},
			{"time", m_bucket->bucket_end},
			{"bucket_start", m_bucket->bucket_start},
			{"bucket_end", m_bucket->bucket_end},
			{"resolution_sec", 60},
			{"target", acc.target},
			{"metrics", std::move(rolled_metrics)},
		};
		m_samples_1m_writer->dump_at(m_bucket->bucket_end, sample);
	}
	m_bucket.reset();
}
